    ["Hover an equipment slot in the Character frame for a compact flyout of compatible bag items, or modifier-click for a larger pinnable picker. Click an item to equip it (out-of-combat)."] = "在角色框架中將滑鼠移到裝備欄位上會顯示相容背包物品的精簡彈出列，或以輔助鍵點擊開啟較大的可固定挑選器。點擊物品即可裝備（脫離戰鬥時）。",
    ["Flyout on hover"] = "滑鼠移過時彈出",
