    ["Dialog Popups"] = "對話彈出視窗",
    ["Restyles Blizzard's confirmation dialogs (logout countdown, delete item, resurrect, group invite) to match the dark look."] = "重新設計暴雪確認對話框的樣式（登出倒數、刪除物品、復活、隊伍邀請），以符合暗色外觀。",
    ["|cffaaaaaaRestyles Blizzard's confirmation dialogs — logout countdown, delete item, resurrect, group invite — to match the dark look.|r"] = "|cffaaaaaa重新設計暴雪確認對話框的樣式 — 登出倒數、刪除物品、復活、隊伍邀請 — 以符合暗色外觀。|r",
    ["Accent strip"] = "標色條",
    ["Draws a thin accent gradient along the top edge of each dialog."] = "沿著每個對話框的上緣繪製一道細的標色漸層。",
    ["Addon Skins"] = "插件外觀",
    ["Restyles supported third-party addon windows to match the dark look: error list, quest tracker, loot browser, profiler and more."] = "重新設計支援的第三方插件視窗樣式，以符合暗色外觀：錯誤列表、任務追蹤器、拾取瀏覽器、效能分析器等等。",
    ["|cffaaaaaaRestyles the windows of supported addons to the dark look. Skins apply when the addon is loaded; turning one off needs a /reload (the quest tracker restores live).|r"] = "|cffaaaaaa將支援的插件視窗重新設計為暗色外觀。外觀會在插件載入時套用；關閉某項需要 /reload（任務追蹤器會即時還原）。|r",
    ["not loaded"] = "未載入",
    ["Dark window skin"] = "暗色視窗外觀",
    ["Restyles the whole friends window dark with purple accents. Turning it off needs a /reload to restore Blizzard's frame."] = "將整個好友視窗重新設計為帶紫色標色的暗色。關閉時需要 /reload 才能還原暴雪的框架。",
    ["Class color names"] = "職業顏色名稱",
    ["Colors each online friend's name by their class."] = "依職業為每位線上好友的名稱著色。",
    ["Show class icons"] = "顯示職業圖示",
    ["Shows a class icon next to online WoW friends (in-game and Battle.net)."] = "在線上魔獸世界好友（遊戲內與Battle.net）名稱旁顯示職業圖示。",
    ["Class icon style"] = "職業圖示樣式",
    ["Blizzard crests"] = "暴雪徽章",
    ["Circles"] = "圓形",
    ["Squares"] = "方形",
    ["Show status dot"] = "顯示狀態圓點",
    ["A coloured dot after the name: green online, yellow away, red busy, grey offline."] = "名稱後方的彩色圓點：綠色為線上，黃色為離開，紅色為忙碌，灰色為離線。",
    ["Show friend notes"] = "顯示好友備註",
    ["Shows your saved note for the friend in grey under their name."] = "在好友名稱下方以灰色顯示你為該好友儲存的備註。",
    ["Faction"] = "陣營",
    ["Faction accent on realm line"] = "伺服器欄陣營色調",
    ["Tints the realm/zone line red (Horde) or blue (Alliance)."] = "將伺服器/區域欄位染成紅色（部落）或藍色（聯盟）。",
    ["Faction row tint"] = "陣營列底色",
    ["Adds a subtle red/blue background tint to each online friend's row."] = "為每位線上好友的列加上淡淡的紅/藍背景色調。",
    ["Invites"] = "邀請",
