    ["Below this many seconds the countdown switches to the warn color; 0 turns the warn color off."] = "低於此秒數時倒數會切換為警告顏色；0 為關閉警告顏色。",
    ["Warn color..."] = "警告顏色…",
    ["Glow while ready"] = "就緒時發光",
    ["A steady glow while the cooldown is ready - and, for spells, only while it is actually usable (enough mana etc.)."] = "冷卻就緒時持續發光——法術則僅在實際可使用時（法力足夠等）才發光。",
    ["Glow color"] = "光效顏色",
    ["Show keybinds"] = "顯示按鍵設定",
    ["Shows the key the spell/item is bound to on your action bars. Macros are not matched; stance pages follow the main bar."] = "顯示該法術/物品在快捷列上所綁定的按鍵。巨集不會被比對；姿態頁面依照主快捷列。",
