    ["Only show while on cooldown"] = "僅在冷卻時顯示",
    ["Hides ready icons; they reappear when on cooldown."] = "隱藏就緒的圖示；進入冷卻時會重新出現。",
    ["Show countdown text"] = "顯示倒數文字",
    ["Show stacks"] = "顯示堆疊數",
    ["  |cffaa5555(other class)|r"] = "  |cffaa5555（其他職業）|r",
    ["Edit mode — move the cooldown bars"] = "編輯模式——移動冷卻列",
    ["Stop editing — lock the cooldown bars"] = "結束編輯——鎖定冷卻列",
    ["Unlocks just the cooldown bars so you can drag them. Arrow keys fine-tune; right-click a purple box for X/Y. (To move ALL VuloUI windows, use 'Unlock Mode' in Global.)"] = "只解鎖冷卻列，讓你可以拖曳它們。方向鍵可微調；在紫色方框上按右鍵可設定 X/Y。（若要移動所有VuloUI視窗，請使用「全域」中的「解鎖模式」。）",
    ["Hide cooldowns under (sec)"] = "隱藏冷卻門檻（秒）",
    ["Cooldowns at or below this are ignored. 1.5 hides the global cooldown; raise it to also hide short cooldowns; 0 shows everything."] = "等於或低於此值的冷卻會被忽略。1.5 可隱藏公共冷卻；調高則連短冷卻也一併隱藏；0 則全部顯示。",
    ["Move earlier"] = "往前移",
    ["Move later"] = "往後移",
    ["Stack / reagent position"] = "堆疊 / 材料位置",
    ["Stack / reagent size"] = "堆疊 / 材料大小",
