    ["Bottom right"] = "右下",
    ["Bottom left"] = "左下",
    ["Top right"] = "右上",
    ["Top left"] = "左上",
    ["Show reagent counts"] = "顯示材料數量",
    ["Shows each spell's OWN reagent count — Soul Shards on Soul Fire, Infernal Stone on Inferno, etc. Spells without a reagent show nothing. Needs 'Show stacks' on."] = "顯示每個法術「本身」的材料數量——靈魂之火顯示靈魂碎片，地獄火顯示地獄火之石等等。沒有材料的法術不會顯示。需要開啟「顯示堆疊數」。",
    ["Anchor"] = "錨點",
    ["Anchor to"] = "錨定至",
    ["Pin this bar to a unit frame, the minimap, or another group's bar — it then moves with it. Drag the bar to detach."] = "將此列固定到單位框架、小地圖或另一個群組的列——之後它會跟著移動。拖曳此列即可解除固定。",
