    ["How much is cut off each edge of the icon. 0 shows the whole icon including the border baked into its artwork."] = "從圖示每個邊裁掉多少。0 顯示完整圖示，包含圖片本身的邊框。",
    ["Cooldown swipe darkness"] = "冷卻掃描暗度",
    ["Only in combat"] = "僅在戰鬥中",
