    ["Hide while mounted"] = "騎乘時隱藏",
    ["Only in instances"] = "僅在副本中",
    ["Dim icon while on cooldown"] = "冷卻時圖示變暗",
    ["Flash when ready"] = "就緒時閃爍",
    ["Saves named snapshots of your action bars, macros and keybindings, and restores them with one click."] = "儲存你的快捷列、巨集與按鍵設定的具名快照，並可一鍵還原。",
    ["|cffaaaaaaSaves your complete bar setup (all action slots, macros, keybindings) as a named profile and restores it with one click — e.g. PvP and Raid layouts, or to copy a setup to a twink (account-wide storage).|r"] = "|cffaaaaaa將你完整的快捷列配置（所有動作格、巨集、按鍵設定）儲存為具名設定檔，並可一鍵還原——例如PvP與團隊版面，或把配置複製到小號（帳號共用儲存）。|r",
    ["Load"] = "載入",
    ["Save current setup"] = "儲存目前配置",
    ["Please enter a profile name first."] = "請先輸入設定檔名稱。",
    ["|cff888888No profiles saved yet.|r"] = "|cff888888尚未儲存任何設定檔。|r",
    ["Also restore macros"] = "一併還原巨集",
    ["Rewrites saved macros by name (existing ones are updated, missing ones created)."] = "依名稱重寫已儲存的巨集（既有的會更新，缺少的會建立）。",
    ["Also restore keybindings"] = "一併還原按鍵設定",
    ["Load profile"] = "載入設定檔",
    ["Overwrite with current setup"] = "以目前配置覆寫",
    ["Replaces the selected profile with your current bars/macros/bindings."] = "以你目前的快捷列/巨集/按鍵設定取代所選的設定檔。",
    ["Note: profile '%s' was saved on another class (%s)."] = "注意：設定檔「%s」是在另一個職業（%s）上儲存的。",
    ["Flight Timer"] = "飛行計時器",
    ["|cffff8800Flight route database not loaded.|r Fully restart WoW (a /reload is not enough after an update) so the flight times work."] = "|cffff8800飛行路線資料庫未載入。|r 請完全重新啟動魔獸世界（更新後只用 /reload 是不夠的），飛行時間才能運作。",
    ["Show flight time bar"] = "顯示飛行時間列",
    ["Shows destination and remaining time while on a taxi. The first flight of a route is learned, then you get a draining countdown."] = "在搭乘飛行路線時顯示目的地與剩餘時間。每條路線的第一次飛行會被記錄，之後就會顯示遞減的倒數。",
    ["Flight: %s (%s)"] = "飛行：%s（%s）",
    ["Print flight time to chat"] = "將飛行時間輸出到聊天",
    ["After landing, prints the measured flight time."] = "降落後輸出測得的飛行時間。",
    ["Reset learned times"] = "重設已記錄的時間",
    ["Deletes all saved route durations."] = "刪除所有已儲存的路線時間。",
    ["Learned flight times reset."] = "已記錄的飛行時間已重設。",
    ["|cffffffffFLIGHT TIME|r"] = "|cffffffff飛行時間|r",
    ["Flight timer: x=%.0f, y=%.0f"] = "飛行計時器：x=%.0f, y=%.0f",
    ["Flight timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "飛行計時器移動模式已啟動。|cff9b6cff拖曳|r或使用|cff9b6cff方向鍵|r（SHIFT = 5像素）。",
    ["Flight timer mover disabled."] = "飛行計時器移動模式已停用。",
    ["Flight debug on — take a flight, the resolution appears in the chat."] = "飛行除錯已開啟——搭乘一次飛行，解析結果會顯示在聊天中。",
    ["Flight debug off."] = "飛行除錯已關閉。",
    ["LazyVulo"] = "LazyVulo",
    ["Training"] = "Training",
    ["Group Board"] = "組隊看板",
    ["Apexis Relic memory minigame helper (Ogri'la dailies): record the flashing color sequence, always see what to click next."] = "阿佩克希斯遺物記憶小遊戲輔助（歐格利拉每日任務）：記錄閃爍的顏色順序，隨時看到下一個該點什麼。",
    ["Green relic"] = "綠色遺物",
