    ["Red relic"] = "紅色遺物",
    ["Left click: remove this entry.\nRight click: remove this and all later entries."] = "左鍵：移除此項目。\n右鍵：移除此項目與其後所有項目。",
    ["Click to record this color."] = "點擊以記錄此顏色。",
    ["Hotkey: %s"] = "快速鍵：%s",
    ["LazyVulo is disabled."] = "LazyVulo 已停用。",
    ["|cffaaaaaaHelper for the Apexis Relic memory minigame (Ogri'la dailies). Record the flashing sequence with the buttons or hotkeys; the first icon is always your next click. Correct clicks are consumed automatically, wrong clicks are restored.|r"] = "|cffaaaaaa阿佩克希斯遺物記憶小遊戲（歐格利拉每日任務）的輔助工具。用按鈕或快速鍵記錄閃爍的順序；第一個圖示永遠是你下一個要點的。點對了會自動消去，點錯了則會還原。|r",
    ["|cffaaaaaaOpen manually with /lazyvulo or /lv.|r"] = "|cffaaaaaa可用 /lazyvulo 或 /lv 手動開啟。|r",
    ["Auto-show at the Apexis Relic"] = "在阿佩克希斯遺物旁自動顯示",
    ["Opens the window automatically when you start the relic minigame."] = "開始遺物小遊戲時自動開啟視窗。",
