    ["Marks & threshold"] = "刻度與門檻",
    ["Hash marks"] = "刻度線",
    ["Comma-separated values, e.g. 30,60 — draws a line at each (great for tick or breakpoint marks)."] = "以逗號分隔的數值，例如 30,60——會在每個位置畫一條線（很適合標示回復間隔或臨界點）。",
