    ["Auto-closes trade windows opened by players who are not in your guild or on your friends list. Trades you start yourself are not affected."] = "自動關閉由非公會成員且不在你好友名單上的玩家所開啟的交易視窗。你自己發起的交易不受影響。",
    ["|cffffd200[QoL]|r Blocked group invite from %s (not guild/friend)."] = "|cffffd200[QoL]|r 已封鎖來自 %s 的隊伍邀請（非公會/好友）。",
