    ["Adds a tab to your spell book that lists the abilities you can still learn from your class trainer, grouped by level. Open the book icon below the spell schools."] = "在法術書中新增一個分頁，列出你還能向職業訓練師學習的技能，並依等級分組。點擊法術類別下方的書本圖示開啟。",
    ["|cffaaaaaaAdds a tab to your spell book (the book icon on the side, below the spell schools) listing every ability you can still learn from your class trainer — grouped by status and coloured by level. No need to visit a trainer.|r"] = "|cffaaaaaa在法術書中新增一個分頁（側邊、法術類別下方的書本圖示），列出你還能向職業訓練師學習的所有技能——依狀態分組並依等級著色。不必特地跑去找訓練師。|r",
    ["Available now"] = "現在可學",
