    ["Power Bar mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Move' again to finish."] = "能量條移動模式已啟動。|cff9b6cff拖曳紫色方框|r或使用|cff9b6cff方向鍵|r（SHIFT = 5像素）。再次點擊「解鎖 / 移動」即可完成。",
    ["Power Bar mover disabled."] = "能量條移動模式已停用。",
    ["|cffaaaaaaResource bar that follows your class automatically (Mana / Rage / Energy). Druids switch with their form: Bear = Rage, Cat = Energy, otherwise Mana.|r"] = "|cffaaaaaa會自動依你的職業變化的資源條（法力 / 怒氣 / 能量）。德魯伊會隨形態切換：熊形 = 怒氣，貓形 = 能量，其他為法力。|r",
    ["v%s loaded. /vcui to open."] = "v%s 已載入。輸入 /vcui 開啟。",
