    ["Profiles"] = "設定檔",
    ["Manage profiles with different settings. A default profile can be assigned per class and is loaded automatically on login."] = "管理不同設定的設定檔。可為每個職業指定預設設定檔，登入時會自動載入。",
    ["Active Profile"] = "使用中的設定檔",
    ["You are currently using: |cff9b6cff%s|r  (Class: %s)"] = "你目前使用：|cff9b6cff%s|r  （職業：%s）",
    ["Switch Profile"] = "切換設定檔",
    ["Profile for this character"] = "此角色的設定檔",
    ["|cffaaaaaaPins a profile to THIS character only. At login it beats the class assignment and the account-wide selection - so every character can keep its own minimap, bars and window settings.|r"] = "|cffaaaaaa只將設定檔固定給「這個」角色。登入時它的優先權高於職業指定與帳號共用的選擇——因此每個角色都能保有自己的小地圖、快捷列與視窗設定。|r",
    ["This character"] = "此角色",
    ["Create New Profile"] = "建立新設定檔",
    ["Name"] = "名稱",
    ["Copy Settings From"] = "複製設定來源",
    ["- empty profile (defaults) -"] = "- 空白設定檔（預設值） -",
