    ["Error."] = "錯誤。",
    ["Share Profile"] = "分享設定檔",
    ["|cffaaaaaaExport the current profile as a text string - as a backup or to share it. Importing always creates a NEW profile and never overwrites anything.|r"] = "|cffaaaaaa將目前設定檔匯出為文字字串——可作為備份或分享出去。匯入時一律會建立「新的」設定檔，絕不會覆寫任何東西。|r",
