    ["|cffff5555Default profile cannot be deleted.|r"] = "|cffff5555預設設定檔無法刪除。|r",
    ["Apply to Active Class"] = "套用至目前職業",
    ["Sets the current profile as the default for %s."] = "將目前設定檔設為 %s 的預設設定檔。",
    ["'%s' is now the default profile for %s."] = "「%s」現在是 %s 的預設設定檔。",
    ["Per-class profile (quick setup)"] = "各職業設定檔（快速設定）",
    ["|cffaaaaaaOne click: makes a profile named after your class (copied from the current one) and loads it for this class automatically. Run it once on each character — every class then keeps its own cooldown bars, frames and settings.|r"] = "|cffaaaaaa一鍵完成：建立一個以你職業命名的設定檔（從目前的複製而來），並自動為此職業載入。在每個角色上執行一次——每個職業就能保有自己的冷卻列、框架與設定。|r",
