    ["Profile Assignment per Class"] = "各職業設定檔指定",
    ["Choose a default profile for each class. When logging in with a character of that class, the profile will be loaded automatically."] = "為每個職業選擇一個預設設定檔。以該職業的角色登入時，會自動載入該設定檔。",
