    ["Show Minimap Button"] = "顯示小地圖按鈕",
    ["Toggle the VuloClassicUI button on the minimap."] = "切換小地圖上的 VuloClassicUI 按鈕。",
    ["Show CPU Usage in Header"] = "在標題列顯示 CPU 使用率",
    ["Shows total CPU usage of all active addons (plus VuloClassicUI's own share) at the top of the config header.\n\n|cffaaaaaaRequires /reload after toggling.\n\nNote: Enables WoW's scriptProfile CVar, which costs ~3-5% performance — that's the price for WoW collecting this data at all.|r"] = "在設定標題列頂端顯示所有啟用插件的 CPU 使用總量（含 VuloClassicUI 自身的部分）。\n\n|cffaaaaaa切換後需要 /reload。\n\n注意：會啟用 WoW 的 scriptProfile CVar，約損耗 3-5% 效能 — 這是 WoW 收集這些資料必須付出的代價。|r",
    ["Script profiling changed. /reload required for the CPU display to update."] = "指令碼分析已變更。CPU 顯示需要 /reload 才會更新。",
    ["Reload now"] = "立即重載",
    ["Later"] = "稍後",
    ["Shows a button on the minimap to quickly open VuloClassicUI. Shift+drag moves the button."] = "在小地圖上顯示按鈕以快速開啟 VuloClassicUI。Shift+拖曳可移動按鈕。",
