    ["|cffffffffShift+drag:|r Move button"] = "|cffffffffShift+拖曳：|r 移動按鈕",
    ["Open Options"] = "開啟選項",
    ["Show button on minimap"] = "在小地圖上顯示按鈕",
    ["If off, the button is completely hidden."] = "關閉時按鈕會完全隱藏。",
    ["Distance from center"] = "與中心的距離",
    ["Angle (degrees)"] = "角度（度）",
    ["Tip: You can also move the button directly on the minimap — hold Shift and drag it to the desired position."] = "提示：你也可以直接在小地圖上移動按鈕 — 按住 Shift 並拖曳到想要的位置。",
    ["Font Bars"] = "狀態條字型",
    ["Smaller font sizes for Player/Target/Pet Health & Mana bars, optionally hide TargetFrameBackground."] = "玩家/目標/寵物的生命與法力條使用較小字型，可選擇隱藏 TargetFrameBackground。",
