    ["Font size for 'Damage', 'Dodge', 'Miss' on the pet."] = "寵物身上「傷害」、「閃躲」、「未命中」的字型大小。",
    ["Only affect Player/Target/Pet bars"] = "僅影響玩家/目標/寵物狀態條",
    ["If off: all TextStatusBars in the UI are overridden with the sizes above (may interfere with other addons)."] = "關閉時：介面中所有 TextStatusBar 都會套用上述大小（可能與其他插件衝突）。",
    ["Hide TargetFrame background"] = "隱藏目標框架背景",
    ["Permanently hides the dark background element of the TargetFrame."] = "永久隱藏目標框架的深色背景元件。",
    ["Target Frame"] = "目標框架",
    ["|cffaaaaaaAdds the modern Target/Focus frame extras the default Anniversary UI is missing - all cosmetic, no taint.|r"] = "|cffaaaaaa加入預設週年慶介面缺少的現代目標/專注目標框架附加元素 - 純外觀，不會造成污染。|r",
    ["Numeric threat %"] = "仇恨百分比數值",
    ["Shows your threat percentage on the target (and focus) above the frame, coloured by threat status."] = "在框架上方顯示你對目標（及專注目標）的仇恨百分比，並依仇恨狀態上色。",
    ["Threat glow"] = "仇恨光暈",
    ["Glows the target (and focus) frame in yellow/orange/red as your threat rises."] = "隨著仇恨上升，讓目標（及專注目標）框架發出黃/橘/紅色光暈。",
    ["Rare-Elite border"] = "稀有精英邊框",
    ["Shows the winged silver-dragon Rare-Elite border on rare-elite mobs."] = "在稀有精英怪物上顯示帶翼銀龍的稀有精英邊框。",
    ["Class icon on player targets"] = "玩家目標顯示職業圖示",
    ["Shows the target's class crest on the frame when you target a player."] = "當你選定玩家為目標時，在框架上顯示目標的職業徽章。",
    ["Also apply to the Focus frame"] = "同時套用至專注目標框架",
    ["Health"] = "生命",
    ["Show real NPC health"] = "顯示 NPC 真實生命值",
