    ["Player Castbar"] = "玩家施法條",
    ["Player castbar with two modes: Original (Blizzard bar extended) or Custom castbar (VUI style)."] = "玩家施法條，兩種模式：原始（延伸的暴雪施法條）或自訂施法條（VUI 樣式）。",
    ["|cffffffffCASTBAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffff施法條|r\n|cffaaaaaa拖曳或方向鍵|r",
    ["Castbar position: x=%.0f, y=%.0f"] = "施法條位置：x=%.0f, y=%.0f",
    ["|cff9b6cffMind Flay|r"] = "|cff9b6cff心靈鞭笞|r",
