    ["Original (Blizzard bar extended)"] = "原始（延伸的暴雪施法條）",
    ["Custom Castbar (VUI style)"] = "自訂施法條（VUI 樣式）",
    ["Castbar mode switched to |cff9b6cffOriginal|r. |cffffff00/reload|r recommended so the default bar works normally again."] = "施法條模式已切換為 |cff9b6cff原始|r。建議執行 |cffffff00/reload|r，讓預設施法條恢復正常運作。",
    ["Castbar mode switched to |cff9b6cffVUI Style|r."] = "施法條模式已切換為 |cff9b6cffVUI 樣式|r。",
    ["|cffaaaaaaMode switch: A /reload may be required after switching so the default bar works normally again.|r"] = "|cffaaaaaa模式切換：切換後可能需要 /reload，預設施法條才能恢復正常運作。|r",
