    ["Hide stack/charge numbers on action buttons"] = "隱藏快捷列按鈕上的堆疊/充能數字",
    ["Hides the small boxes with numbers at the top right (item stacks, charges, cooldown seconds for long CDs)."] = "隱藏右上角帶數字的小方框（物品堆疊、充能、長冷卻的秒數）。",
