    ["Inspect state manually reset."] = "觀察狀態已手動重設。",
    ["NotifyInspect hook: %s\nInspectFrame hook: %s"] = "NotifyInspect 掛鉤：%s\nInspectFrame 掛鉤：%s",
    ["|cff66ff66active|r"] = "|cff66ff66啟用中|r",
    ["|cffff8800waiting|r"] = "|cffff8800等待中|r",
    ["|cffff8800waiting for Blizzard_InspectUI|r"] = "|cffff8800等待 Blizzard_InspectUI|r",
    ["|cffaaaaaaWhat the fix does: tracks active inspects with a timestamp, repaints late-arriving item data, re-requests an all-empty inspect once, and calls ClearInspectPlayer() on close + on timeout. Prevents a stuck state from blocking all subsequent inspects.|r"] = "|cffaaaaaa此修正的作用：以時間戳記追蹤進行中的觀察、重繪延遲抵達的物品資料、對完全空白的觀察重新請求一次，並在關閉時與逾時後呼叫 ClearInspectPlayer()。可避免卡住的狀態阻擋後續所有觀察。|r",
    ["Auto-retry empty inspects"] = "自動重試空白觀察",
    ["After the server answers, the item slots are repainted again shortly after (data often arrives late). If the window is still completely empty, the inspect is automatically requested one more time."] = "伺服器回應後，稍後會再次重繪物品欄位（資料常延遲抵達）。若視窗仍完全空白，會自動再請求一次觀察。",
    ["|cffaaaaaaStatus: %s|r"] = "|cffaaaaaa狀態：%s|r",
    ["|cff66ff66Hook active|r"] = "|cff66ff66掛鉤啟用中|r",
    ["LFG Browse Nil Fix"] = "LFG 瀏覽 Nil 修正",
    ["Catches Lua errors in the Anniversary Group Finder (LFGBrowseSearchEntry_Update with stale resultIDs). Prevents chat spam and broken browse lists."] = "攔截週年慶隊伍搜尋器中的 Lua 錯誤（LFGBrowseSearchEntry_Update 使用過期的 resultID）。可避免聊天洗版與瀏覽清單損毀。",
    ["|cffffff00[VuloClassicUI]|r Blizzard LFG browse error caught (stale entry skipped)."] = "|cffffff00[VuloClassicUI]|r 已攔截暴雪 LFG 瀏覽錯誤（已略過過期項目）。",
    ["Chat message on first error"] = "首次錯誤時發送聊天訊息",
    ["Shows a brief message once per session in chat when an LFG browse error was caught."] = "攔截到 LFG 瀏覽錯誤時，每次遊戲階段在聊天中顯示一次簡短訊息。",
    ["This fix wraps Blizzard's |cffffffffLFGBrowseSearchEntry_Update|r function in a protected call (xpcall). When the entry crashes due to a stale resultID (\"searchResultInfo nil\"), the error is swallowed — Blizzard's next refresh automatically cleans up the list entry."] = "此修正將暴雪的 |cffffffffLFGBrowseSearchEntry_Update|r 函式包在保護呼叫（xpcall）中。當項目因過期的 resultID 而當機（\"searchResultInfo nil\"）時，錯誤會被吞下 — 暴雪的下一次重新整理會自動清理該清單項目。",
    ["waiting for Blizzard_GroupFinder_VanillaStyle"] = "等待 Blizzard_GroupFinder_VanillaStyle",
    ["Guild News Nil Fix"] = "公會動態 Nil 修正",
    ["Catches Lua errors in guild news entries (typically \"formatString\" or \"GuildUtil\") and replaces broken entries with a fallback text instead of letting the whole panel break."] = "攔截公會動態項目中的 Lua 錯誤（通常是 \"formatString\" 或 \"GuildUtil\"），並以備用文字取代損毀的項目，避免整個面板失效。",
    ["|cffff8080Invalid guild news entry|r"] = "|cffff8080無效的公會動態項目|r",
    ["|cffffff00[VuloClassicUI]|r Blizzard guild news error caught (fallback applied)."] = "|cffffff00[VuloClassicUI]|r 已攔截暴雪公會動態錯誤（已套用備用文字）。",
    ["Shows a brief message once per session in chat when a guild news error was caught."] = "攔截到公會動態錯誤時，每次遊戲階段在聊天中顯示一次簡短訊息。",
    ["This fix wraps Blizzard's |cffffffffGuildNewsButton_SetNews|r function in a protected call (xpcall). When an entry throws a known error (\"formatString\" or \"GuildUtil\"), the entry is replaced with a fallback text \"Invalid guild news entry\" — the panel remains usable."] = "此修正將暴雪的 |cffffffffGuildNewsButton_SetNews|r 函式包在保護呼叫（xpcall）中。當項目擲出已知錯誤（\"formatString\" 或 \"GuildUtil\"）時，該項目會被替換為備用文字 \"無效的公會動態項目\" — 面板仍可正常使用。",
    ["waiting for Blizzard_Communities"] = "等待 Blizzard_Communities",
    ["Auction Price Fix"] = "拍賣價格修正",
    ["Fixes a nil error in the German auction house UI (PriceDropdown not defined)."] = "修正德文拍賣場介面中的 nil 錯誤（PriceDropdown 未定義）。",
    ["This fix addresses a known bug in the German WoW localization: the auction house UI references a \"PriceDropdown\" element that was never defined, which causes Lua errors when opening the auction house."] = "此修正處理德文 WoW 在地化的已知錯誤：拍賣場介面參照了一個從未定義的 \"PriceDropdown\" 元件，導致開啟拍賣場時產生 Lua 錯誤。",
    ["|cffaaaaaaCurrent locale: %s|r"] = "|cffaaaaaa目前語系：%s|r",
    ["|cffaaaaaaThe fix only applies on German clients (deDE). On other languages the module is inactive.|r"] = "|cffaaaaaa此修正僅套用於德文客戶端（deDE）。其他語言下此模組不作用。|r",
    ["|cff66ff66applied|r"] = "|cff66ff66已套用|r",
