    ["Also apply font to Blizzard mob FCT"] = "字型也套用至暴雪怪物浮動戰鬥文字",
    ["Additionally sets DAMAGE_TEXT_FONT globally - changes the font of the damage numbers above mobs/pets. Requires /reload to take effect."] = "另外全域設定 DAMAGE_TEXT_FONT - 變更怪物/寵物上方傷害數字的字型。需要 /reload 才會生效。",
    ["Interrupted"] = "已中斷",
    ["Parried/Dodged/Missed"] = "招架/閃躲/未命中",
