    ["Engine FCT Scale"] = "引擎浮動戰鬥文字縮放",
    ["Damage numbers above mob/pet — bitmap scaling."] = "怪物/寵物上方的傷害數字 — 點陣圖縮放。",
    ["Center"] = "置中",
    ["Unlock / Position"] = "解鎖 / 位置",
    ["Trinkets"] = "飾品",
    ["Two trinket slots on screen with cooldown display, dropdown selection and auto-queue."] = "螢幕上的兩個飾品欄位，含冷卻顯示、下拉選擇與自動佇列。",
    ["|cffaaaaaaTwo trinket slots with cooldown, dropdown selection and auto-queue.|nLeft click = use, right click = dropdown.|r"] = "|cffaaaaaa兩個飾品欄位，含冷卻、下拉選擇與自動佇列。|n左鍵 = 使用，右鍵 = 下拉選單。|r",
    ["Show frame"] = "顯示框架",
    ["Hides or shows the two trinket slots. Auto-queue continues to run while hidden."] = "隱藏或顯示兩個飾品欄位。隱藏時自動佇列仍會繼續運作。",
    ["Position locked"] = "鎖定位置",
    ["If on, the frame cannot be accidentally moved."] = "開啟時框架無法被意外移動。",
    ["Size"] = "大小",
    ["Scales the trinket slots."] = "縮放飾品欄位。",
    ["Character Panel"] = "角色面板",
    ["Dark Skin"] = "深色外觀",
    ["The dark look of the UI in one place: a built-in dark skin for action buttons and WeakAuras icons, plus an optional Dark Mode that darkens Blizzard's default frames, minimap and bars."] = "介面深色外觀的統一設定：內建的快捷列按鈕與 WeakAuras 圖示深色外觀，以及可選的深色模式，讓暴雪預設框架、小地圖與快捷列變暗。",
    ["The dark action-bar button skin."] = "深色快捷列按鈕外觀。",
    ["Enable Dark Mode"] = "啟用深色模式",
    ["Re-tints Blizzard's default frames, minimap and action-bar artwork to a dark tone. Off by default."] = "將暴雪預設框架、小地圖與快捷列美術重新上色為深色調。預設關閉。",
    ["|cffaaaaaaOptional: darkens and desaturates Blizzard's default artwork — unit frames, minimap and action bars — to a neutral dark tone. Reversible: turn it off and the gold look returns.|r"] = "|cffaaaaaa可選：將暴雪預設美術 — 單位框架、小地圖與快捷列 — 加深並降低飽和度為中性深色調。可逆：關閉後金色外觀即會回復。|r",
    ["Action Bars"] = "快捷列",
    ["Skin the action bars"] = "為快捷列套用外觀",
    ["Bar style"] = "快捷列樣式",
    ["WeakAuras Icons"] = "WeakAuras 圖示",
    ["Skin WeakAuras icons"] = "美化 WeakAuras 圖示",
    ["Hide WeakAuras' own border"] = "隱藏 WeakAuras 自身的邊框",
    ["Hides the light border WeakAuras draws on icons, so only our dark rim shows. /reload to fully restore it."] = "隱藏 WeakAuras 在圖示上繪製的淺色邊框，只顯示我們的深色外框。輸入 /reload 可完全還原。",
    ["Circle"] = "圓形",
    ["Also skin pet & stance buttons"] = "同時美化寵物與姿態按鈕",
    ["Enhances the character panel: iLvL per slot, socket display, shortened enchant text."] = "強化角色面板：各裝備欄物品等級、插槽顯示、縮短附魔文字。",
    ["Show item level per slot"] = "顯示各欄位物品等級",
    ["Show average item level"] = "顯示平均物品等級",
    ["Show sockets"] = "顯示插槽",
    ["Shorten enchant text (DE/EN)"] = "縮短附魔文字（德文／英文）",
    ["Example: 'Stamina' -> 'Stam', 'Ausdauer' -> 'Ausd'."] = "例如：'Stamina' -> 'Stam'、'Ausdauer' -> 'Ausd'。",
    ["Treat rings as enchantable"] = "將戒指視為可附魔",
    ["Also shows enchant text on rings (TBC: some professions can enchant rings). /reload required."] = "戒指上也顯示附魔文字（TBC：部分專業可為戒指附魔）。需要 /reload。",
    ["Text Size"] = "文字大小",
    ["Item Level Text Size"] = "物品等級文字大小",
    ["Font size of the item level number on each item slot. Takes effect immediately when the character panel is open."] = "各裝備欄上物品等級數字的字型大小。角色面板開啟時立即生效。",
    ["Note: Some changes only take full effect after /reload, since the character panel is hooked on load."] = "注意：部分變更需 /reload 後才完全生效，因為角色面板是在載入時掛接的。",
    ["|cffff0000No Ench|r"] = "|cffff0000無附魔|r",
    ["|c%siLvL - %d|r"] = "|c%s物品等級 - %d|r",
    ["Gold Tracker"] = "金錢追蹤",
    ["Shows in the backpack gold tooltip how much gold has been gained or spent since the last reset. Per-char persistent."] = "在背包金錢提示資訊中顯示自上次重設以來獲得或花費了多少金錢。以角色為單位永久保存。",
    ["Gold Tracker reset|r. Start = "] = "金錢追蹤已重設|r。起始 = ",
    ["Gold Balance|r"] = "金錢結算|r",
    ["Gained:|r"] = "收入：|r",
    ["Spent:|r"] = "支出：|r",
    ["|cffffffffNet:|r"] = "|cffffffff淨額：|r",
    ["Start:|r"] = "起始：|r",
    ["Now:|r"] = "目前：|r",
    ["Reset with /vcui goldreset|r"] = "使用 /vcui goldreset 重設|r",
    ["|cffaaaaaaShows in the backpack gold tooltip the balance since the last manual reset:|n  - |cff44ff44Gained|r (quests, loot, vendor sales, mail)|n  - |cffff4444Spent|r (repair, vendor buy, mail cost)|n  - |cffffffffNet|r (+/- since reset)|n|nValues are |cffffffffper-char persistent|r across /reload and logout.|nOffline gold (AH mail, trade) is not counted.|n|nReset: button below or |cffffff00/vcui goldreset|r.|r"] = "|cffaaaaaa在背包金錢提示資訊中顯示自上次手動重設以來的結算：|n  - |cff44ff44收入|r（任務、拾取、商人販售、郵件）|n  - |cffff4444支出|r（修理、向商人購買、郵資）|n  - |cffffffff淨額|r（自重設以來的 +/-）|n|n數值為|cffffffff以角色為單位永久保存|r，可跨 /reload 與登出。|n離線取得的金錢（拍賣場郵件、交易）不計入。|n|n重設：下方按鈕或 |cffffff00/vcui goldreset|r。|r",
    ["Reset session"] = "重設本次紀錄",
    ["Class Specific"] = "職業專屬",
    ["|cffaaaaaaVampiric Touch mana tracker — shows live how much mana you've given to the group (5% of shadow damage per tick, per mana user).|n|cffffffffReset automatically on combat start.|r|r"] = "|cffaaaaaa吸血鬼之觸法力追蹤 — 即時顯示你為隊伍提供了多少法力（每次跳動為暗影傷害的 5%，依每位使用法力的成員計算）。|n|cffffffff戰鬥開始時自動重設。|r|r",
    ["|cffff8800These tools are only active while playing a Priest.|r"] = "|cffff8800這些工具僅在扮演牧師時啟用。|r",
    ["No tools yet"] = "尚無工具",
    ["|cffaaaaaaNo class-specific tools for this class yet. Got an idea? Let me know!|r"] = "|cffaaaaaa此職業目前尚無專屬工具。有想法嗎？歡迎告訴我！|r",
    ["|cff9b6cffVT Mana:|r %d"] = "|cff9b6cffVT 法力：|r %d",
    ["|cff9b6cffVT Mana:|r 0"] = "|cff9b6cffVT 法力：|r 0",
    ["Vampiric Touch: %d mana given to the group."] = "吸血鬼之觸：已為隊伍提供 %d 點法力。",
    ["|cffffffffVT MANA|r"] = "|cffffffffVT 法力|r",
    ["VT mana frame: x=%.0f, y=%.0f"] = "VT 法力框架：x=%.0f, y=%.0f",
    ["VT mana mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "VT 法力移動模式啟用。|cff9b6cff拖曳|r或|cff9b6cff方向鍵|r（SHIFT = 5 像素）。",
    ["VT mana mover disabled."] = "VT 法力移動模式已關閉。",
    ["Print to chat at combat end"] = "戰鬥結束時輸出至聊天",
    ["Writes a summary in chat after each fight."] = "每場戰鬥後在聊天中輸出摘要。",
    ["Reset manually"] = "手動重設",
    ["VT mana reset."] = "VT 法力已重設。",
    ["Bars"] = "長條",
    ["Icons"] = "圖示",
    ["Shadow Word: Pain"] = "暗言術：痛",
    ["Vampiric Touch"] = "吸血鬼之觸",
    ["Devouring Plague"] = "吞噬瘟疫",
    ["Warning (seconds left)"] = "警告（剩餘秒數）",
    ["Bar width"] = "長條寬度",
    ["Bar height"] = "長條高度",
    ["Spacing"] = "間距",
    ["Color the timer text"] = "為計時文字上色",
    ["Show recast gain %"] = "顯示重施增益 %",
    ["Shows how much harder a fresh cast would hit right now (e.g. +12% with a spell power proc up). Negative values mean the running DoT snapshotted stronger — keep it."] = "顯示現在重新施放會強多少（例如法術強度觸發時 +12%）。負值代表運作中的持續傷害快照更強 — 請保留它。",
    ["DoT Tracker"] = "持續傷害追蹤",
    ["|cffaaaaaaTracks your DoTs on the target. |cff44ff44Green|r = a buff is up that makes it hit harder if you recast now (TBC snapshot); |cffff4444red|r = about to expire.|r"] = "|cffaaaaaa追蹤你在目標身上的持續傷害。|cff44ff44綠色|r＝目前有增益，現在重施會打得更痛（TBC 快照機制）；|cffff4444紅色|r＝即將到期。|r",
    ["|cffff8800Only active while playing a %s.|r"] = "|cffff8800僅在扮演%s時啟用。|r",
    ["|cffaaaaaaTracks your Warlock DoTs (Corruption, Curse of Agony, Unstable Affliction, Siphon Life, Immolate, Curse of Doom) on the target, with the same recast-snapshot readout as the Priest tracker.|r"] = "|cffaaaaaa追蹤你在目標身上的術士持續傷害（腐蝕術、痛苦詛咒、不穩定的痛苦、生命虹吸、獻祭、末日詛咒），並提供與牧師追蹤器相同的重施快照數值。|r",
    ["Corruption"] = "腐蝕術",
