    ["Unstable Affliction"] = "不穩定的痛苦",
    ["Siphon Life"] = "生命虹吸",
    ["Immolate"] = "獻祭",
    ["Curse of Doom"] = "末日詛咒",
    ["|cffffffffDOTS|r"] = "|cffffffff持續傷害|r",
    ["Shadow DoTs: x=%.0f, y=%.0f"] = "暗影持續傷害：x=%.0f, y=%.0f",
    ["Shadow DoTs mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "暗影持續傷害移動模式啟用。|cff9b6cff拖曳|r或|cff9b6cff方向鍵|r（SHIFT = 5 像素）。",
    ["Shadow DoTs mover disabled."] = "暗影持續傷害移動模式已關閉。",
    ["Mark empty sockets"] = "標記空插槽",
    ["Adds a red ring around item sockets that have no gem."] = "在沒有寶石的插槽周圍加上紅色外框。",
    ["Text shadow (instead of outline)"] = "文字陰影（取代描邊）",
    ["Cleaner text with a drop shadow instead of a thick outline."] = "以投影取代粗描邊，讓文字更乾淨。",
    ["|cffaaaaaaA modern round minimap with a beveled ring, zone text and clock in a slim pill. Zoom with the mouse wheel. |cffffffffShift+drag the map|r to move it — or use Unlock / the addon's own Edit Mode (/vedit). Blizzard's Edit Mode does not manage this map.|r"] = "|cffaaaaaa現代化的圓形小地圖，具備斜角外環、區域文字與細長膠囊型時鐘。以滑鼠滾輪縮放。|cffffffffShift+拖曳地圖|r即可移動 — 或使用解鎖／插件自身的編輯模式（/vedit）。暴雪的編輯模式無法管理這個地圖。|r",
    ["|cffffffffMINIMAP|r"] = "|cffffffff小地圖|r",
