    ["Minimap mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "小地圖移動模式啟用。|cff9b6cff拖曳|r或|cff9b6cff方向鍵|r（SHIFT = 5 像素）。",
    ["Minimap module disabled — /reload restores the default layout completely."] = "小地圖模組已停用 — /reload 可完全還原預設版面。",
    ["Minimap ping: %s"] = "小地圖標記：%s",
    ["Shape"] = "形狀",
