    ["Custom color"] = "自訂顏色",
    ["Theme color"] = "主題顏色",
    ["Dark guild & communities window"] = "深色公會與社群視窗",
    ["Restyles the guild and communities window to the same dark look. Turning it off needs a /reload."] = "將公會與社群視窗改為相同的深色外觀。關閉時需要 /reload。",
    ["Debuffs on target (yours only)"] = "目標身上的減益（僅你的）",
    ["Missing buffs (reminder)"] = "缺少的增益（提醒）",
    ["|cffaaaaaaIcons appear while YOUR debuff/DoT is on the target, with its remaining time. Add the debuff by name or ID.|r"] = "|cffaaaaaa當你的減益／持續傷害在目標身上時顯示圖示與剩餘時間。可用名稱或 ID 新增減益。|r",
    ["|cffaaaaaaIcons appear while the buff is MISSING on you - a reminder for weapon oils, blessings, food buffs. Add the buff by name or ID.|r"] = "|cffaaaaaa當你身上缺少該增益時顯示圖示 - 適合武器油、祝福、食物增益的提醒。可用名稱或 ID 新增增益。|r",
    ["Tint blue when out of mana"] = "法力不足時染成藍色",
    ["Tint red when out of range"] = "距離不足時染成紅色",
    ["Needs a target; uses the spell's own range."] = "需要目標；使用該法術本身的施法距離。",
    ["Auto-track equipped trinkets"] = "自動追蹤已裝備的飾品",
    ["Keeps both equipped trinkets in this group automatically - they follow along when you swap trinkets."] = "自動將兩件已裝備的飾品保留在此群組 - 更換飾品時會一起跟著變更。",
    ["(copy)"] = "（副本）",
    ["Show tooltips on hover"] = "滑鼠移過時顯示提示資訊",
    ["The icons then intercept the mouse - leave this off if the bar sits over clickable UI."] = "圖示會攔截滑鼠 - 若此列位於可點擊的介面上方，請保持關閉。",
    ["Copy the link with Ctrl+C:"] = "以 Ctrl+C 複製連結：",
    ["Click: copy link"] = "點擊：複製連結",
    ["|cffaaaaaaColors everything that is purple today in the color of your choice - sidebar, borders, highlights, bars. A /reload applies it everywhere.|r"] = "|cffaaaaaa將目前所有紫色的元素改成你選擇的顏色 - 側邊欄、邊框、高亮、長條。/reload 後套用至各處。|r",
    ["Preset"] = "預設組合",
    ["Purple (default)"] = "紫色（預設）",
    ["Turquoise"] = "藍綠色",
    ["Pink"] = "粉紅色",
    ["Orange"] = "橘色",
    ["Theme color changed. /reload applies it to everything (elements already drawn keep the old color until then)."] = "主題顏色已變更。/reload 後套用至所有元素（已繪製的元素在此之前維持舊顏色）。",
    ["Custom ring color"] = "自訂外環顏色",
    ["A thin colored line around the dark ring (round shape only)."] = "深色外環周圍的細彩色線條（僅限圓形）。",
    ["Zone panel"] = "區域面板",
    ["Zone text and clock"] = "區域文字與時鐘",
    ["Above the map"] = "地圖上方",
    ["Below the map"] = "地圖下方",
    ["Hidden"] = "隱藏",
    ["Show clock"] = "顯示時鐘",
    ["Show date"] = "顯示日期",
    ["Shows the date next to the clock. Click it to open the calendar."] = "在時鐘旁顯示日期。點擊可開啟行事曆。",
    ["Buttons"] = "按鈕",
    ["Zoom buttons (+/-)"] = "縮放按鈕（+/-）",
    ["Shows a flat + and - on the right edge of the map. The mouse wheel always zooms too."] = "在地圖右緣顯示扁平的 + 與 -。滑鼠滾輪同樣可縮放。",
    ["Show day/night button"] = "顯示日／夜按鈕",
    ["Restyle addon buttons"] = "重新美化插件按鈕",
    ["Removes the gold borders from other addons' minimap buttons and gives them a clean round look. Turning this off needs a /reload."] = "移除其他插件小地圖按鈕的金色邊框，改為乾淨的圓形外觀。關閉時需要 /reload。",
    ["Addon buttons only on mouseover"] = "插件按鈕僅在滑鼠移過時顯示",
    ["Hides other addons' minimap buttons until the mouse is over the minimap."] = "在滑鼠移到小地圖上之前，隱藏其他插件的小地圖按鈕。",
    ["Ping in chat"] = "在聊天中顯示標記",
    ["Prints who pinged the minimap."] = "輸出是誰標記了小地圖。",
    ["Totem Bar"] = "圖騰列",
    ["|cffaaaaaa|cffffffffLeft-click|r an icon to (re)cast that element's totem, |cffffffffhover|r a slot to pick which totem from the icon list, |cffffffffmiddle-click|r to recall all totems. The icon border turns red just before the totem expires.|r"] = "|cffaaaaaa|cffffffff左鍵點擊|r圖示可（重新）施放該元素的圖騰，|cffffffff將滑鼠移到|r欄位上可從圖示清單挑選圖騰，|cffffffff中鍵點擊|r可召回所有圖騰。圖騰即將到期前，圖示邊框會轉為紅色。|r",
    ["|cffff8800Only active while playing a Shaman.|r"] = "|cffff8800僅在扮演薩滿時啟用。|r",
    ["Totem set"] = "圖騰組合",
    ["Active set"] = "使用中的組合",
    ["Set name"] = "組合名稱",
    ["New set"] = "新增組合",
    ["Delete set"] = "刪除組合",
    ["Shown elements"] = "顯示的元素",
    ["Sound before a totem expires"] = "圖騰到期前播放音效",
    ["Icon border (action-bar style)"] = "圖示邊框（快捷列樣式）",
    ["Style"] = "樣式",
    ["VuloUI (dark)"] = "VuloUI（深色）",
    ["Classic (metal)"] = "經典（金屬）",
    ["Flyout direction"] = "彈出方向",
    ["Which way the totem picker opens when you hover a slot. Automatic picks the side away from the screen edge."] = "滑鼠移到欄位上時圖騰選單的展開方向。自動會選擇遠離螢幕邊緣的一側。",
    ["Automatic"] = "自動",
    ["Upwards"] = "向上",
    ["Downwards"] = "向下",
    ["To the left"] = "向左",
    ["To the right"] = "向右",
    ["Open flyout in combat"] = "戰鬥中開啟彈出選單",
    ["Tooltip with cooldown on hover"] = "滑鼠移過時顯示含冷卻的提示資訊",
    ["Hovering a totem slot or a picker icon shows the totem name and its remaining cooldown."] = "將滑鼠移到圖騰欄位或選單圖示上時，顯示圖騰名稱與剩餘冷卻時間。",
    ["Off = hovering a slot never opens the totem picker while you are fighting (clicks still cast). The picker now also closes itself on mouse-out and after every cast, even in combat."] = "關閉＝戰鬥中將滑鼠移到欄位上不會開啟圖騰選單（點擊仍可施放）。選單現在也會在滑鼠移開後與每次施放後自動關閉，戰鬥中亦然。",
    ["Fire"] = "火",
    ["Earth"] = "土",
    ["Water"] = "水",
    ["Air"] = "風",
    ["|cffffffffTOTEMS|r"] = "|cffffffff圖騰|r",
    ["Totems: x=%.0f, y=%.0f"] = "圖騰：x=%.0f, y=%.0f",
    ["Totem timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "圖騰計時移動模式啟用。|cff9b6cff拖曳|r或|cff9b6cff方向鍵|r（SHIFT = 5 像素）。",
    ["Totem timer mover disabled."] = "圖騰計時移動模式已關閉。",
    ["|cffff5555Class tool error:|r %s"] = "|cffff5555職業工具錯誤：|r %s",
    ["EDIT MODE"] = "編輯模式",
    ["Edit Mode"] = "編輯模式",
    ["Open Edit Mode"] = "開啟編輯模式",
    ["Close Edit Mode and lock all windows. Your changes stay applied."] = "關閉編輯模式並鎖定所有視窗。你的變更會保留。",
    ["Keep the current arrangement and carry on editing. Discard then returns to this point instead of to how things looked when Edit Mode opened."] = "保留目前的排列並繼續編輯。之後的「捨棄」會回到此時的狀態，而非編輯模式開啟時的樣子。",
    ["Window positions saved."] = "視窗位置已儲存。",
    ["Exit"] = "離開",
    ["Close"] = "關閉",
    ["Reset"] = "重設",
    ["Reset this frame"] = "重設此框架",
    ["Reset all VuloUI window positions to the screen centre."] = "將所有 VuloUI 視窗位置重設至螢幕中央。",
    ["Reset all VuloUI window positions to the screen centre?"] = "要將所有 VuloUI 視窗位置重設至螢幕中央嗎？",
    ["Done — lock everything"] = "完成 — 鎖定全部",
    ["Grid"] = "格線",
    ["Snap"] = "對齊",
    ["Show an alignment grid."] = "顯示對齊格線。",
    ["Snap windows to the grid while dragging."] = "拖曳時讓視窗對齊格線。",
    ["%d frames here - hold Alt to cycle"] = "此處有 %d 個框架 - 按住 Alt 可循環切換",
    ["Which screen point the frame is pinned to (keeps it put across resolution changes)."] = "框架固定在螢幕上的哪個位置（解析度變更後仍維持原位）。",
    ["ANCHOR"] = "錨點",
    ["POSITION"] = "位置",
    ["SCALE"] = "縮放",
    ["FREE MOVE"] = "自由移動",
    ["FOLLOW WINDOW"] = "跟隨視窗",
    ["Pins this window to another one - it then moves along whenever that window is moved. Dragging this window keeps the pin and just updates the distance."] = "將此視窗固定到另一個視窗 - 之後該視窗移動時會一起移動。拖曳此視窗會保留固定關係，只更新兩者的距離。",
    ["Not possible - that would create a loop."] = "無法執行 - 這會造成循環。",
    ["Anchor to window..."] = "錨定到視窗…",
    ["WIDTH LIKE"] = "寬度同於",
    ["HEIGHT LIKE"] = "高度同於",
    ["Takes its width from another window and keeps it."] = "從另一個視窗取得寬度並保持一致。",
    ["Takes its height from another window and keeps it."] = "從另一個視窗取得高度並保持一致。",
    ["This window sets its own size - the match will not stick."] = "此視窗自行決定大小 - 同步設定不會生效。",
    ["Drag a box, or hover it and use the arrow keys (Shift = 5px). Hold Shift while dragging to lock one axis. Shift+right-click hides a box that is in the way."] = "拖曳方框，或將滑鼠移到上面後使用方向鍵（Shift = 5 像素）。拖曳時按住 Shift 可鎖定單一軸向。Shift+右鍵點擊可隱藏擋路的方框。",
    ["Then click any window to anchor this one to it."] = "接著點擊任一視窗，即可將此視窗錨定到它。",
    ["Click a window to anchor it (right-click to cancel)."] = "點擊一個視窗以進行錨定（右鍵取消）。",
    ["ANCHOR SIDE"] = "錨定邊",
    ["Centered"] = "置中",
    ["Top of"] = "上方",
    ["Bottom of"] = "下方",
    ["Discard"] = "捨棄",
    ["Pin this frame to a screen edge/corner so it stays put across resolution changes. Off keeps it centred."] = "將此框架固定到螢幕邊緣／角落，讓它在解析度變更後維持原位。關閉則保持置中。",
    ["Leave this window unlocked so you can still drag it after closing Edit Mode. Stays unlocked through /reload."] = "讓此視窗保持解鎖，關閉編輯模式後仍可拖曳。/reload 後仍維持解鎖。",
    ["LAYOUTS"] = "版面配置",
    ["Layouts"] = "版面配置",
    ["SAVED"] = "已儲存",
    ["No layouts saved"] = "尚未儲存任何版面配置",
    ["No layout selected."] = "未選取版面配置。",
    ["Save, load, export and import named window layouts."] = "儲存、載入、匯出與匯入具名的視窗版面配置。",
    ["Save your window arrangement, then load or share it any time."] = "儲存你的視窗排列，隨時載入或分享。",
    ["Pick a saved layout to load, delete or export."] = "選擇一個已儲存的版面配置以載入、刪除或匯出。",
    ["Save current as..."] = "將目前設定另存為…",
    ["Name for this layout:"] = "此版面配置的名稱：",
    ["Delete layout '%s'?"] = "要刪除版面配置「%s」嗎？",
    ["Layout '%s' saved."] = "版面配置「%s」已儲存。",
    ["Applied layout '%s' (%d frames)."] = "已套用版面配置「%s」（%d 個框架）。",
    ["Layout '%s' imported."] = "已匯入版面配置「%s」。",
    ["Import"] = "匯入",
    ["Export"] = "匯出",
    ["Imported"] = "已匯入",
    ["Import failed (%s)."] = "匯入失敗（%s）。",
    ["Paste a layout string and confirm:"] = "貼上版面配置字串並確認：",
    ["Copy this string (Ctrl+A, Ctrl+C):"] = "複製此字串（Ctrl+A、Ctrl+C）：",
    ["Move it in the unified Edit Mode (/vedit)."] = "請在整合編輯模式（/vedit）中移動它。",
    ["Drag the combat-text box in the unified Edit Mode (/vedit)."] = "請在整合編輯模式（/vedit）中拖曳戰鬥文字方框。",
    ["|cffffffffARENA FRAMES|r"] = "|cffffffff競技場框架|r",
    ["|cff44ff44Edit Mode is ON.|r Close this window to reach the boxes."] = "|cff44ff44編輯模式已開啟。|r關閉此視窗即可操作方框。",
    ["|cffaaaaaaMove everything in one editor: VuloUI windows and Blizzard's frames (player, target, focus, minimap, buffs). They snap to a shared grid.|r"] = "|cffaaaaaa在同一個編輯器中移動所有東西：VuloUI 視窗與暴雪的框架（玩家、目標、專注目標、小地圖、增益）。它們會對齊共用的格線。|r",
    ["|cff888888• Drag a purple box to move that frame.|n• Hover a box, then arrow keys fine-tune (SHIFT = 5px).|n• Right-click a box for exact X / Y.|n• |cffffffff/vedit|r toggles Edit Mode too.|r"] = "|cff888888• 拖曳紫色方框可移動該框架。|n• 將滑鼠移到方框上，再用方向鍵微調（SHIFT = 5 像素）。|n• 在方框上按右鍵可輸入精確的 X / Y。|n• |cffffffff/vedit|r 同樣可切換編輯模式。|r",
    ["Enable 'Target and Focus' in Blizzard's Edit Mode settings, then /reload, so VuloUI can move the target/focus frame."] = "請在暴雪的編輯模式設定中啟用「目標與專注目標」，然後 /reload，VuloUI 才能移動目標／專注目標框架。",
    ["Dark Mode"] = "深色模式",
    ["Desaturate (greyscale)"] = "去飽和（灰階）",
    ["Strips the colour out of the artwork before tinting, for a true greyscale look. Off keeps a hint of the original hue."] = "上色前先移除美術的顏色，呈現真正的灰階效果。關閉則保留些許原本的色調。",
    ["Tint colour"] = "染色顏色",
    ["Unit frames"] = "單位框架",
    ["Player, target, focus, pet and party frame borders."] = "玩家、目標、專注目標、寵物與隊伍框架的邊框。",
    ["Minimap border, compass, zoom and tracking buttons."] = "小地圖邊框、羅盤、縮放與追蹤按鈕。",
    ["Action bar artwork"] = "快捷列美術",
    ["The gryphons and the metal action-bar background."] = "獅鷲與金屬質感的快捷列背景。",
    ["Action button borders"] = "快捷按鈕邊框",
    ["Also tints the border ring around every action button. Optional — leave off if it looks too flat."] = "同時為每個快捷按鈕周圍的邊框上色。選用 — 若看起來太平淡就保持關閉。",
    ["Bag slots"] = "背包欄位",
    ["Tints the backpack, bag and keyring button borders."] = "為背包、背包欄與鑰匙圈按鈕的邊框上色。",
    ["|cffaaaaaaNote: if the Player & Target Frame module's |cffffffffThreat glow|r is on, threat colouring takes over the target/focus border while you have aggro — that's intended.|r"] = "|cffaaaaaa注意：若「玩家與目標框架」模組的 |cffffffff威脅光暈|r 已開啟，當你承受仇恨時，威脅顏色會接管目標／專注目標的邊框 — 這是正常的。|r",
    ["Chat"] = "聊天",
    ["Polishes Blizzard's chat: a dark panel with an icon sidebar, timestamps, class-coloured names, clickable links, dark tabs, idle fade and history that survives a /reload. Every part is optional."] = "優化暴雪的聊天：深色面板搭配圖示側邊欄、時間戳記、職業顏色名稱、可點擊連結、深色標籤、閒置淡出，以及可跨 /reload 保留的歷史紀錄。每項功能皆為選用。",
    ["|cffaaaaaaPolishes Blizzard's own chat — nothing is replaced, so it stays light and compatible. Every option below is independent.|r"] = "|cffaaaaaa優化暴雪自己的聊天 — 不取代任何東西，因此保持輕量且相容。以下每個選項都各自獨立。|r",
    ["Timestamps"] = "時間戳記",
    ["Show timestamps"] = "顯示時間戳記",
    ["Prefixes each line with the time, using the game's own timestamp setting."] = "在每行前加上時間，使用遊戲本身的時間戳記設定。",
    ["Time format"] = "時間格式",
    ["Names & links"] = "名稱與連結",
    ["Class-coloured names"] = "職業顏色名稱",
    ["Colours player names by their class in say, party, raid, guild, whisper and channels."] = "在說話、隊伍、團隊、公會、密語與頻道中，依職業為玩家名稱上色。",
    ["Clickable links"] = "可點擊連結",
    ["Turns web links into clickable links that open a copy box."] = "將網址轉為可點擊的連結，點擊後開啟複製視窗。",
    ["Style chat tabs"] = "美化聊天標籤",
    ["Flat dark tab background with an accent underline on the active tab."] = "扁平的深色標籤背景，使用中的標籤帶有強調色底線。",
    ["Tab label size"] = "標籤文字大小",
    ["One uniform font size for every chat tab label."] = "所有聊天標籤文字使用統一的字型大小。",
    ["Chat font size (0 = Blizzard)"] = "聊天字型大小（0 = 暴雪預設）",
    ["Scrollback (lines per window)"] = "回捲行數（每個視窗）",
    ["How many lines each chat window keeps for scrolling (Blizzard default: 128). More lines use a little more memory; changing this clears the currently shown lines once."] = "每個聊天視窗保留多少行供捲動（暴雪預設：128）。行數越多會多用一點記憶體；變更此設定會清空一次目前顯示的內容。",
    ["Item levels in chat links"] = "聊天連結中顯示物品等級",
    ["Appends the item level to equipment links: [Sword] becomes [Sword (45)]."] = "在裝備連結後附加物品等級：[劍] 會變成 [劍 (45)]。",
    ["Overrides the message font size for every chat window. 0 keeps each window's own Blizzard size."] = "覆寫所有聊天視窗的訊息字型大小。0 則保留各視窗原本的暴雪大小。",
    ["Panel opacity (%)"] = "面板不透明度（%）",
    ["Transparency of the dark background panel behind the chat."] = "聊天後方深色背景面板的透明度。",
    ["Indent wrapped lines"] = "換行內容縮排",
    ["Wraps long messages with continuation lines indented under the message start, for a cleaner column."] = "長訊息換行時，後續行縮排至訊息開頭下方，讓版面更整齊。",
    ["Idle fade"] = "閒置淡出",
    ["Fade chat when idle"] = "閒置時淡出聊天",
    ["Dims the chat after a while with no activity. A new message, hovering it or typing brings it back."] = "一段時間沒有活動後將聊天變暗。新訊息、滑鼠移過或開始輸入都會恢復。",
    ["Idle delay (seconds)"] = "閒置延遲（秒）",
    ["Faded opacity (%)"] = "淡出後不透明度（%）",
    ["History"] = "歷史紀錄",
    ["Keep chat history"] = "保留聊天歷史紀錄",
    ["Remembers recent chat per character and re-shows it after a /reload."] = "為每個角色記住最近的聊天內容，並在 /reload 後重新顯示。",
    ["Lines to keep"] = "保留行數",
    ["Clear history"] = "清除歷史紀錄",
    ["Chat history cleared."] = "聊天歷史紀錄已清除。",
    ["--- chat history ---"] = "--- 聊天歷史紀錄 ---",
    ["Copy"] = "複製",
    ["Copy chat"] = "複製聊天內容",
    ["Link"] = "連結",
    ["Ctrl+A to select all, Ctrl+C to copy."] = "Ctrl+A 全選，Ctrl+C 複製。",
    ["Scroll to bottom"] = "捲動至底部",
    ["|cffaaaaaaThe panel, input and sidebar reposition Blizzard's chat. Turning them off here hides them immediately; a |cffffffff/reload|r restores the exact original positions.|r"] = "|cffaaaaaa面板、輸入列與側邊欄會重新調整暴雪聊天的位置。在此關閉會立即隱藏它們；|cffffffff/reload|r 可還原原本的精確位置。|r",
    ["Dark background panel"] = "深色背景面板",
    ["A dark panel behind the chat and input line, with the tab bar above it — one cohesive block."] = "聊天與輸入列後方的深色面板，標籤列位於其上方 — 形成一個整體區塊。",
    ["Top fade"] = "頂端淡出",
    ["Fades old lines into the panel at the top edge of the chat."] = "讓舊訊息在聊天頂端邊緣淡入面板中。",
    ["Icon sidebar"] = "圖示側邊欄",
    ["A slim bar left of the chat with copy, settings, new-window and scroll-to-bottom icons."] = "聊天左側的細長列，包含複製、設定、新視窗與捲動至底部的圖示。",
    ["Show online friends"] = "顯示線上好友",
    ["Show how many friends are online at the top of the sidebar; click the icon to open the friends list."] = "在側邊欄頂端顯示有多少好友在線上；點擊圖示可開啟好友名單。",
    ["Friends online"] = "線上好友",
