    ["Copy button (standalone)"] = "複製按鈕（獨立）",
    ["A small copy button above the chat. Off by default since the sidebar already has a copy icon; turn the sidebar off to use this instead."] = "聊天上方的小型複製按鈕。預設關閉，因為側邊欄已經有複製圖示；關閉側邊欄後可改用這個。",
