    ["Fixed slot order (OneBag)"] = "固定格位順序（OneBag）",
    ["Shows every slot in its natural bag order with the empty slots inline — items stay visually where you drop them, like one big real bag. Needs the free-slots option above."] = "依背包原本的順序顯示所有格位，空格也一併排列 — 物品會停在你放下的位置，就像一個真正的大背包。需要啟用上方的空位選項。",
    ["Junk marker (C)"] = "垃圾標記（C）",
