    ["Faded opacity"] = "淡出不透明度",
    ["Fade speed (sec.)"] = "淡出速度（秒）",
    ["|cffff5555Action Bars: leaving combat to restore Blizzard's bars…|r"] = "|cffff5555快捷列：脫離戰鬥後將還原暴雪的快捷列…|r",
    ["|cffaaaaaaOwn buttons for every action bar (1-5): real combat / mouseover show-hide, scale and grid layout, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. Move each in Edit Mode (/vedit). After disabling, /reload to fully restore Blizzard's bars.|r"] = "|cffaaaaaa為每個快捷列（1-5）提供自有按鈕：真正的戰鬥／滑鼠移過顯示隱藏、縮放與格線版面、正確的主列換頁（德魯伊／盜賊／戰士／牧師形態）以及你的按鍵設定。可在編輯模式（/vedit）中個別移動。停用後請執行 /reload 以完整還原暴雪的快捷列。|r",
    ["Action Bar 1 (Main)"] = "快捷列 1（主要）",
    ["Action Bar 2"] = "快捷列 2",
    ["Action Bar 3"] = "快捷列 3",
    ["Action Bar 4"] = "快捷列 4",
    ["Action Bar 5"] = "快捷列 5",
    ["Action Bar 6 (Extra)"] = "快捷列 6（額外）",
    ["Grow from"] = "延伸起點",
    ["Left edge (rightwards)"] = "左緣（向右）",
    ["Right edge (leftwards)"] = "右緣（向左）",
    ["Rows grow"] = "列的延伸方向",
    ["Mouseover reveals all mouseover bars"] = "滑鼠移過時顯示所有滑鼠移過的快捷列",
    ["Hovering ANY mouseover bar shows every bar set to mouseover at once."] = "移過任一滑鼠移過快捷列時，會同時顯示所有設為滑鼠移過的快捷列。",
    ["Button text styling"] = "按鈕文字樣式",
    ["|cffaaaaaaColours and fine offsets for the button texts, on every bar.|r"] = "|cffaaaaaa所有快捷列上按鈕文字的顏色與細部偏移。|r",
    ["Keybind text colour"] = "按鍵設定文字顏色",
    ["Macro text colour"] = "巨集文字顏色",
    ["Count text colour"] = "數量文字顏色",
    ["Keybind offset X"] = "按鍵設定 X 偏移",
    ["Keybind offset Y"] = "按鍵設定 Y 偏移",
    ["Macro offset X"] = "巨集 X 偏移",
    ["Macro offset Y"] = "巨集 Y 偏移",
    ["Count offset X"] = "數量 X 偏移",
    ["Count offset Y"] = "數量 Y 偏移",
    ["0 = use the game's default size."] = "0 = 使用遊戲的預設大小。",
    ["Vertical layout"] = "垂直版面",
    ["Reverse order"] = "反轉順序",
    ["Hide keybind text"] = "隱藏按鍵設定文字",
    ["Hide macro text"] = "隱藏巨集文字",
    ["Game Menu"] = "遊戲選單",
    ["Game menu: VuloUI look"] = "遊戲選單：VuloUI 外觀",
    ["Restyles the Escape menu to match the addon look: dark panel, flat buttons, accent title. Changing this needs a /reload."] = "將 Esc 選單重新設計成與插件外觀一致：深色面板、扁平按鈕、強調色標題。變更此項需要 /reload。",
    ["Game menu: VuloClassicUI button"] = "遊戲選單：VuloClassicUI 按鈕",
    ["Adds a VuloClassicUI button to the Escape menu that opens the options window. Turning this off needs a /reload."] = "在 Esc 選單中加入一個 VuloClassicUI 按鈕，可開啟選項視窗。關閉此項需要 /reload。",
    ["Hide the FPS / latency bar"] = "隱藏 FPS／延遲列",
    ["Hides Blizzard's small green performance (FPS / latency) bar."] = "隱藏暴雪的小型綠色效能（FPS／延遲）列。",
    ["Micro menu style"] = "微型選單樣式",
    ["World map"] = "世界地圖",
    ["Friends list"] = "好友名單",
    ["Group finder"] = "隊伍搜尋器",
    ["Bag bar style"] = "背包列樣式",
    ["Key ring"] = "鑰匙圈",
    ["Timer decimals below 10 seconds"] = "10 秒以下顯示計時小數",
    ["Interrupted by %s"] = "被 %s 打斷",
    ["Value + percent"] = "數值 + 百分比",
    ["Value + percent layout"] = "數值 + 百分比版面",
    ["Short values (12.3k)"] = "簡短數值（12.3k）",
    ["Show percent sign"] = "顯示百分比符號",
    ["Smooth health changes"] = "平滑的生命變化",
    ["The bar glides to the new value; a bright trail marks health draining away."] = "此條會滑順地移動到新數值；明亮的殘影標示流失中的生命。",
    ["Tint background with bar colour"] = "以條的顏色為背景著色",
    ["The empty part of the bar shows a darkened shade of the bar colour instead of plain dark grey."] = "條的空白部分會顯示條顏色的暗色調，而非單純的深灰色。",
    ["Glow at the bar edge"] = "條緣發光",
    ["A soft glow rides the end of the fill, tinted in the bar's own colour. Also applies to the cast bar."] = "柔和的光暈跟隨填充末端，並以條本身的顏色著色。也套用於施法條。",
    ["Edge glow width"] = "邊緣光暈寬度",
    ["Rounded bar corners"] = "圓角的條",
    ["Clips the fill and background to a rounded shape. The line border stays square, so a thin border may show slightly at the corners."] = "將填充與背景裁切為圓角形狀。線條邊框仍是方形，因此角落可能會略微露出細邊框。",
    ["Overall plate scale (%)"] = "整體名條縮放 (%)",
    ["Scales every plate at once, on top of each individual size."] = "在各自大小之上，一次縮放所有名條。",
    ["Vertical offset"] = "垂直偏移",
    ["Moves every plate up or down relative to its unit."] = "相對於單位上下移動所有名條。",
    ["Font outline"] = "字型外框",
    ["How plate text is lifted off the background."] = "名條文字如何從背景中凸顯出來。",
    ["Thick outline"] = "粗外框",
    ["Show level"] = "顯示等級",
    ["Shows the unit level to the left of the name; ?? means the level is far above yours."] = "在名稱左側顯示單位等級；?? 表示等級遠高於你。",
    ["Mark rare and elite"] = "標示稀有與精英",
    ["Appends a rank to the level and turns it gold: + elite, R rare, R+ rare elite, B world boss."] = "在等級後附加階級並轉為金色：+ 精英、R 稀有、R+ 稀有精英、B 世界首領。",
    ["Level size"] = "等級大小",
    ["0 = uses the name size."] = "0 = 使用名稱大小。",
    ["Emphasise casting units"] = "強調施法中的單位",
    ["While a unit casts, its plate grows a little and stays readable even when something else is targeted."] = "單位施法時，其名條會稍微放大，即使目標是其他對象也維持易讀。",
    ["Casting scale (%)"] = "施法縮放 (%)",
    ["Casting opacity (%)"] = "施法不透明度 (%)",
    ["Colour border by school"] = "依法術系別為邊框著色",
    ["Aura borders take the colour of their school: magic blue, curse purple, disease orange, poison green."] = "光環邊框採用其系別的顏色：魔法藍、詛咒紫、疾病橘、中毒綠。",
    ["Flash before running out"] = "結束前閃爍",
    ["The icon pulses over the last part of its duration, so you can see when to refresh."] = "圖示會在持續時間的最後階段脈動，讓你看出何時該重新施放。",
    ["Flash below (%)"] = "低於此比例時閃爍 (%)",
    ["Your Own Debuffs"] = "你自己的減益",
    ["|cffaaaaaaA separate row for the harmful auras you cast yourself - your damage-over-time timers, kept away from everything else on the target.|r"] = "|cffaaaaaa為你自己施放的有害光環設立獨立一列 - 你的持續傷害計時，與目標身上的其他一切分開。|r",
    ["Show your own debuffs (separate row)"] = "顯示你自己的減益（獨立列）",
    ["Max icons"] = "圖示數量上限",
    ["Icons per line"] = "每行圖示數",
    ["0 = one line. Otherwise the row wraps after this many icons."] = "0 = 單行。否則此列會在達到此圖示數後換行。",
    ["Reminders"] = "提醒",
    ["|cffaaaaaaShows a short row of icons for what you are missing right now. Out of combat a click casts or uses the fix; hovering explains what it wants. The row holds still during combat.|r"] = "|cffaaaaaa以一小列圖示顯示你目前缺少的東西。非戰鬥中點擊即可施放或使用對應的補救；移過滑鼠會說明它的需求。戰鬥中此列維持不動。|r",
    ["Also warn about empty equipment slots"] = "同時警告空的裝備欄位",
    ["Off by default: a ring, trinket or cloak is often legitimately empty while levelling."] = "預設關閉：升級過程中，戒指、飾品或披風經常是合理地空著。",
    ["Shows what you are missing - class buffs, weapon enchants, food, stance, pet, ammo, durability, empty gear slots and unspent talent points."] = "顯示你缺少的東西 - 職業增益、武器附魔、食物、姿態、寵物、彈藥、耐久度、空的裝備欄位以及未使用的天賦點數。",
    ["What to watch"] = "監看項目",
    ["Class buffs"] = "職業增益",
    ["Weapon enchants"] = "武器附魔",
    ["Stance and aura"] = "姿態與光環",
    ["Food and flask"] = "食物與精煉藥劑",
    ["Ammo, durability, gear, talents"] = "彈藥、耐久度、裝備、天賦",
    ["Most icons at once"] = "同時顯示的圖示上限",
    ["Anything past this is bundled into a single counter instead of adding another icon."] = "超過此數量的部分會併入單一計數器，而不會再增加圖示。",
    ["Show labels"] = "顯示標籤",
    ["Settle time (seconds)"] = "穩定時間（秒）",
    ["How long something must stay missing before an icon appears. Stops it flickering between casts."] = "某項缺失必須持續多久才會出現圖示。可避免它在施放之間閃爍。",
    ["Warn when under (seconds)"] = "低於此秒數時警告（秒）",
    ["Also warn while a buff or weapon enchant is about to run out. 0 = only warn when it is gone."] = "增益或武器附魔即將結束時也提出警告。0 = 僅在消失時警告。",
    ["Durability below (%)"] = "耐久度低於 (%)",
    ["Ammo below"] = "彈藥低於",
    ["Quiet while resting"] = "休息時安靜",
    ["No reminders in a city or inn."] = "在城市或旅店中不提醒。",
    ["Quiet while eating or drinking"] = "進食或喝水時安靜",
    ["Click to cast."] = "點擊以施放。",
    ["Missing: %s"] = "缺少：%s",
    ["Main hand"] = "主手",
    ["Off hand"] = "副手",
    ["No weapon enchant: %s"] = "沒有武器附魔：%s",
    ["Weapon enchant running out: %s"] = "武器附魔即將結束：%s",
    ["Stance"] = "姿態",
    ["No stance active"] = "未啟用姿態",
    ["Aura"] = "光環",
    ["No aura active"] = "未啟用光環",
    ["Pet"] = "寵物",
    ["No pet out"] = "未召喚寵物",
    ["Passive"] = "被動",
    ["Pet is set to passive"] = "寵物設定為被動",
    ["Food"] = "食物",
    ["Not well fed"] = "未獲得飽食狀態",
    ["Flask"] = "精煉藥劑",
    ["No flask or elixir"] = "沒有精煉藥劑或藥劑",
    ["Low ammo: %d left"] = "彈藥不足：剩餘 %d",
    ["Equipment damaged: %d%% left"] = "裝備已損壞：剩餘 %d%%",
    ["Empty equipment slots: %d"] = "空的裝備欄位：%d",
    ["Unspent talent points: %d"] = "未使用的天賦點數：%d",
    ["Racials"] = "種族技能",
    ["Racial Cooldowns"] = "種族技能冷卻",
    ["Shows the opponent's racial ability and its cooldown once they use it. These are this expansion's cooldowns, and no racial shares one with the PvP trinket yet."] = "對手使用種族技能後，顯示該技能及其冷卻。這些是本資料片的冷卻，目前尚無種族技能與 PvP 飾品共用冷卻。",
    ["Show racial cooldown"] = "顯示種族技能冷卻",
    ["Shadow Sight"] = "暗影視野",
    ["Shadow Sight up"] = "暗影視野已出現",
    ["Shadow Sight up - next in %d s"] = "暗影視野已出現 - 下一個在 %d 秒後",
    ["Shadow Sight in %d s"] = "暗影視野在 %d 秒後",
    ["Counts down the arena orbs: the first pair appears 95 seconds after the gates open, and each one returns 122 seconds after it is taken."] = "為競技場寶珠倒數：第一對在閘門開啟後 95 秒出現，之後每個在被取走後 122 秒重新出現。",
    ["Show Shadow Sight timer"] = "顯示暗影視野計時",
    ["Aura on the class icon"] = "職業圖示上的光環",
    ["Puts the single most relevant aura on the opponent's class icon: an immunity outranks crowd control, which outranks a defensive, which outranks an offensive cooldown."] = "在對手的職業圖示上放上最相關的單一光環：免疫優先於控場，控場優先於防禦技能，防禦技能優先於攻擊性冷卻。",
    ["Show aura on the class icon"] = "在職業圖示上顯示光環",
    ["Crowd control only"] = "僅控場效果",
    ["Dispels"] = "驅散",
    ["Dispel Cooldowns"] = "驅散冷卻",
    ["|cffaaaaaaMost dispels have no cooldown in this expansion, so only Mass Dispel and the felhunter's Devour Magic can ever show up here.|r"] = "|cffaaaaaa本資料片中大多數驅散沒有冷卻，因此只有大驅散與地獄獵犬的吞噬魔法會出現在這裡。|r",
    ["Show dispel cooldown"] = "顯示驅散冷卻",
    ["Range"] = "距離",
    ["Fades the frame while the opponent is out of reach, measured with a spell your class knows rather than a fixed distance."] = "對手超出範圍時淡出其框架，以你職業已知的法術測量，而非固定距離。",
    ["Fade out-of-range opponents"] = "淡出超出距離的對手",
    ["Discard changes and revert every window to the last save point, or to how it was when Edit Mode opened."] = "捨棄變更，並將每個視窗還原至上次的儲存點，或還原成開啟編輯模式時的樣子。",
    ["Discard all changes made since the last save?"] = "捨棄自上次儲存後的所有變更？",
    ["Grey out when you walk out of range"] = "走出範圍時變灰",
    ["Drains the colour while you are outside a totem's radius, and restores it when you step back in. Recognised from the buff the totem puts on you, so totems that grant no buff (Searing, Magma, Tremor, ...) always stay lit."] = "當你在圖騰半徑之外時抽離顏色，回到範圍內時恢復。這是由圖騰給予你的增益判定，因此不給予增益的圖騰（灼熱、熔岩、顫動…）永遠保持亮起。",
    ["Limit to"] = "限制為",
    ["Everything"] = "全部",
    ["Only mine"] = "僅自己的",
    ["Only removable"] = "僅可移除的",
    ["Narrows this row to auras you cast yourself, or to ones that can be removed."] = "將此列限縮為你自己施放的光環，或可被移除的光環。",
    ["Nudges every aura row at once, on top of each row's own offset."] = "在每列自身偏移之上，一次微調所有光環列。",
    ["Share of the remaining duration at which the pulse starts."] = "脈動開始時剩餘持續時間的比例。",
    ["Own colour while your interrupt is ready"] = "你的打斷就緒時使用專屬顏色",
    ["Interruptible casts paint in this colour while your interrupt is off cooldown — kick at will."] = "當你的打斷不在冷卻中時，可打斷的施法會以此顏色顯示 — 隨時可以踢。",
    ["Interrupt-ready colour"] = "打斷就緒顏色",
    ["Own colour while channelling"] = "引導時使用專屬顏色",
    ["Channel colour"] = "引導顏色",
    ["Own colour when the cast targets YOU"] = "施法目標是你時使用專屬顏色",
    ["The bar turns this colour while the caster's target is you."] = "當施法者的目標是你時，此條會轉為這個顏色。",
    ["Targets-you colour"] = "目標為你的顏色",
    ["Show who interrupted"] = "顯示打斷者",
    ["The interrupt flash shows the name of whoever landed the interrupt."] = "打斷閃光會顯示成功打斷者的名字。",
    ["On: 9.9, 3.4 … Off: whole seconds (9, 3)."] = "開啟：9.9、3.4 … 關閉：整秒（9、3）。",
    ["Modern puts the real bag buttons on a flat dark strip in the VuloUI look — opening, swapping and tooltips stay identical."] = "現代風格將真正的背包按鈕放在 VuloUI 外觀的扁平深色長條上 — 開啟、交換與提示資訊完全不變。",
    ["Modern replaces Blizzard's buttons with a flat dark icon strip in the VuloUI look. Clicks and tooltips stay identical."] = "現代風格以 VuloUI 外觀的扁平深色圖示長條取代暴雪的按鈕。點擊與提示資訊完全不變。",
    ["Classic (Blizzard buttons)"] = "經典（暴雪按鈕）",
    ["Modern (flat icon strip)"] = "現代（扁平圖示長條）",
    ["Hide the micro menu"] = "隱藏微型選單",
    ["Hides the row of menu buttons (character, spellbook, …)."] = "隱藏選單按鈕列（角色、法術書、…）。",
    ["Hide the bag bar"] = "隱藏背包列",
    ["Hides the backpack and bag slots."] = "隱藏背包與背包欄位。",
    ["|cff9b6cffThe micro menu, bag bar, FPS/latency bar and the XP bar below are movable in Edit Mode (/vedit) like the action bars.|r"] = "|cff9b6cff微型選單、背包列、FPS／延遲列以及下方的經驗值條，都可像快捷列一樣在編輯模式（/vedit）中移動。|r",
    ["Micro menu"] = "微型選單",
    ["Bag bar"] = "背包列",
    ["FPS / latency bar"] = "FPS／延遲列",
    ["XP bar"] = "經驗值條",
    ["Show a custom XP bar"] = "顯示自訂經驗值條",
    ["Colour"] = "顏色",
    ["Bar opacity"] = "條的不透明度",
    ["Show empty buttons"] = "顯示空按鈕",
    ["Off hides empty slots; they reappear automatically while you drag an ability."] = "關閉會隱藏空欄位；拖曳技能時它們會自動重新出現。",
    ["Click through"] = "點擊穿透",
    ["The bar ignores the mouse entirely — clicks go through it. Keybinds still work."] = "此列完全忽略滑鼠 — 點擊會直接穿過。按鍵設定仍可運作。",
    ["Keybind text size"] = "按鍵設定文字大小",
    ["Macro text size"] = "巨集文字大小",
    ["Count text size"] = "數量文字大小",
    ["Cooldown text size"] = "冷卻文字大小",
    ["0 = default size."] = "0 = 預設大小。",
    ["0 = default size. Requires cooldown numbers to be enabled in the game options."] = "0 = 預設大小。需要在遊戲選項中啟用冷卻數字。",
    ["Cooldown & look"] = "冷卻與外觀",
    ["|cffff5555Quick keybind mode is not available on this client.|r"] = "|cffff5555此客戶端不支援快速按鍵設定模式。|r",
    ["Modifier paging"] = "輔助鍵換頁",
    ["Click: open these settings"] = "點擊：開啟這些設定",
    ["Crowd Control"] = "控場效果",
    ["Addon font (default)"] = "插件字型（預設）",
    ["The typeface for every text on the plates (name, health, cast, auras)."] = "名條上所有文字的字體（名稱、生命、施法、光環）。",
    ["Health text size"] = "生命文字大小",
    ["0 = uses the general text size."] = "0 = 使用一般文字大小。",
    ["Cast text size"] = "施法文字大小",
    ["Cast background colour"] = "施法背景顏色",
    ["Cast background opacity"] = "施法背景不透明度",
    ["0 = uses the global background opacity."] = "0 = 使用全域背景不透明度。",
    ["Icon scale"] = "圖示縮放",
    ["Icon on the right"] = "圖示置於右側",
    ["Icon offset X"] = "圖示 X 偏移",
    ["Icon offset Y"] = "圖示 Y 偏移",
    ["Shield on uninterruptible casts"] = "無法打斷的施法顯示盾牌",
    ["Tick where your interrupt becomes ready"] = "標示你的打斷就緒時機的刻度",
    ["Marks the spot on the enemy cast bar where YOUR interrupt comes off cooldown — everything after the tick is kickable."] = "在敵方施法條上標示「你的」打斷技能冷卻結束的位置——刻度之後的部分都打得斷。",
    ["Tick colour"] = "刻度顏色",
    ["Flash when a cast is interrupted"] = "施法被打斷時閃爍",
