    ["A thin marker line on the bar at the chosen health percentage (e.g. 20 for Execute)."] = "在條上依所選生命百分比繪製一條細標記線（例如斬殺為 20）。",
    ["Execute line only on your target"] = "只在你的目標上顯示斬殺線",
