    ["Show remaining cast time"] = "顯示剩餘施法時間",
    ["Own colour while your interrupt is on cooldown"] = "你的打斷技能冷卻中時使用自訂顏色",
    ["Interruptible casts paint differently while YOUR interrupt ability is still on cooldown — you see at a glance whether kicking is even possible."] = "當「你的」打斷技能還在冷卻中時，可打斷的施法會以不同顏色呈現——一眼就看得出打不打得斷。",
    ["Interrupt-on-cooldown colour"] = "打斷冷卻中顏色",
    ["Own bar colour on your target"] = "目標使用自訂條顏色",
    ["Your current target's health bar uses this colour instead of reaction / class / threat colours."] = "你目前目標的生命條會使用此顏色，取代態度／職業／威脅顏色。",
    ["Target bar colour"] = "目標條顏色",
    ["Mouseover highlight"] = "滑鼠指向高亮",
    ["Lightens the health bar of the plate under your mouse cursor."] = "讓滑鼠游標下名條的生命條變亮。",
    ["Target plate scale"] = "目標名條縮放",
    ["Your target's plate is drawn this much larger (100 = off)."] = "你的目標名條會依此比例放大顯示（100 = 關閉）。",
    ["Behaviour"] = "行為",
    ["|cffaaaaaaThese are the game's own nameplate settings, changed live (not part of the profile). Not changeable in combat.|r"] = "|cffaaaaaa這些是遊戲本身的名條設定，會即時變更（不屬於設定檔）。戰鬥中無法變更。|r",
    ["Plate motion"] = "名條移動方式",
    ["Overlapping"] = "重疊",
    ["Stacking"] = "堆疊",
    ["Stacked spacing"] = "堆疊間距",
    ["Vertical distance between stacked plates (a tenth of the game value)."] = "堆疊名條之間的垂直距離（遊戲數值的十分之一）。",
    ["Line-of-sight opacity"] = "視線阻擋不透明度",
    ["Opacity of plates whose unit is out of your line of sight."] = "單位不在你視線內時，其名條的不透明度。",
    ["Plate view distance"] = "名條顯示距離",
    ["|cffaaaaaaWhile the key is held (or your target matches), the main bar shows the chosen bar's abilities instead. Fully secure — works in combat.|r"] = "|cffaaaaaa按住該按鍵時（或目標符合條件時），主快捷列會改為顯示所選快捷列的技能。完全安全——戰鬥中也有效。|r",
    ["Shift held"] = "按住 Shift",
    ["Ctrl held"] = "按住 Ctrl",
    ["Alt held"] = "按住 Alt",
    ["Friendly target"] = "友方目標",
    ["Hostile target"] = "敵對目標",
