    ["Only in a party"] = "只在小隊中",
    ["Only solo"] = "只在單人時",
    ["Hide when mounted"] = "騎乘時隱藏",
    ["Hide without target"] = "沒有目標時隱藏",
    ["Hide without enemy target"] = "沒有敵方目標時隱藏",
    ["Quick keybind mode (/vkb)"] = "快速按鍵設定模式（/vkb）",
    ["Hover an action button and press a key to bind it. Hidden bars are shown while binding."] = "將滑鼠移到動作按鈕上並按下按鍵即可綁定。設定期間會顯示隱藏的快捷列。",
    ["Swipe colour"] = "掃動顏色",
    ["Icon opacity on cooldown"] = "冷卻中的圖示不透明度",
    ["Dims the whole icon while the ability is on cooldown (100 = off)."] = "技能冷卻中時使整個圖示變暗（100 = 關閉）。",
    ["Show cooldown numbers"] = "顯示冷卻數字",
    ["The game's own countdown numbers on cooldowns (a game setting, changed live)."] = "遊戲本身在冷卻上顯示的倒數數字（遊戲設定，即時變更）。",
    ["|cffaaaaaaApplies to every action bar.|r"] = "|cffaaaaaa套用於所有快捷列。|r",
    ["Cooldown swipe opacity"] = "冷卻掃動不透明度",
    ["How dark the cooldown sweep overlay is (0 = invisible)."] = "冷卻掃動覆蓋層的深淺程度（0 = 不可見）。",
    ["Desaturate icons on cooldown"] = "冷卻中的圖示去色",
    ["Out-of-range colouring"] = "超出距離著色",
    ["Tints the whole icon while your target is out of range."] = "目標超出施放距離時為整個圖示染色。",
    ["Tooltips"] = "提示資訊",
    ["Hide in combat"] = "戰鬥中隱藏",
    ["Hide always"] = "永遠隱藏",
    ["A movable, resizable experience bar with rested overlay. Hidden at max level. Replaces Blizzard's bar while on."] = "可移動、可調整大小的經驗條，含休息經驗覆蓋層。滿等時隱藏。啟用時取代暴雪的經驗條。",
    ["Hide Blizzard's XP / reputation bar"] = "隱藏暴雪的經驗／聲望條",
    ["Removes the leftover blue experience / reputation bar under the action bar."] = "移除快捷列下方殘留的藍色經驗／聲望條。",
    ["Stance bar"] = "姿態列",
    ["Pet bar"] = "寵物列",
    ["Takes over every action bar with its own movable frames: real combat/mouseover show-hide, scale and grid layout per bar, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. EXPERIMENTAL — test ability clicks and paging in combat; /reload after disabling."] = "以自己的可移動框架接管所有快捷列：真正的戰鬥／滑鼠指向顯示隱藏、每條快捷列的縮放與格狀排版、正確的主快捷列翻頁（德魯伊／盜賊／戰士／牧師姿態）以及你的按鍵設定。實驗性功能——請在戰鬥中測試技能點擊與翻頁；停用後請執行 /reload。",
    ["Standard action bars are back. Reload the interface to restore every last piece of the default layout."] = "標準快捷列已恢復。重新載入介面即可將預設配置恢復到最後一處細節。",
    ["Buttons per row"] = "每列按鈕數",
    ["Button spacing"] = "按鈕間距",
    ["Reset ALL VuloClassicUI settings for every character on this account? This cannot be undone."] = "要重設此帳號上所有角色的全部 VuloClassicUI 設定嗎？此操作無法復原。",
    ["Swing Timer switched off: it only tracks melee auto-attacks, which this character's talents do not use."] = "揮擊計時器已關閉：它只追蹤近戰自動攻擊，而此角色的天賦並不使用。",
    ["|cffff5555Settings migration %s failed:|r %s"] = "|cffff5555設定轉移 %s 失敗：|r %s",
    ["Plays a raid warning sound the moment an opponent uses their PvP trinket."] = "對手使用 PvP 飾品的瞬間播放團隊警告音效。",
    ["Flashes the icon briefly when an opponent uses their PvP trinket."] = "對手使用 PvP 飾品時短暫閃爍圖示。",
    ["Icon gap"] = "圖示間隔",
    ["Distance between the icon and the bar."] = "圖示與條之間的距離。",
    ["Accent colour"] = "強調色",
    ["Used for the bar while the fill mode is not a texture, and for channelled casts on Blizzard's own castbar."] = "當填充模式不是材質時用於條上，也用於暴雪原本施法條上的引導施法。",
    ["Cast finished"] = "施法完成",
    ["The bar flashes in this colour when a cast completes."] = "施法完成時，條會以此顏色閃爍。",
    ["Cast interrupted"] = "施法被打斷",
    ["The bar flashes in this colour when a cast is interrupted or fails."] = "施法被打斷或失敗時，條會以此顏色閃爍。",
    ["Fade-in time"] = "淡入時間",
    ["How long an icon takes to appear. 0 makes it show instantly."] = "圖示出現所需的時間。0 表示立即顯示。",
    [" and %d item(s)"] = " 和 %d 件物品",
    ["/vlfg toggles the group board."] = "/vlfg 可切換組隊看板。",
    ["Auto-apply a lure when the pole has none"] = "魚竿沒有魚餌時自動塗抹",
    ["Auto-equip a fishing pole if none is worn"] = "未裝備魚竿時自動裝備一把",
    ["Auto-loot while fishing"] = "釣魚時自動拾取",
    ["Bags are full — some items were left in the mail."] = "背包已滿——部分物品仍留在信件中。",
    ["Boost fishing sound (hear the bite clearly)"] = "強化釣魚音效（清楚聽見上鉤聲）",
    ["Burning Crusade Dungeons"] = "燃燒的遠征地城",
    ["Burning Crusade Raids"] = "燃燒的遠征團隊副本",
    ["Can't change the fishing key in combat."] = "戰鬥中無法變更釣魚按鍵。",
    ["Classic Dungeons"] = "經典舊世地城",
    ["Classic Raids"] = "經典舊世團隊副本",
    ["Clear key"] = "清除按鍵",
    ["Extra items & macros"] = "額外物品與巨集",
    ["Fishing key cleared."] = "釣魚按鍵已清除。",
    ["Fishing key set to: %s"] = "釣魚按鍵已設定為：%s",
    ["Fishing key: %s  —  click to change"] = "釣魚按鍵：%s  —  點擊以變更",
    ["Fishing sound volume"] = "釣魚音效音量",
    ["Friends"] = "好友",
    ["Guild"] = "公會",
    ["H"] = "H",
    ["Hide the reel error spam while fishing"] = "隱藏釣魚時的收竿錯誤訊息",
    ["In Progress"] = "進行中",
    ["Invite"] = "邀請",
    ["Keep requests for (minutes)"] = "保留請求的時間（分鐘）",
    ["Keep sound audible when the game is in the background"] = "遊戲在背景時仍保持音效可聽見",
    ["Keep this many bag slots free"] = "保留這麼多個背包空格",
    ["Mail emptied: looted %s%s."] = "信箱已清空：取得 %s%s。",
    ["No contacts yet"] = "尚無聯絡人",
    ["No groups forming right now."] = "目前沒有正在組隊的隊伍。",
    ["One-key reel (soft-target interact)"] = "一鍵收竿（軟目標互動）",
    ["Open All"] = "全部開啟",
    ["Press the key for fishing  (ESC to cancel)"] = "請按下用於釣魚的按鍵  （按 ESC 取消）",
    ["Print a looted summary"] = "輸出拾取摘要",
    ["Recently mailed"] = "最近寄件對象",
    ["Recipient dropdown on the Send tab"] = "寄件頁籤上的收件人下拉選單",
    ["Scan guild chat"] = "掃描公會頻道",
    ["Scan say / yell"] = "掃描說話／大喊",
    ["Scan world / trade / LFG channels"] = "掃描世界／交易／尋求組隊頻道",
    ["Set fishing key"] = "設定釣魚按鍵",
    ["Slot %d"] = "格子 %d",
    ["Speed (seconds between actions)"] = "速度（動作之間的秒數）",
    ["Take item attachments"] = "領取附件物品",
    ["Take money"] = "領取金錢",
    ["While the bobber is out, maxes effect + master volume and dims music/ambience so the splash is easy to hear. Restored when you reel in."] = "浮標在水面上時，將效果與主音量調到最大並降低音樂／環境音，讓水花聲更容易聽見。收竿時會還原。",
    ["While the bobber is out, the same key interacts with it to reel in. Needs soft-target interaction, which is enabled only while fishing and restored afterwards."] = "浮標在水面上時，同一個按鍵會與其互動以收竿。需要軟目標互動，此功能只在釣魚時啟用，之後會還原。",
    ["Whisper"] = "密語",
    ["Who"] = "查詢",
    ["Your characters"] = "你的角色",
    ["now"] = "現在",
    ["|cffaaaaaaAdds an 'Open All' button to the mailbox. It takes every attachment and coin, skipping CoD and GM mail. Shift-click the button to ignore the filters and take everything.|r"] = "|cffaaaaaa在信箱中加入「全部開啟」按鈕。它會領取所有附件與金錢，跳過貨到付款與 GM 信件。按住 Shift 點擊按鈕可忽略篩選並領取全部。|r",
    ["|cffaaaaaaItems or macros also used by the key while fishing — only when ready (off cooldown, buff missing, conditions met), then it goes back to casting. Type an item name or ID, shift-click an item into the box, or paste a /macro.|r"] = "|cffaaaaaa釣魚時該按鍵也會使用的物品或巨集——僅在就緒時（冷卻結束、缺少增益、條件符合），之後便回到拋竿。輸入物品名稱或 ID、按住 Shift 將物品點入欄位，或貼上 /macro。|r",
    ["|cffaaaaaaOne key does it all: cast, reel in, and apply a lure — then auto-loots. Set a key below, face some water, and press it.|r"] = "|cffaaaaaa一個按鍵搞定一切：拋竿、收竿、塗抹魚餌——然後自動拾取。在下方設定按鍵，面向水面按下即可。|r",
    ["|cffff5555Arena submodule OnDisable error:|r %s"] = "|cffff5555競技場子模組 OnDisable 錯誤：|r %s",
    ["Languages"] = "語言",
    ["Reminders (new module)"] = "提醒（新模組）",
    ["Arena"] = "競技場",
    ["Totems"] = "圖騰",
    ["Fixes"] = "修正",
    ["Resource Bar"] = "資源條",
    ["Settings Window"] = "設定視窗",
    ["Character Window"] = "角色視窗",
    ["Nameplates (German: Namensplaketten)"] = "名條（德文：Namensplaketten）",
    ["German client"] = "德文客戶端",
    ["Performance"] = "效能",
    ["Equipment Sets"] = "裝備組合",
    ["Spanish, French, Italian, Portuguese, Russian and Korean. All six are complete — every one of the 2244 texts is translated, nothing falls back to English. Spanish also serves Latin American clients. Choose your language under General, or leave it on Auto."] = "西班牙文、法文、義大利文、葡萄牙文、俄文與韓文。六種語言全數完成——2244 條文字全部翻譯，沒有任何一條退回英文。西班牙文同時適用於拉丁美洲客戶端。請在「一般」中選擇你的語言，或維持自動。",
    ["Shows what you are missing before a pull: weapon oils and stones, blessings, food and flask buffs, the aura or stance you forgot to set. Click a reminder to cast or use it. Off by default, found under Quality of Life."] = "在開怪前顯示你缺少的東西：武器油與磨刀石、祝福、食物與精煉藥水增益，以及忘了開啟的光環或姿態。點擊提醒即可施放或使用。預設關閉，位於「生活品質」之下。",
    ["A spark at the bar's fill point, rounded corners, aura rows you can assign freely, and your own damage-over-time effects on a row of their own."] = "條的填充處加上光點、圓角、可自由指定的光環列，以及自己的持續傷害效果獨立成一列。",
    ["Aura borders take the colour of their spell school, and an aura flashes shortly before it runs out."] = "光環邊框會採用其法術學派的顏色，光環也會在即將結束前短暫閃爍。",
    ["Level and elite text, plus overall scale and vertical offset per plate."] = "等級與精英文字，加上每個名條的整體縮放與垂直偏移。",
    ["A window can take its width or height from another window and keep it."] = "視窗可以沿用另一個視窗的寬度或高度並保持一致。",
    ["Save button. While dragging, hold Shift to lock one axis."] = "儲存按鈕。拖曳時按住 Shift 可鎖定單一軸向。",
    ["Trinket and racial cooldowns, Shadow Sight timer, a ring on the class icon for the most important aura, and range checking."] = "飾品與種族技能冷卻、暗影視域計時器、職業圖示上顯示最重要光環的圓環，以及距離檢查。",
    ["Totem icons grey out once you leave the totem's range and regain their colour when you come back."] = "離開圖騰範圍後圖騰圖示會變灰，回到範圍內時恢復顏色。",
    ["The character sheet and spellbook open in combat again. The action bars no longer set a protected field from our own code, which was the real cause."] = "角色資訊與法術書在戰鬥中可以再次開啟。快捷列不再由我們自己的程式碼設定受保護的欄位，那才是真正的原因。",
    ["The melee swing timer is off by default and only loads for melee classes and specialisations."] = "近戰揮擊計時器預設關閉，並且只會為近戰職業與專精載入。",
    ["Sliders got a proper look: soft edges, an inner shadow and a smoother hover."] = "滑桿有了像樣的外觀：柔和邊緣、內陰影與更流暢的滑鼠指向效果。",
    ["Own icons for the three collection pages, and class icons on the class tabs."] = "三個收藏頁面有了專屬圖示，職業頁籤上也加上了職業圖示。",
    ["Anchor a window to another one's edge (left/right/top/bottom) — the gap is kept edge-to-edge, so it survives either window being resized."] = "將視窗錨定到另一個視窗的邊緣（左／右／上／下）——間距以邊對邊維持，因此任一視窗調整大小後仍然有效。",
    ["Click-to-anchor: press \"Anchor to window...\" in a window's panel, then click the target window. Loop and self-anchor are blocked."] = "點擊錨定：在視窗的面板中按下 \"錨定至視窗...\"，然後點擊目標視窗。循環錨定與自我錨定會被阻擋。",
    ["While dragging, alignment lines now also show the pixel distance to the window you line up with."] = "拖曳時，對齊線現在也會顯示與你對齊的視窗之間的像素距離。",
    ["Discard button — snapshots the layout when you open Edit Mode and restores it (positions, scale, anchors and links) if you discard."] = "捨棄按鈕——開啟編輯模式時記錄版面快照，若你選擇捨棄便會還原（位置、縮放、錨點與連結）。",
    ["The drag area now covers the whole dark chat panel down to the edit box, not just the narrow message strip."] = "拖曳區域現在涵蓋整個深色聊天面板直到輸入框，而不只是狹窄的訊息區。",
    ["Fixed right-click on the chat window not opening its settings panel in Edit Mode."] = "修正在編輯模式中右鍵點擊聊天視窗無法開啟其設定面板的問題。",
    ["Interrupt help on the cast bar: own colours while your interrupt is on cooldown or ready, a tick marking where it comes back mid-cast, a shield on uninterruptible casts and an interrupt flash that can show who landed the kick."] = "施法條上的打斷輔助：你的打斷技能冷卻中或就緒時使用自訂顏色、在施法途中標示技能恢復位置的刻度、不可打斷施法上的盾牌，以及可顯示是誰成功打斷的打斷閃爍。",
    ["Cast bar suite: icon side and scale, remaining time, own background, channel colour, a warning colour when the cast aims at YOU — and on your target the cast bar lines up flush with the health bar including its border."] = "施法條套件：圖示位置與縮放、剩餘時間、自訂背景、引導顏色、施法對象是「你」時的警告顏色——而在你的目標上，施法條會連同邊框與生命條完全對齊。",
    ["Execute line, target and mouseover effects, crowd control section, combo point shapes and placement, per-element position, size and text-size controls plus a font picker."] = "斬殺線、目標與滑鼠指向效果、控場區塊、連擊點形狀與位置、各元素的位置、大小與文字大小控制，以及字型選擇器。",
    ["The options page carries a clickable live preview that stays pinned while you scroll — click any element to jump to its settings."] = "選項頁面附有可點擊的即時預覽，捲動時會固定在原處——點擊任一元素即可跳到它的設定。",
    ["Smooth health movement with a damage trail, value plus percent text layouts with short numbers, and a decimal toggle for aura timers."] = "平滑的生命值變化並帶有傷害拖尾、數值加百分比的文字排版與縮寫數字，以及光環計時器的小數點開關。",
    ["Per-bar visibility conditions (instances, mounted, target, group), modifier paging, quick keybind mode (/vkb), a sixth bar, growth directions, button text styling and cooldown look options."] = "各快捷列的顯示條件（副本、騎乘、目標、隊伍）、輔助鍵翻頁、快速按鍵設定模式（/vkb）、第六條快捷列、延展方向、按鈕文字樣式與冷卻外觀選項。",
    ["Micro menu and bag bar modern style: flat dark strips with an own monochrome icon set, plus world map, friends list, group finder, shop and key ring buttons."] = "微型選單與背包列的現代樣式：扁平深色列條搭配專屬單色圖示組，另有世界地圖、好友清單、組隊搜尋、商城與鑰匙圈按鈕。",
    ["The experience bar width now adjusts in single steps."] = "經驗條寬度現在可以逐格微調。",
    ["Visibility conditions, colour modes with gradient, background and border colours, smooth value changes, hash marks and threshold colouring."] = "顯示條件、含漸層的顏色模式、背景與邊框顏色、平滑的數值變化、刻度線與臨界值著色。",
    ["Character sheet stats panel no longer bleeds into other tabs; loadout sidebar aligns with the modern character sheet."] = "角色資訊的屬性面板不再溢出到其他頁籤；裝備配置側邊欄與現代版角色資訊對齊。",
    ["Arena points calculator panel and button wear the addon look and dock beside the character sheet."] = "競技場點數計算面板與按鈕採用插件外觀，並停靠在角色資訊旁。",
    ["The Escape menu now wears the dark addon look — flat buttons, accent title — and gains a VuloClassicUI button that opens the options window. Both have their own toggles under General."] = "Esc 選單現在採用深色插件外觀——扁平按鈕、強調色標題——並新增一個可開啟選項視窗的 VuloClassicUI 按鈕。兩者在「一般」下各有獨立開關。",
    ["The add friend dialog is skinned to match: dark panel, accent headline, dark input field and flat buttons."] = "新增好友對話框也做了相符的外觀：深色面板、強調色標題、深色輸入欄位與扁平按鈕。",
    ["Guild roster column header hover and click no longer stick out past the flat header row."] = "公會成員清單的欄位標題在滑鼠指向與點擊時不再超出扁平標題列。",
    ["The combat log filter bar now shares the exact width and height of the chat tab row, flush with the panel edge."] = "戰鬥記錄篩選列現在與聊天頁籤列的寬高完全一致，並與面板邊緣切齊。",
    ["After an update, a pulsing dot on the \"Patch Notes\" entry points at the new notes until you open them once — account wide, per version."] = "更新後，\"更新說明\" 項目上會有一個脈動圓點指向新內容，直到你開啟過一次為止——依版本記錄，全帳號通用。",
    ["With the Modern style, the equipment set sidebar now docks to the right of the stats panel at exactly the window's height, instead of overlapping it. Switching styles with the window open moves it immediately."] = "在現代樣式下，裝備組合側邊欄現在會停靠在屬性面板右側，高度剛好與視窗一致，而不再與它重疊。在視窗開啟時切換樣式會立即移動它。",
    ["Micro menu buttons that the game hides situationally are shown again, so the row no longer has a gap."] = "遊戲會視情況隱藏的微型選單按鈕重新顯示出來，因此該列不再出現空隙。",
    ["The default nameplate no longer shows through as a faint transparent bar under the custom plate — it is now hidden outright and kept hidden while the custom plate is active."] = "預設名條不再以淡淡的半透明條透出於自訂名條下方——現在會直接隱藏，並在自訂名條啟用期間持續隱藏。",
    ["All micro menu buttons open their windows again — the emptied default micro menu shell was invisibly swallowing clicks on the relocated buttons."] = "所有微型選單按鈕都能再次開啟對應視窗——被清空的預設微型選單外殼原本會在看不見的情況下吞掉移位按鈕上的點擊。",
    ["Fixed a blocked-action error when the stance bar updated during combat; stance button visibility now only changes out of combat, while icon tint, cooldown and the active marker keep updating live."] = "修正姿態列在戰鬥中更新時出現的動作受阻錯誤；姿態按鈕的顯示狀態現在只在戰鬥外變更，而圖示著色、冷卻與啟用標記仍會即時更新。",
    ["An Action Bars module puts every action bar on its own movable frame — action bars 1 to 5, the stance bar and the pet bar — each placed and scaled in Edit Mode and configured on its own."] = "快捷列模組將每條快捷列放在各自的可移動框架上——快捷列 1 到 5、姿態列與寵物列——每一條都能在編輯模式中定位與縮放，並各自獨立設定。",
    ["The main bar pages correctly with druid, rogue, warrior and priest forms, and your keybinds keep working on every bar, with the key shown on the buttons."] = "主快捷列會隨德魯伊、盜賊、戰士與牧師的姿態正確翻頁，你的按鍵設定在每條快捷列上仍然有效，並會在按鈕上顯示按鍵。",
    ["Per bar: visibility (always, mouseover, in or out of combat), opacity, icon size, buttons per row, spacing, vertical layout, reverse order, and hiding the keybind or macro text — with adjustable text sizes for keybind, macro, count and cooldown numbers."] = "每條快捷列可設定：顯示條件（總是、滑鼠指向、戰鬥中或戰鬥外）、不透明度、圖示大小、每列按鈕數、間距、垂直排列、反向排序，以及隱藏按鍵或巨集文字——按鍵、巨集、數量與冷卻數字的文字大小皆可調整。",
    ["Empty slots can be hidden and reappear automatically while you drag an ability onto the bar, and a bar can be made click-through."] = "空格可以隱藏，並在你將技能拖曳到快捷列上時自動重新出現，快捷列也可以設為滑鼠穿透。",
    ["Cooldown and look settings for all bars: cooldown sweep darkness, desaturating icons on cooldown, colouring icons while the target is out of range, and hiding button tooltips always or only in combat."] = "所有快捷列的冷卻與外觀設定：冷卻掃動的深淺、冷卻中圖示去色、目標超出距離時為圖示著色，以及永遠或僅在戰鬥中隱藏按鈕提示資訊。",
    ["An own experience bar with adjustable width, height and colour, rested overlay and progress text — it replaces the default bar while enabled and hides at the level cap."] = "專屬的經驗條，寬度、高度與顏色皆可調整，含休息經驗覆蓋層與進度文字——啟用時取代預設經驗條，並在滿等時隱藏。",
    ["The micro menu, the bag bar and the performance bar sit on movable holders, and each of them can be hidden — as can the default experience bar."] = "微型選單、背包列與效能列都放在可移動的容器上，且每一項都能隱藏——預設經驗條也一樣。",
    ["Off by default: the standard bars stay untouched until you enable the module, and disabling hands everything back (a reload fully restores the default bars)."] = "預設關閉：在你啟用模組之前，標準快捷列不會有任何變動，停用後也會把一切交還（重新載入介面可完全還原預設快捷列）。",
    ["The dark button skin now also covers the new action-bar buttons."] = "深色按鈕外觀現在也涵蓋新的快捷列按鈕。",
    ["A custom Nameplates module draws its own health bar, cast bar, name and health text over enemy and NPC nameplates — fully configurable, with a live preview that updates as you change each option."] = "自訂名條模組會在敵人與 NPC 名條上繪製自己的生命條、施法條、名稱與生命文字——完全可設定，並附有隨選項變更即時更新的預覽。",
    ["Health bar with your choice of texture, width, height, background, and a border drawn as thin lines or a texture, all in your own colours."] = "生命條可自選材質、寬度、高度與背景，邊框可繪製為細線或材質，全部使用你自訂的顏色。",
    ["Colouring by reaction (hostile, neutral, friendly, tapped) and by class for players, plus role-based threat colouring for tanks and damage dealers."] = "依態度（敵對、中立、友善、已標記）著色，玩家可依職業著色，另有針對坦克與傷害輸出的角色定位威脅著色。",
    ["Target and focus highlight rings, and an optional fade for plates that are not your target."] = "目標與專注目標的高亮框，以及可選的非目標名條淡化。",
    ["Cast bar with spell icon, spell name, and a separate colour for casts that cannot be interrupted."] = "施法條含法術圖示、法術名稱，以及不可打斷施法的獨立顏色。",
    ["Aura rows: your debuffs (or all of them), enemy buffs, and a separate prominent row for crowd control such as Polymorph, Fear and Sap. A glow marks enemy buffs you can steal or dispel."] = "光環列：你的減益（或全部減益）、敵方增益，以及變形術、恐懼術與悶棍等控場效果的獨立醒目列。發光標記代表你可以偷取或驅散的敵方增益。",
    ["Combo point pips on your target for Rogues and Druids in cat form."] = "盜賊與獵豹型態德魯伊可在目標上顯示連擊點標記。",
    ["Raid target markers (skull, cross, and the rest) with adjustable size and position."] = "團隊標記（骷髏、叉叉等）可調整大小與位置。",
    ["Friendly plates can show name only, the full plate, or nothing — set separately for players and NPCs — and can show a friendly NPC's subtitle under its name."] = "友方名條可以只顯示名稱、顯示完整名條或完全不顯示——玩家與 NPC 可分別設定——並可在友方 NPC 名稱下顯示其頭銜。",
    ["A single \"Dark Skin\" module now covers the dark action-button and WeakAuras skin plus the optional Dark Mode that darkens Blizzard's default frames — those used to be two separate modules. Your existing settings carry over."] = "單一的 \"深色外觀\" 模組現在涵蓋深色動作按鈕與 WeakAuras 外觀，以及可將暴雪預設框架變暗的選用深色模式——這些原本是兩個獨立模組。你現有的設定會沿用。",
    ["The reskin modules (skins, character panel, chat, friends list, minimap) are now one tabbed entry, matching how the other groups are already organised."] = "外觀重製模組（外觀、角色面板、聊天、好友清單、小地圖）現在合併為一個含頁籤的項目，與其他群組現有的組織方式一致。",
    ["Consolidated groups now list their modules as a vertical, icon-labelled column instead of a wrapping row of tabs — easier to scan when there are many."] = "合併後的群組現在以垂直、附圖示標籤的欄位列出其模組，而非換行的頁籤列——項目多時更容易瀏覽。",
    ["A \"Patch Notes\" page under Overview shows every version's changes right in the game."] = "「概覽」下的 \"更新說明\" 頁面可直接在遊戲中顯示每個版本的變更。",
    ["Cleaner tab names for a few tools: Training, Leisten-Profile, Apexis-Minispiel, Gruppensuche."] = "幾個工具的頁籤名稱更清楚了：Training、Leisten-Profile、Apexis-Minispiel、Gruppensuche。",
    ["The target-frame extras and the elite player-frame border are now a single module called \"Player & Target Frame\". Your existing settings and per-character on and off state carry over automatically."] = "目標框架附加功能與精英玩家框架邊框現在合併為單一模組，名為 \"玩家與目標框架\"。你現有的設定與各角色的開關狀態會自動沿用。",
    ["Settings now default to a separate profile per class, so what you set on one class no longer changes another. Your current settings are copied into each class profile, and you can still share or pin profiles as before."] = "設定現在預設為每個職業各有獨立設定檔，因此你在某個職業上的設定不會再改動另一個職業。你目前的設定會複製到每個職業的設定檔中，你仍然可以像以前一樣共用或固定設定檔。",
    ["Scrolling messages that fire at the same moment now stack with a gap instead of overlapping."] = "同時觸發的捲動訊息現在會以間隔堆疊，而不再互相重疊。",
    ["Fixed an error that could appear when combat started while your line was cast. The sound and interact settings now restore after combat ends instead."] = "修正在你已拋竿時進入戰鬥可能出現的錯誤。音效與互動設定現在改為在戰鬥結束後還原。",
    ["Lighter cast bar time text, cooldown bars that batch their refreshes during busy moments, a cheaper combat-log check for the cooldown pulse, and a lighter minimap hover check."] = "更輕量的施法條時間文字、在繁忙時段批次更新的冷卻條、冷卻脈動採用更省資源的戰鬥記錄檢查，以及更輕量的小地圖滑鼠指向檢查。",
    ["The spell stats are ordered spell power, healing, spell crit, then spell hit."] = "法術屬性依法術能量、治療、法術爆擊、法術命中的順序排列。",
    ["The Fishing and Mail tabs now read \"Angeln\" and \"Post\"."] = "釣魚與信件頁籤現在顯示為 \"Angeln\" 與 \"Post\"。",
    ["A style dropdown at the top of the module options. Classic+ keeps the current look; Modern is a new dark, single-window style."] = "模組選項最上方新增樣式下拉選單。Classic+ 維持目前的外觀；Modern 則是全新的深色單一視窗樣式。",
    ["Modern reskins the whole character window dark with an accent border and a stats panel on the right: a big equipped item level, then collapsible categories — attributes, melee, spell, defense and resistances — with per-stat hover breakdowns and mouse-wheel scrolling."] = "Modern 會將整個角色視窗重製為深色，帶有強調色邊框，右側則是屬性面板：先是大大的裝備等級，接著是可收合的分類——屬性、近戰、法術、防禦與抗性——每項屬性都有滑鼠指向的詳細說明，並支援滾輪捲動。",
    ["Under Modern the built-in stats, resistance icons and the model rotate arrows are hidden, and the reputation, skills and player-versus-player sub-tabs plus the bottom tabs are skinned to match. Everything switches back to Classic+ live, and adapts per client (rating stats only where they exist)."] = "在 Modern 之下，內建屬性、抗性圖示與模型旋轉箭頭會隱藏，聲望、技能與玩家對戰子頁籤以及底部頁籤也會套用相符的外觀。一切都能即時切換回 Classic+，並依客戶端調整（等級評分屬性只在存在時顯示）。",
    ["Dark skin for a world-map options window, with its own on and off switch in the Addon Skins options."] = "為某個世界地圖選項視窗提供深色外觀，並在插件外觀選項中設有獨立開關。",
    ["The clock now sits on the same line as the date and zone instead of floating higher."] = "時鐘現在與日期和區域位於同一行，不再浮在上方。",
    ["Dark skin for a loot-distribution addon — its award and roll windows, its settings and overview windows, and the two always-visible roll and bid bars get the house panel, accent border and flat close button."] = "為某個拾取分配插件提供深色外觀——它的分配與擲骰視窗、設定與總覽視窗，以及兩個常駐的擲骰與競標列，都會套用本體面板、強調色邊框與扁平關閉按鈕。",
    ["Dark skin for an attunement tracker — the main window and its buttons match the dark look; the colored status rows stay as they are so the state colors remain readable."] = "為某個副本許可追蹤插件提供深色外觀——主視窗與其按鈕皆採用深色外觀；彩色的狀態列維持原樣，讓狀態顏色仍然清楚可讀。",
    ["Both are separate on and off switches in the Addon Skins options, next to the others."] = "兩者在插件外觀選項中都有各自的開關，與其他項目並列。",
    ["NEW:"] = "全新：",
    ["A single unified inventory window: all bags in one grid, with quality borders, counts, cooldowns, money and free slots. Movable and scalable."] = "單一整合的物品欄視窗：所有背包集中於一個格狀清單，含品質邊框、數量、冷卻、金錢與空格。可移動與縮放。",
    ["Fixes stuck inspect bugs (no player inspect possible after a faulty close/timeout). Auto-reset after a timeout, auto-retry when the window stays empty, cleanup when InspectFrame closes + /inspectreset slash command."] = "修正觀察卡住的問題（錯誤關閉／逾時後無法再觀察玩家）。逾時後自動重設、視窗持續空白時自動重試、InspectFrame 關閉時清理，並提供 /inspectreset 指令。",
    ["A modern minimap: round with a clean dark ring and accent line, zone text and clock in a slim panel, mouse-wheel zoom, movable and scalable. Optionally hides other addons' buttons until mouseover."] = "現代化的小地圖：圓形並帶有俐落的深色環與強調線、細長面板中的區域文字與時鐘、滾輪縮放，可移動與縮放。可選擇在滑鼠指向前隱藏其他插件的按鈕。",
    ["Custom enemy & NPC nameplates with a live preview: health bar, cast bar, name and health text, reaction / class colours, target highlight and threat colouring."] = "自訂敵人與 NPC 名條並附即時預覽：生命條、施法條、名稱與生命文字、態度／職業顏色、目標高亮與威脅著色。",
    ["Hover an equipment slot for a compact flyout of compatible bag items, or modifier-click for a larger picker. Click an item to equip it."] = "將滑鼠移到裝備欄位即可看到相容背包物品的精簡快捷選單，或搭配輔助鍵點擊開啟較大的選擇視窗。點擊物品即可裝備。",
    ["Move every VuloUI window and Blizzard's default frames in one editor."] = "在單一編輯器中移動所有 VuloUI 視窗與暴雪的預設框架。",
    ["One-key fishing: one key casts, reels and applies a lure, and auto-loots your catch."] = "一鍵釣魚：一個按鍵完成拋竿、收竿與塗抹魚餌，並自動拾取你的漁獲。",
    ["Adds an 'Open All' button to your mailbox that collects every attachment and coin in one click."] = "在你的信箱中加入「全部開啟」按鈕，一鍵收取所有附件與金錢。",
    ["Top"] = "上",
    ["Bottom"] = "下",
    ["Top-Left"] = "左上",
    ["Top-Right"] = "右上",
    ["Bottom-Left"] = "左下",
    ["Bottom-Right"] = "右下",
    ["Trinkets: Cleared all ignored/hidden trinkets."] = "飾品：已清除所有忽略／隱藏的飾品。",
    ["Trinkets usage:"] = "飾品用法：",
    ["/trinket or /Trinkets : toggle the window"] = "/trinket 或 /Trinkets ：切換視窗",
    ["/trinket reset : reset all settings"] = "/trinket reset ：重設所有設定",
    ["/trinket clear : clear all ignored/hidden trinkets"] = "/trinket clear ：清除所有忽略／隱藏的飾品",
    ["/trinket opt : summon options window"] = "/trinket opt ：呼叫選項視窗",
    ["/trinket lock|unlock : toggles window lock"] = "/trinket lock|unlock ：切換視窗鎖定",
    ["/trinket scale main|menu (number) : sets an exact scale"] = "/trinket scale main|menu （數字）：設定精確的縮放",
    ["/trinket load top|bottom profilename : loads a profile to top or bottom trinket"] = "/trinket load top|bottom profilename ：將設定檔載入至上方或下方飾品",
    ["Are you sure you want to reset Trinkets to default state and reload the UI?"] = "確定要將飾品重設為預設狀態並重新載入使用者介面嗎？",
    ["Queued: %s"] = "已排入佇列：%s",
    ["Priority"] = "優先度",
    ["Pause Queue"] = "暫停佇列",
    ["Parameter must be 0 for top trinket or 1 for bottom."] = "參數必須為 0（上方飾品）或 1（下方飾品）。",
    ["No profiles saved yet."] = "尚未儲存任何設定檔。",
    ["Visuals"] = "視覺",
    ["The language option under General now actually applies. It silently never took effect — the addon read the client language before your saved choice was loaded. After a /reload every label, dropdown and popup follows your choice."] = "「一般」下的語言選項現在真的會生效。它原本默默地毫無作用——插件在你儲存的選擇載入之前就先讀取了客戶端語言。執行 /reload 後，所有標籤、下拉選單與彈出視窗都會依照你的選擇。",
    ["The Patch Notes page is translated into all languages, including every past version."] = "更新說明頁面已翻譯成所有語言，包含每一個過往版本。",
    ["The trinket panel, its queue window and the /trinket help are translated too."] = "飾品面板、它的佇列視窗與 /trinket 說明也都已翻譯。",
    ["German: sixteen duplicated translations cleaned up, five of which contradicted each other."] = "德文：清理了十六處重複的翻譯，其中五處彼此矛盾。",
    ["Third pass over the busiest code paths: nameplate auras scan once instead of four times, combat-log and aura events skip a safety wrapper, timer texts only redraw when the shown number changes, and several background listeners now sleep while their feature is off or hidden. Less stutter in raids and arenas."] = "對最繁忙的程式路徑進行第三輪優化：名條光環只掃描一次而非四次、戰鬥記錄與光環事件略過一層安全包裝、計時器文字只在顯示的數字改變時重繪，並且數個背景監聽器會在其功能關閉或隱藏時進入休眠。團隊與競技場中的卡頓更少。",
    ["The frames can be turned off again without leftovers."] = "這些框架可以再次關閉而不留下殘餘。",
    ["An interrupted enemy cast now shows INTERRUPTED briefly — it used to vanish the same instant."] = "被打斷的敵方施法現在會短暫顯示「已打斷」——過去它會在同一瞬間消失。",
    ["Diminishing-returns icons clean up correctly after toggling the tracker mid-arena."] = "在競技場中途切換追蹤器後，遞減效果圖示會正確清除。",
    ["Seven working settings that were invisible in the options are shown again, and several switches that did nothing are wired up."] = "七個原本能運作卻在選項中看不見的設定重新顯示出來，數個毫無作用的開關也接上了功能。",
    ["Modules tidy up after themselves when disabled: totem range dimming, the inspect window, queue timer, quest log and font bars no longer leave stale pieces behind."] = "模組停用時會自行清理：圖騰距離變暗、觀察視窗、佇列計時器、任務記錄與字型列不再留下失效的殘餘元件。",
    ["Three modules got their own sidebar icons instead of the placeholder, and Reminders got a nicer bell."] = "三個模組有了自己的側邊欄圖示，不再使用預留圖示，提醒模組也換上更好看的鈴鐺。",
    ["Quest starter marker (!)"] = "任務起始標記（!）",
    ["Overlays a yellow exclamation mark on items that start a quest you have not accepted yet."] = "在可開啟你尚未接受任務的物品上疊加黃色驚嘆號。",
    ["|cffff5555Options page '%s' failed to build:|r %s"] = "|cffff5555選項頁面 '%s' 建立失敗：|r %s",
    ["|cffff5555This page could not be built. /reload, and report it if it persists.|r"] = "|cffff5555此頁面無法建立。請執行 /reload，若問題持續請回報。|r",
    ["|cff888888%.2f ms/frame |cff666666(%.1f%% of ours, peak %.1f ms)|r|r"] = "|cff888888%.2f 毫秒/影格 |cff666666（佔我們的 %.1f%%，尖峰 %.1f 毫秒）|r|r",
    ["|cffaaaaaaThe header shows how much frame time VuloClassicUI costs. Your client measures this on its own, all the time — no setting and no reload needed.|r"] = "|cffaaaaaa標題列會顯示 VuloClassicUI 佔用多少影格時間。你的客戶端會自行持續測量——不需要任何設定，也不需要重新載入。|r",
    ["Classic Era, Hardcore and Season of Discovery"] = "經典時代、專家模式與探索賽季",
    ["Under the hood"] = "底層改進",
    ["The addon loads again without ticking \"Load out of date AddOns\". Blizzard's July interface update moved these realms to a new version number."] = "不必勾選 \"載入過期的插件\" 插件也能再次載入。暴雪七月的介面更新將這些伺服器移到了新的版本號。",
    ["Fixed a crash that switched the whole Class Trainer page off on Season of Discovery: one ability the realm does not know took the entire module down with it."] = "修正在探索賽季中導致整個職業訓練師頁面關閉的當機：一個伺服器不認識的技能拖垮了整個模組。",
    ["The elite border on your player frame sits correctly again. It was placed against the old frame layout, which that same update replaced."] = "玩家框架上的精英邊框再次正確定位。它原本是依照舊的框架排版擺放，而該次更新已將其取代。",
    ["Fixed a rare error storm at the end of a fight. Cleanup work in nineteen files could be skipped and the chat filled with error lines."] = "修正戰鬥結束時罕見的錯誤風暴。十九個檔案中的清理工作可能被略過，導致聊天視窗充滿錯誤訊息。",
    ["Combat log features (swing timer, cooldown pulse, combat text, arena tracker, nameplates, mana display) no longer depend on a setting a player can switch off."] = "戰鬥記錄相關功能（揮擊計時器、冷卻脈動、戰鬥文字、競技場追蹤器、名條、法力顯示）不再依賴玩家可以關閉的設定。",
    ["An interrupted enemy cast now really shows INTERRUPTED for a moment."] = "被打斷的敵方施法現在真的會短暫顯示「已打斷」。",
    ["Items that start a quest you have not accepted yet are marked with a yellow exclamation mark, in bags, bank and keyring."] = "可開啟你尚未接受任務的物品，會在背包、銀行與鑰匙圈中標上黃色驚嘆號。",
    ["Seven of the eight shipped translations no longer build their lookup table at all. Only the language you actually read is assembled, which frees about a megabyte on every login."] = "隨附的八種翻譯中，有七種完全不再建立查詢表。只有你實際閱讀的語言會被組建，這讓每次登入省下約一 MB 記憶體。",
    ["Edit Mode: three background drivers no longer run permanently, dragging a window allocates far less, and finding a window is a direct lookup instead of a search."] = "編輯模式：三個背景驅動不再持續運作、拖曳視窗時配置的記憶體大幅減少，尋找視窗也改為直接查詢而非搜尋。",
    ["Disabling a module now detaches it completely — several used to leave listeners running for the rest of the session."] = "停用模組現在會將它完全卸離——過去有數個模組會讓監聽器在該次遊戲期間持續運作。",
    ["The performance readout in the header uses your client's own always-on measurement, so it needs no setting and no reload."] = "標題列中的效能讀數使用客戶端本身持續運作的測量，因此不需要設定，也不需要重新載入。",
    ["Nothing measured yet. Play for a bit, then read it again."] = "尚未測得任何資料。先玩一會兒，再回來查看一次。",
    ["Measured over %.1f s -- %.1f ms total, %.2f%% of it ours:"] = "測量時間 %.1f 秒 -- 總計 %.1f 毫秒，其中 %.2f%% 屬於我們：",
    ["Measurement off."] = "測量已關閉。",
    ["Measurement reset."] = "測量已重設。",
    ["Measurement on. Play, then type /vcuiprof again to read it."] = "測量已開啟。玩一段時間後再輸入 /vcuiprof 讀取結果。",
    ["Class Trainer page"] = "職業訓練師頁面",
    ["Fixed the page being thrown away again a moment after you opened it, dropping you back on a class tab. The spell book resets its own page whenever your spells change, and our page sits past the last real tab, so it was always the one discarded. Most noticeable on Season of Discovery, where engraving changes spells constantly."] = "修正頁面在你開啟後片刻又被丟棄、把你退回職業頁籤的問題。法術書在你的法術變動時會重設自己的頁面，而我們的頁面位於最後一個真實頁籤之後，因此總是被丟棄的那一個。在法術會因刻印不斷改變的探索賽季中最為明顯。",
    ["`/vcuiprof` measures how much frame time each part of the addon costs, then prints a list. It ships switched off and costs nothing while it is — the measuring code is only put in place when you turn it on. Type it once to start, once more to read."] = "`/vcuiprof` 會測量插件各部分佔用多少影格時間，然後輸出一份清單。它預設關閉，關閉時完全不耗資源——測量程式碼只會在你開啟時才裝上。輸入一次開始測量，再輸入一次讀取結果。",
    ["Clicking a trinket button while that trinket slot is empty no longer throws an error. The game's own shortcut for \"use the item in slot N\" stopped tolerating an empty slot with July's interface update, so the button now takes a different route to the same action."] = "在飾品欄位為空時點擊飾品按鈕不再產生錯誤。遊戲本身 \"使用第 N 格物品\" 的捷徑在七月的介面更新後不再容許空欄位，因此該按鈕現在改以其他方式達成相同的動作。",
    ["Fixed a stutter of almost two frames every time you entered or left combat, if you use WeakAuras and have the WeakAuras skin switched on. Every combat change repainted every aura you have ever saved — including the ones not on screen — with a look that had not changed. Auras are now only repainted when the settings or their size actually changed. Measured: 28 ms down to under 2 ms. The skin itself is unchanged."] = "修正在你使用 WeakAuras 並開啟 WeakAuras 外觀時，每次進入或離開戰鬥都會出現將近兩個影格卡頓的問題。每次戰鬥狀態改變，都會以未曾變動的外觀重繪你曾儲存過的每一個光環——包括不在畫面上的。現在只有在設定或大小確實改變時才會重繪光環。實測：28 毫秒降到 2 毫秒以下。外觀本身沒有變動。",
    -- Patch notes 1.39.0
    ["Download"] = "下載",
    ["Diminishing Returns Position – Put the DR row on either side of the frame, with its own X and Y offset"] = "遞減效果位置 – 可將該列放在框架任一側，並有自己的 X、Y 位移",
    ["The DR row no longer lands on top of the trinket or racial icon. It used to hang at a fixed distance on the right edge, exactly where the side icon sits, so switching it on stacked the two. The new default clears it, and on the left edge the row grows outward instead of across the frame."] = "遞減效果那一列不再壓在飾品或種族技能圖示上。它以前固定挂在右邊緣的某個距離上，而那裡正是側邊圖示所在的位置，所以一打開兩者就疊在一起。新的預設值讓它避開該位置，在左邊緣時該列會向外延伸，而不是橫越框架。",
    ["The trinket and racial icons sit further out from the enemy frame and are a little smaller, so the health and mana bars read as the middle of the frame instead of competing with an icon at each shoulder. Both are sliders, so your own values are kept."] = "飾品與種族技能圖示離敵方框架更遠，也略小了一些，因此生命值與魔法值條讀起來就是框架的中心，而不必與兩肩各一個圖示爭奪注意力。兩者都是滑桿，因此你自己設定的數值會保留。",
    ["The addon folder no longer ships build tools and source files that no player needs. The licence files stay where they are."] = "插件資料夾不再附帶任何玩家都用不到的建置工具與原始檔。授權檔案仍然保留在原處。",
    ["The release notes on the distribution pages are written in English now."] = "發布頁面上的版本說明現在以英文撰寫。",
    ["Six languages were missing seven texts that existed in German only. All nine are complete again."] = "有六種語言缺少七條只存在於德語中的文字。現在九種語言都重新完整。",
    ["The keyword help for the item search was misleading in Chinese: it gave an English type name as the example, which a Chinese client would never have matched. The example is written in the reader's own language now."] = "物品搜尋的關鍵字說明在中文下有誤導性：它給出的範例是英文的類型名稱，而中文客戶端永遠不會比對到。現在範例會以讀者自己的語言書寫。",
    ["Seal Twist Helper – A swing bar with the twist window marked, plus the next sensible action"] = "聖印切換輔助 – 帶有切換視窗標記的揮擊進度條，以及下一步合理的動作",
    ["The bar counts down to your next auto attack with two marks: green is the last moment the second seal can still land, purple is how long a Judgement still fits in front of it. The next action is worked out live from your swing timer, the global cooldown and the seals actually on you — not from a fixed rotation. Crusader Strike is only suggested while there is room for it and the holding seal afterwards. Judgement deliberately gets none: it consumes the seal, and a wrong hint costs more there than no hint. Off by default."] = "進度條倒數到你的下一次自動攻擊，上面有兩個標記：綠色是第二個聖印還能生效的最後時刻，紫色表示在它之前還塞得下一次制裁的時間。下一步動作根據你的揮擊節奏、公共冷卻時間以及你身上實際生效的聖印即時計算——而不是照搬固定循環。只有在十字軍打擊以及之後的保持聖印都還有空間時，才會建議使用十字軍打擊。制裁刻意不給任何建議：它會消耗聖印，在那裡給錯提示比不給提示代價更大。預設關閉。",
    -- Sidebar groups (QoL split, 1.40.0)
    ["Bags & Items"] = "背包與物品",
    ["Chat & Social"] = "聊天與社交",
    ["Extras"] = "雜項",
    ["Tools"] = "工具",
    -- Overview page
    ["peak %.1f ms"] = "峰值 %.1f 毫秒",
    ["%.2f ms"] = "%.2f 毫秒",
    ["%.1f MB"] = "%.1f MB",
    ["%d KB"] = "%d KB",
    ["%d of %d"] = "%d / %d",
    ["moved"] = "已移動",
    ["Modules"] = "模組",
    ["Frame time"] = "影格時間",
    ["Memory"] = "記憶體",
    ["Windows"] = "視窗",
    ["%d modules are switched off."] = "有 %d 個模組已關閉。",
    ["The edit mode grid is switched on."] = "編輯模式的格線已開啟。",
    ["There are patch notes you have not read yet."] = "有你尚未閱讀的版本說明。",
    ["What would you like to change?"] = "你想設定什麼？",
    ["Worth knowing"] = "值得一看",
    ["Recently visited"] = "最近造訪",
    -- Talent overrides
    ["active"] = "已啟用",
    ["Talent Overrides"] = "按天賦方案覆寫",
    ["Talent group %d"] = "天賦方案 %d",
    ["%d settings overridden"] = "已覆寫 %d 項設定",
    ["Forget all overrides for this talent group"] = "忘記此天賦方案的所有覆寫",
    ["Overrides apply on their own when you switch talent groups. This client has no specialisations, so the dual talent system is the axis."] = "切換天賦方案時覆寫會自動生效。本客戶端沒有專精，因此以雙天賦系統為準。",
    -- Override groups
    ["Talent group %d (%s)"] = "天賦方案 %d (%s)",
    ["Name for the new group"] = "新群組的名稱",
    ["Editing as"] = "正在編輯",
    ["Yourself"] = "你自己",
    ["Manage groups..."] = "管理群組...",
    ["Owns the current talent group"] = "適用於目前天賦方案",
    ["Delete this group"] = "刪除此群組",
    ["No groups yet."] = "尚無群組。",
    -- Anchor points
    ["Centre"] = "置中",
    ["Thin outline"] = "細描邊",
    ["Bar Setups"] = "快捷列設定",
    -- Patch notes 1.40.0
    ["Moved out of the sidebar into Global Settings, as its own tab beside Profiles. Your saved setups were kept."] = "已從側邊欄移到全域設定，成為緊鄰設定檔的獨立分頁。你儲存的配置都還在。",
    ["They were stored once per class profile — seven copies of one macro library. Stored once now, which cut the settings file by a third. Identical copies are merged, ones that differ are kept side by side."] = "它們先前依職業設定檔各存一份——同一個巨集庫存了七遍。現在只存一份，設定檔因此縮小了三分之一。內容相同的副本會合併，不同的則並列保留。",
    ["The chat window no longer jumps back the moment you open the edit mode. Switching layouts re-anchors every window the game knows about, including ones we place ourselves."] = "打開編輯模式時，聊天視窗不會再彈回原位。切換版面配置會重新錨定遊戲已知的每一個視窗，包括由本插件自己擺放的那些。",
    ["A dropdown with a long entry no longer wraps into the row below it."] = "項目較長的下拉選單不會再折行擠到下一列。",
    ["The first page is a picture of your interface instead of a second sidebar: modules running, frame time and memory, windows you moved, pages you last visited."] = "首頁現在顯示介面的狀態，而不是第二個側邊欄：執行中的模組、影格時間與記憶體、你移動過的視窗，以及最近造訪的頁面。",
    ["Talent Overrides – Named groups hold their own value for individual settings and apply when you switch talent specs"] = "天賦覆寫 – 具名群組為個別設定保存各自的數值，切換天賦配置時自動生效",
    ["A group can also name a situation — raid, dungeon, arena, battleground, in a group, alone. Anything you change while a group is active is recorded into it, and every overridden row is marked."] = "群組還可以指定情境：團隊副本、地城、競技場、戰場、在隊伍中、單人。群組生效期間你改動的一切都會記入該群組，每一列被覆寫的設定都有標記。",
    ["Sliders are one row like every other setting, their number can be typed into, and labels line up in a measured column across the page. A long translation no longer pushes a value box into the next column or a button off its card."] = "滑桿現在和其他設定一樣只佔一列，數值可以直接輸入，標籤在整頁範圍內依實測寬度對齊。較長的譯文不會再把數值框擠進相鄰欄位，也不會把按鈕擠出卡片。",
    ["Every section starts closed, so a long page opens as a list of headings."] = "每個區段預設摺疊，因此長頁面打開時就是一份標題清單。",
    ["The automatic swap queue has controls again — order, delay and the stop marker, on the trinket page. They only ever existed in a window this addon hides."] = "自動更換佇列重新有了操作介面：順序、延遲和停止標記都在飾品頁面上。它們先前只存在於本插件隱藏起來的視窗裡。",
    ["Trinket icons show up again: on the buttons, on the queue marker, and on your worn trinkets right after login instead of only once you click them."] = "飾品圖示重新顯示：按鈕上、佇列標記上，以及登入後立刻顯示已佩戴的飾品，而不必先點一下。",
    -- Befehlsregistratur
    ["%s has no handler yet — this is a bug, please report it."] = "%s 還沒有對應的處理程式——這是一個缺陷，請回報。",
    ["%s belongs to %s, which is switched off."] = "%s 屬於 %s，而它已關閉。",
    ["|cff9b6cffCommands|r — %d in total. Grey ones belong to a module that is switched off."] = "|cff9b6cff指令|r——共 %d 條。灰色的屬於已關閉的模組。",
    ["%s is also claimed by another addon (%s) — one of the two wins."] = "%s 也被另一個插件（%s）占用——兩者只有一個生效。",
    -- v1.40.0 nachgezogen
    ["|cffff5555Bar setups module not loaded.|r"] = "|cffff5555快捷列設定模組未載入。|r",
    ["Bar setup '%s' saved."] = "快捷列設定 '%s' 已儲存。",
    ["Bar setup '%s' deleted."] = "快捷列設定 '%s' 已刪除。",
    ["Not in combat — bars can't be changed while fighting."] = "不在戰鬥中——戰鬥時無法變更快捷列。",
    ["Bar setup '%s' loaded: %d slots set, %d cleared, |cffff8800%d skipped|r (unknown spell / missing item or macro)."] = "快捷列設定 '%s' 已載入：設定 %d 格，清空 %d 格，|cffff8800跳過 %d 格|r（未知法術／缺少物品或巨集）。",
    ["Bar setup '%s' loaded: %d slots set, %d cleared."] = "快捷列設定 '%s' 已載入：設定 %d 格，清空 %d 格。",
    ["on"] = "開",
    ["Overridden settings: %s"] = "被覆寫的設定：%s",
    ["Situation"] = "情境",
    ["Everywhere"] = "任何地方",
    ["Raid instance"] = "團隊副本",
    ["5-player instance"] = "5人副本",
    ["Battleground"] = "戰場",
    ["In a group"] = "在隊伍中",
    ["Alone"] = "單人",
    ["Applies only in this situation. Combined with a talent group, both have to be true - and that group then overrides one that names only the talent group."] = "僅在此情境下生效。與天賦配置同時指定時，兩者都必須成立——此時該群組優先於只指定天賦配置的群組。",
    ["Icon"] = "圖示",
    ["No icon"] = "無圖示",
    ["Shown in front of the group name in the menu and on the header button."] = "顯示在選單中群組名稱的前面，以及標題按鈕上。",
    ["Switch off to drop this one override. The setting then follows the profile again."] = "關閉只會移除這一條覆寫。該設定隨後重新跟隨設定檔。",
    ["Bar setups are now stored once for the whole account: %d kept, %d duplicates merged."] = "快捷列設定現在整個帳號只存一份：保留 %d 個，合併重複 %d 個。",
    ["Trinket window settings now live in this addon's own database."] = "飾品視窗的設定現在存放在本插件自己的資料庫中。",
    ["Auto queue: top slot"] = "自動佇列：上方格子",
    ["Auto queue: bottom slot"] = "自動佇列：下方格子",
    ["Auto queue for this slot"] = "此格子的自動佇列",
    ["Same switch as alt-clicking the slot. While on, the queue swaps this trinket in combat, following the order below."] = "與 Alt+點擊該格子是同一個開關。開啟後，佇列會在戰鬥中依下面的順序更換此飾品。",
    ["Order"] = "順序",
    ["The queue works through this list from the top. Pick an entry to move it or to change its settings."] = "佇列從上往下處理這個清單。選取一項即可移動它或修改它的設定。",
    ["- empty -"] = "- 空 -",
    ["— queue stops here —"] = "—— 佇列到此為止 ——",
    ["Add from bags"] = "從背包新增",
    ["Adds a trinket you are carrying to the end of this list."] = "把你身上帶著的一件飾品加到這個清單末尾。",
    ["Swap delay"] = "更換延遲",
    ["Seconds this trinket stays equipped before the queue swaps it out again. 0 = no wait."] = "此飾品保持裝備的秒數，之後佇列才會再次更換。0 = 不等待。",
    ["This trinket is swapped in ahead of the ones above it once it is ready."] = "此飾品一旦就緒，就會先於上面的幾件被換上。",
    ["Pause while equipped"] = "裝備期間暫停",
    ["While this trinket is worn the queue holds still - for a trinket whose effect you do not want cut short."] = "只要戴著這件飾品，佇列就保持不動——適合不想被打斷效果的飾品。",
    ["|cffaaaaaaTip: left click a slot to use the trinket, right click for the list. Alt-click arms the auto queue for that slot.|r"] = "|cffaaaaaa提示：左鍵點擊格子使用飾品，右鍵開啟清單。Alt+點擊可為該格子啟用自動佇列。|r",
    ["%d snapshot(s) had the same name but different contents and were kept under a new name."] = "有 %d 份快照名稱相同但內容不同，已用新名稱保留。",
    ["GAP"] = "間距",
    ["Distance from that edge, in pixels. 0 is flush."] = "與該邊緣的距離，單位為像素。0 表示緊貼。",
    ["Docks this window to that side of the target and centres it there. 'Centered' does not move it - it only travels along. The gap is kept edge-to-edge, so it survives either window being resized."] = "把這個視窗停靠到目標視窗的該側並在該側置中。'置中' 不會移動它——只是讓它跟隨。間距按邊到邊保持，因此兩個視窗任一改變大小都不受影響。",
    ["waiting for a swing"] = "等待揮擊",
    ["  -  lag %.0fms"] = "  -  延遲 %.0f毫秒",
    ["|cffff8800No seal to twist out of. Only Seal of Command and Seal of Righteousness carry over to a swing after being replaced, so one of the two has to be learned.|r"] = "|cffff8800沒有可供切換出來的聖印。只有命令聖印和公正聖印在被替換後仍會作用於那一擊，因此必須學會其中之一。|r",
    ["|cffff8800Only one seal learned. A second one is needed to twist into.|r"] = "|cffff8800只學會了一個聖印。切換還需要第二個。|r",
    ["|cffff8800The seal you hold cannot be twisted out of. Only Seal of Command and Seal of Righteousness carry over to the swing that replaces them.|r"] = "|cffff8800無法從你保持的聖印切換出來。只有命令聖印和公正聖印在被替換時仍會作用於那一擊。|r",
    ["Only Seal of Command and Seal of Righteousness work here: they are the two whose effect still lands on the swing that replaces them."] = "這裡只能選命令聖印和公正聖印：只有這兩個在被替換時，效果仍會作用於那一擊。",
    -- Namensplaketten-Vorlage
    ["Nameplate settings replaced. Switch profile to get the old ones back."] = "名條設定已替換。切換設定檔即可恢復原本的設定。",
    ["Overwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched."] = "以寬、扁平、深色的外觀覆寫此設定檔的名條設定。其他設定檔不受影響。",
    ["|cffaaaaaaOverwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched.|r"] = "|cffaaaaaa以寬、扁平、深色的外觀覆寫此設定檔的名條設定。其他設定檔不受影響。|r",
    ["Apply the wide, flat look"] = "套用寬扁外觀",
    -- Plaetze der Namensplaketten
    ["Main positions"] = "主要位置",
    ["|cffaaaaaaOne thing per slot. Giving a slot something takes it away from the slot that had it.|r"] = "|cffaaaaaa每個位置只放一樣。把某項放到一個位置，就會從原本的位置移走。|r",
    ["Debuffs"] = "減益效果",
    ["Buffs"] = "增益效果",
    ["Crowd control"] = "控制效果",
    ["Your own debuffs"] = "你自己的減益效果",
    -- Leuchten bei wenig Leben, Entzauber-Leuchten
    ["Glow when low on health"] = "生命值低時發光",
    ["A coloured ring around the bar once the unit drops below the mark."] = "目標掉到標記以下時，血條周圍出現一圈彩色邊框。",
    ["Glow below (%)"] = "低於此值發光 (%)",
    ["Low health colour"] = "低生命值顏色",
    ["Glow in the aura's own school colour"] = "依效果自身的類型顏色發光",
    ["Magic blue, curse purple, disease orange, poison green — instead of one colour for everything."] = "魔法藍、詛咒紫、疾病橙、中毒綠——而不是所有效果一個顏色。",
    -- Absorptionsstil
    ["Absorb style"] = "吸收護盾樣式",
    ["Flat colour"] = "純色",
    -- Zauberziel
    ["Show who the cast is aimed at"] = "顯示施法目標",
    ["The caster's current target, beside the cast bar. Your own name is coloured."] = "在施法條旁邊顯示施法者目前的目標。你自己的名字會以顏色突顯。",
    ["Cast target size"] = "施法目標字級",
    -- Zielpfeile
    ["Arrows beside your target"] = "目標兩側的箭頭",
    ["Two arrows pointing in at the target's bar, one on each side."] = "兩個箭頭從兩側指向目標的血條。",
    ["Arrow size"] = "箭頭大小",
    ["Arrow distance"] = "箭頭間距",
    ["Arrow colour"] = "箭頭顏色",
    -- Fokus-Merkzeichen
    ["Mark on the focus plate"] = "焦點名條上的標記",
    ["A short text on your focus target's plate. A ring says this one is special; the mark says which."] = "在焦點目標的名條上顯示一小段文字。邊框說明這個特別，標記說明它是哪一個。",
    ["Mark text"] = "標記文字",
    ["Mark position"] = "標記位置",
    ["Mark size"] = "標記大小",
    -- Kleine Plaketten
    ["Back to the small plates"] = "回到小型名條",
    ["Puts the same settings back to the small plates this addon ships with."] = "把同一批設定恢復成本插件自帶的小型名條。",
    ["|cffaaaaaaHold Seal of Command, then cast the second seal in the last fraction of a second before your auto-attack: that swing carries both. Below level 64 the second seal is Righteousness; Blood and the Martyr replace it from there.|r"] = "|cffaaaaaa保持命令聖印，然後在自動攻擊落下前的最後一瞬施放第二個聖印：這一擊就會同時帶上兩個。64 級以下第二個聖印是公正聖印；從 64 級起由鮮血聖印和殉難聖印取代。|r",
    ["|cffaaaaaaThe bar counts down to the swing in zones: |cff5c8aebblue|r is free for a filler, |cffd93636red|r is the stretch where a cast would still be on the global cooldown when the window opens, and |cff33ff66green|r is the twist window. The last mark inside the green is the late twist, which leaves room for a judgement in front of the seal.|r"] = "|cffaaaaaa進度條按區間倒數到下一次揮擊：|cff5c8aeb藍色|r 可以自由插入填充技能，|cffd93636紅色|r 是此時施法會讓公共冷卻延續到視窗開啟的區段，|cff33ff66綠色|r 則是切換視窗。綠色裡最後一道標記是延後切換，前面還能塞進一次審判。|r",
    ["Late twist window (seconds)"] = "延後切換視窗（秒）",
    ["The tail of the twist window, marked separately. Twisting that late still leaves room for a judgement in front of the seal. Set it as long as the twist window to hide the mark."] = "切換視窗的末段，單獨標出。切得這麼晚，前面還塞得下一次審判。設成與切換視窗一樣長即可隱藏這道標記。",
    ["Second cue for the late window"] = "延後視窗的第二個提示音",
    ["A different sound at the late twist mark, so the two ends of the window can be told apart without looking at the bar."] = "在延後切換標記處發出不同的聲音，不看進度條也能分辨視窗的兩端。",
    ["Shade the zones"] = "為區間著色",
    ["Tints the part of the swing still to come in the colour of the zone it runs into."] = "把這一擊尚未走完的部分染成它將進入的區間顏色。",
    ["Show the marks"] = "顯示標記",
    ["The three boundary lines: danger zone, twist window, late twist."] = "三道分界線：危險區、切換視窗、延後切換。",
    ["Show seal indicators"] = "顯示聖印指示",
    ["The seals currently on you and how long they last, right of the bar. Both show while the twist is in -- that overlap is the pay-off."] = "目前身上的聖印及其剩餘時間，顯示在進度條右側。切換成功時兩個都會顯示，這段重疊正是收益所在。",
    ["Seal icon size"] = "聖印圖示大小",
    ["Head start for the prompt (ms)"] = "提示提前量（毫秒）",
    ["Shows the twist prompt and plays its cue this far before the window actually opens, so there is time to see it and press. The colours on the bar stay exact."] = "在視窗真正開啟前這麼久就顯示切換提示並播放提示音，好讓你有時間看到並按下。進度條上的顏色仍然是精確時點。",
    ["auto"] = "普攻",
    ["Twist only"] = "只切換",
    ["Rotation"] = "循環",
    ["Show the rotation helper"] = "顯示循環輔助",
    ["A row of steps above the bar: which sequence fits your weapon and haste, and where in it you are. It steps forward on what you actually cast and on your swings."] = "在進度條上方排出一行步驟：哪套順序適合你的武器和加速，以及你此刻走到哪一步。它按你實際施放的技能和揮擊往前推進。",
    ["Sequence"] = "順序",
    ["Automatic follows your attack speed and spell haste, which is what decides how many twists fit between two strikes. Pick one by hand to drill a single sequence."] = "自動會跟隨你的攻擊速度和法術加速——兩次打擊之間能塞進幾次切換由它們決定。想只練一套順序時手動選擇。",
    ["Rotation icon size"] = "圖示大小",
    ["Sound when the twist lands"] = "切換成功時播放聲音",
    ["Hit sound"] = "命中音",
    ["Listen"] = "試聽",
    ["Chime"] = "鈴聲",
    ["Raid warning"] = "團隊警報",
    ["Ready check"] = "就位確認",
    ["Click"] = "點擊",
    -- Patch notes 1.41.0
    ["Moving a frame could throw a blocked-action error if you happened to be in combat while the frames were built. The keyboard is only taken over once a mover is on screen."] = "在視窗建立時你正好處於戰鬥中，移動視窗可能觸發動作被阻擋的錯誤。現在只有移動框出現在畫面上之後才會接管鍵盤。",
    ["The trinket window's settings were being written to the saved file a second time under their old names. They are stored once now."] = "飾品視窗的設定會以舊名稱在存檔檔案裡再寫一份。現在只存一份。",
    ["42 texts existed in German only, among them the whole talent override interface and the trinket queue. All nine languages are complete again."] = "有 42 段文字只有德語版本，其中包括天賦覆寫的整個介面和飾品佇列。九種語言重新完整。",
    ["Main positions – Six slots around the plate, each holding one thing: debuffs, buffs, crowd control or your own damage-over-time"] = "主要位置 – 名條周圍六個位置，每個只放一樣：減益效果、增益效果、控制效果，或你自己的持續傷害",
    ["Glow when low on health – A coloured ring once the unit drops past your mark"] = "生命值低時發光 – 目標掉到你設定的標記以下時出現彩色邊框",
    ["Arrows beside your target – Two arrows pointing in at the bar"] = "目標兩側的箭頭 – 兩個箭頭從兩側指向血條",
    ["Mark on the focus plate – A short text, so target and focus stay apart at a glance"] = "焦點名條上的標記 – 一小段文字，讓目標和焦點一眼分得開",
    ["Preset – One click for a wide, flat, dark look, and one to put the small plates back"] = "範本 – 一鍵切換到寬、扁平、深色的外觀，另一鍵切回小型名條",
    ["Two of the six slots sit beside the plate as a column, which was not possible before. And two rows can no longer land on top of each other: giving a slot something takes it away from the slot that had it."] = "六個位置裡有兩個以直排放在名條旁邊，這在以前做不到。而且兩列不會再疊在一起：把某項放到一個位置，就會從原本的位置移走。",
    ["The cast bar can name who the cast is aimed at, your own name coloured."] = "施法條可以顯示施法針對的目標，你自己的名字會以顏色突顯。",
    ["Twist zones – The swing bar answers what you may press now instead of counting down"] = "切換區間 – 揮擊條回答你現在可以按什麼，而不是倒數計時",
    ["Rotation helper – A short sequence rather than a single next step, worked out from your weapon and cast speed"] = "手法助手 – 給出一小段順序，而不是單獨的下一步，依據你的武器速度和施法速度算出",
    ["The seal you twist into may be any other seal, not only the two that arrive at level 64."] = "你切換進入的印記可以是任何其他印記，不只是 64 級才有的那兩個。",
    ["Sections no longer fold away. Long pages fold at the gear on a row instead, which says something a section expander never could: the rows behind it belong to the switch it sits on."] = "分區不再摺疊。長頁面改為在某一列的齒輪上摺疊，而齒輪說出了分區摺疊從來說不出的事：它後面的列屬於它所在的那個開關。",
    ["Controls line up down a page now, and a switch sits in the middle of its row."] = "各個控制項沿頁面對齊，開關位於所在列的正中。",
    -- Vier Nachzuegler
    ["Darken enemies out of combat"] = "戰鬥外的敵人變暗",
    ["Dims enemies that are not fighting anyone, so the ones that are stand out. Never your own target."] = "把沒有在與誰交戰的敵人調暗，讓正在交戰的顯出來。不會影響你自己的目標。",
    ["Darken to (%)"] = "變暗到 (%)",
    ["Cast bars in front of other plates"] = "施法條顯示在其他名條之前",
    ["In a pull the plates overlap and a cast bar can end up behind the plate in front of it."] = "拉怪時名條會互相重疊，施法條可能被前面的名條擋住。",
    ["Highlight strength"] = "高亮強度",
    ["Hitbox width (%)"] = "可點擊區域寬度 (%)",
    ["Clickable plate area. 100 leaves the game's own size untouched. Stored in the profile."] = "名條的可點擊區域。100 表示不改動遊戲本身的大小。存在設定檔裡。",
    ["Hitbox height (%)"] = "可點擊區域高度 (%)",
    -- Wechsel verloren
    -- Gewehrschuss
    ["Rifle"] = "步槍槍聲",
    -- Aktionszeile
    ["Action text size"] = "操作提示文字大小",
    ["The line that names what to press. 0 follows the general text size."] = "提示該按什麼的那一行。0 表示跟隨通用文字大小。",
    -- Tempo- und Siegel-Timer-Groesse
    ["Seal timer text size"] = "印記計時文字大小",
    ["The countdown on the seal icons. 0 scales it with the icon."] = "印記圖示上的倒數。0 表示依圖示大小縮放。",
    -- Warnzeile
    ["Warning text size"] = "警告文字大小",
    ["The red and yellow warnings on the bar. 0 follows the action text size."] = "條上的紅色和黃色警告。0 表示跟隨操作提示文字大小。",
    -- Bedingungen je Eintrag
    ["Narrows this icon to a number of stacks, or to the last seconds before it runs out."] = "把這個圖示限制在某個層數，或者快要結束前的最後幾秒。",
    ["Only from stacks"] = "達到層數才顯示",
    ["0 = any number of stacks."] = "0 = 不看層數。",
    ["Only in the last seconds"] = "只在最後幾秒顯示",
    ["0 = at any time. Otherwise the icon appears only this close to running out."] = "0 = 任何時候。否則圖示只在離結束這麼近時出現。",
    -- Einheit je Gruppe
    ["Watch this unit"] = "觀察此單位",
    ["Whose auras this group reads. The default is what the group type has always used."] = "這個分組讀取誰身上的效果。預設就是該分組類型一直使用的那個。",
    ["You"] = "你自己",
    ["Target"] = "目標",
    ["Focus"] = "焦點",
    -- Nur eigene Auren
    ["Only what I cast myself"] = "只算我自己施放的",
    ["Off counts the aura no matter who put it there - for a raid debuff that anyone may apply."] = "關閉後不管是誰施加的都算 — 適合任何人都能上的團隊減益。",
    -- Sortierung
    ["Fixed keeps the order you added them in. The other two reorder live by what is left."] = "固定保持你新增時的順序。另外兩種會按剩餘時間即時重排。",
    ["As added"] = "按新增順序",
    ["Least time left first"] = "剩餘時間少的在前",
    ["Most time left first"] = "剩餘時間多的在前",
    ["Practice"] = "練習",
    ["|cffaaaaaaA swing clock that runs on its own, with no target and nothing spent. Press your bound keys against it and every swing is graded: the twist landed, it was too early, or nothing was attempted. The seal model is the real one -- a replaced seal keeps resolving for 0.4 seconds -- so the timing you learn here is the timing that works.|r"] = "|cffaaaaaa一個自行運轉的揮擊計時器，不需要目標，也不消耗任何資源。對著它按下你設定的按鍵，每一次揮擊都會被評分：twist 成功、過早出手，或是根本沒有出手。聖印的運作模型是真實的 -- 被替換掉的聖印仍會繼續生效 0.4 秒 -- 所以你在這裡練出來的時機，就是實戰中管用的時機。|r",
    ["Start / stop practice"] = "開始／停止練習",
    ["Stop practice"] = "停止練習",
    ["Simulated weapon speed"] = "模擬武器速度",
    ["0 uses whatever you have equipped. Any other value drills a speed you do not own yet, which is how you find out that the weapon you are saving for needs a different sequence."] = "設為 0 時使用你目前裝備的武器。其他數值則讓你練習一把你還沒有的武器速度，你也就能提前發現：那把你正在攢的武器需要不一樣的順序。",
    ["Spell queue window (ms)"] = "法術佇列時間 (毫秒)",
    ["A key pressed this far before the global cooldown ends is held and fires the moment it does, exactly as the client does it. Practising without it teaches a rhythm the game never asks for."] = "在公共冷卻時間結束前這段時間內按下的按鍵會被暫存，並在冷卻結束的瞬間送出，與遊戲客戶端的行為完全一致。不開啟它來練習，等於在練一種遊戲根本不會要求的節奏。",
    ["Result text size"] = "結果文字大小",
    ["Result text duration (seconds)"] = "結果文字持續時間 (秒)",
    ["Landed colour"] = "成功顏色",
    ["Missed colour"] = "失敗顏色",
    ["Show the fight timeline"] = "顯示戰鬥時間軸",
    ["Every swing and every cast on one strip against a ruler. The ruler is the point: without it you can see that two swings were close together but not how close, which is the only number practice is about."] = "把每一次揮擊與每一次施法都畫在同一條帶子上，並附上刻度尺。刻度尺才是重點：少了它，你只看得出兩次揮擊靠得很近，卻看不出到底有多近，而那正是練習唯一在乎的數字。",
    ["Timeline width"] = "時間軸寬度",
    ["Timeline pixels per second"] = "時間軸每秒像素數",
    ["TWIST"] = "twist",
    ["MISS"] = "錯過",
    ["TOO EARLY"] = "過早",
    ["speed %.2fs  -  GCD %.2fs  -  %d of %d"] = "速度 %.2f秒  -  公共冷卻 %.2f秒  -  %d / %d",
    ["|cffffffffPRACTICE|r"] = "|cffffffff練習|r",
    ["|cffffffffRESULT|r"] = "|cffffffff結果|r",
    ["|cffffffffTIMELINE|r"] = "|cffffffff時間軸|r",
    ["|cffffcc33Twist practice|r"] = "|cffffcc33twist 練習|r",
    ["Practice needs two seals: pick them under Seals first."] = "練習需要兩個聖印：請先在「聖印」中選好。",
    ["Practice mode on. Press your bound keys; the swing runs on its own."] = "練習模式已開啟。按下你設定的按鍵；揮擊會自行運轉。",
    ["Practice mode off. %d of %d swings carried the twist."] = "練習模式已關閉。%d / %d 次揮擊成功帶上了 twist。",
    ["Bloodlust"] = "嗜血",
    ["Haste potion"] = "加速藥水",
    ["Abacus"] = "算盤",
    ["Time warp"] = "時光扭曲",
    ["Crusader Strike"] = "十字軍打擊",
    ["Judgement"] = "制裁",
    ["Cast the held seal"] = "施放保留的聖印",
    ["Cast the twist seal"] = "施放 twist 的聖印",
    ["Filler"] = "填充技能",
    ["Start / stop attack"] = "開始／停止攻擊",
    ["wait"] = "等待",
    ["Next action"] = "下一個動作",
    ["|cffffffffNEXT ACTION|r"] = "|cffffffff下一個動作|r",
    ["Next action mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "下一個動作移動模式已啟用。|cff9b6cff拖曳紫色方框|r 或使用 |cff9b6cff方向鍵|r (SHIFT = 5 像素)。再次點擊「解鎖／測試」即可完成。",
    ["Next action mover disabled."] = "下一個動作移動模式已停用。",
    ["|cffaaaaaaAn icon of the one thing to press, wherever you want it. It answers the same question as the line under the bar -- the three switches below feed both, so the word and the picture can never disagree.|r"] = "|cffaaaaaa把該按的那一個動作畫成圖示，放在你想要的任何位置。它回答的問題和計時條下方那一行完全相同 -- 底下三個開關同時餵給兩者，所以文字和圖示永遠不會互相矛盾。|r",
    ["Show the next action guide"] = "顯示下一個動作提示",
    ["When to show it"] = "顯示時機",
    ["Show a hold instead of nothing"] = "以保留提示取代空白顯示",
    ["While the right move is to press nothing on purpose -- the twist is coming and anything else would cost it -- the guide keeps showing the seal, drained and outlined. An empty box says the same thing much less clearly."] = "當正確的做法是刻意什麼都不按時 -- twist 即將到來，按下其他任何東西都會毀掉它 -- 提示仍會繼續顯示該聖印，只是變暗並加上外框。空白的方框雖然表達同樣的意思，卻遠不夠清楚。",
    ["Suggest Judgement"] = "建議使用制裁",
    ["Judging consumes the seal, so it is only ever offered with room to re-seal afterwards. Off by default: a mistimed judgement costs more than no suggestion at all."] = "制裁會消耗聖印，因此只有在之後還來得及重新上印時才會提示。預設為關閉：一次時機錯誤的制裁，代價比完全沒有提示更高。",
    ["Suggest a filler"] = "建議填充技能",
    ["Consecration, or Exorcism where the target can take it, in the stretch of the swing that is free for it. Exorcism is offered by asking the client whether the spell can be aimed at your target, which is right in every language."] = "在揮擊中空出來的那段時間內，建議使用奉獻；若目標吃得下驅邪術，則建議驅邪術。是否提示驅邪術是直接詢問客戶端該法術能否指向你的目標，因此在任何語言下都正確。",
    ["Consecration mana floor (%)"] = "奉獻魔力下限 (%)",
    ["Below this share of your mana the filler is not worth it."] = "當你的魔力低於這個比例時，填充技能就不值得施放了。",
    ["Exorcism mana floor (%)"] = "驅邪術魔力下限 (%)",
    ["Longest Crusader Strike delay (ms)"] = "十字軍打擊最長延後時間 (毫秒)",
    ["Once leaving the strike any longer than this would waste it, it stops being a suggestion and becomes the answer. Measured against the earliest moment you could actually cast it, not against now."] = "一旦再拖下去就會白白浪費掉這次打擊，它就不再只是建議，而是唯一的答案。計算基準是你實際上最早能施放它的那一刻，而不是現在。",
    ["Twist!"] = "twist！",
    ["|cffffffffTWIST TEXT|r"] = "|cfffffffftwist 文字|r",
    ["Twist text mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "twist 文字移動模式已啟用。|cff9b6cff拖曳紫色方框|r 或使用 |cff9b6cff方向鍵|r (SHIFT = 5 像素)。再次點擊「解鎖／測試」即可完成。",
    ["Twist text mover disabled."] = "twist 文字移動模式已停用。",
    ["Twist landed"] = "twist 成功",
    ["|cffaaaaaaAll three cues below wait for PROOF, not for a prediction. A swing has to land with both seals up, and the held seal's own damage has to follow it in the combat log. Nothing fires without that second line -- a confirmation that is right most of the time is one you cannot practise against.|r"] = "|cffaaaaaa底下三種提示都要等到真憑實據，而不是靠預測。一次揮擊必須在兩個聖印都在身上時命中，而且保留的那個聖印自己的傷害也必須跟著出現在戰鬥紀錄裡。少了第二行紀錄就不會觸發任何提示 -- 一個只是大多數時候正確的確認，是沒辦法拿來練習的。|r",
    ["Sound channel"] = "音效頻道",
    ["Master"] = "主音量",
    ["Sound effects"] = "音效",
    ["Master ignores the sound effects slider, which is what a confirmation wants: it is feedback about the fight rather than part of it."] = "主音量不受音效滑桿影響，這正是確認提示需要的：它是關於戰鬥的回饋，而不是戰鬥的一部分。",
    ["The sniper and rifle cracks are bundled; the rest are the client's own cues. Below them stand any sounds other addons have registered as shared media."] = "狙擊與步槍的爆響是內附的；其餘都是遊戲客戶端本身的提示音。再下面則是其他插件註冊為共用媒體的音效。",
    ["Sniper"] = "狙擊",
    ["Level up"] = "升級",
    ["Quest complete"] = "任務完成",
    ["Bonus objective"] = "額外目標",
    ["Map ping"] = "地圖標記",
    ["Glow on the bar when the twist lands"] = "twist 成功時計時條發光",
    ["Glow style"] = "發光樣式",
    ["Pixel border"] = "像素邊框",
    ["Autocast ring"] = "自動施放光環",
    ["Pixel border traces the bar's own outline at any width. Autocast pins the client's own ring to the four corners, so it stays a ring however wide the bar gets."] = "像素邊框會沿著計時條本身的輪廓描邊，不論寬度為何。自動施放光環則把遊戲內建的光環固定在四個角落，因此計時條再寬它仍然是個環。",
    ["Glow colour"] = "發光顏色",
    ["Glow duration (seconds)"] = "發光持續時間 (秒)",
    ["Text when the twist lands"] = "twist 成功時顯示文字",
    ["A line somewhere on screen, with its own position. Useful where the bar is in the corner of the eye and the confirmation should be in the middle of it."] = "在螢幕上任一處顯示一行文字，並有自己的位置設定。當計時條放在眼角餘光處，而確認訊息應該出現在視線正中央時特別好用。",
    ["Text font"] = "文字字型",
    ["Text outline"] = "文字外框",
    ["Text colour"] = "文字顏色",
    ["Text duration (seconds)"] = "文字持續時間 (秒)",
    ["|cffffffffSEALS|r"] = "|cffffffff聖印|r",
    ["Seal indicator mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "聖印指示器移動模式已啟用。|cff9b6cff拖曳紫色方框|r 或使用 |cff9b6cff方向鍵|r (SHIFT = 5 像素)。再次點擊「解鎖／測試」即可完成。",
    ["Seal indicator mover disabled."] = "聖印指示器移動模式已停用。",
    ["Match the bar height"] = "配合計時條高度",
    ["Sizes the icons to the bar instead of to their own setting, so the pair keeps lining up with it when the bar height changes."] = "讓圖示依照計時條而非自己的設定調整大小，如此一來計時條高度改變時，這一對圖示仍會與它對齊。",
    ["Ignored while the icons match the bar height."] = "當圖示配合計時條高度時，此設定會被忽略。",
    ["Seal icon spacing"] = "聖印圖示間距",
    ["Centre the icons"] = "置中圖示",
    ["Keeps the midpoint of the pair still when the second seal appears or falls off. Left-aligned keeps the first icon still instead, which is what an attached pair wants -- that edge is the bar."] = "當第二個聖印出現或消失時，讓這一對圖示的中點保持不動。靠左對齊則是讓第一個圖示保持不動，這才是附著在計時條上的圖示需要的 -- 因為那條邊就是計時條。",
    ["Show the cooldown sweep"] = "顯示冷卻掃描",
    ["The client's own sweep across the icon. It says the same thing as the number under it, but it says it without being read."] = "遊戲內建、覆蓋在圖示上的冷卻掃描。它傳達的訊息和下方的數字相同，只是不必你去讀它。",
    ["Seal timer colour"] = "聖印計時顏色",
    ["Detach from the bar"] = "從計時條分離",
    ["Gives the pair its own position anywhere on screen. They stay tied to the bar in every other way: when it is hidden, they are too."] = "讓這一對圖示能自由擺放在螢幕上的任何位置。其餘方面它們仍與計時條連動：計時條隱藏時，它們也會跟著隱藏。",
    ["Twist lost"] = "twist 失敗",
    ["Swing ready -- restart your attack"] = "揮擊已就緒 -- 請重新開始攻擊",
    ["(none available)"] = "(無可用項目)",
    ["Solid"] = "純色",
    ["Attack speed"] = "攻擊速度",
    ["Swing timer"] = "揮擊計時",
    ["Latency (ms)"] = "延遲 (毫秒)",
    ["Global cooldown left"] = "公共冷卻剩餘時間",
    ["Nothing"] = "不顯示",
    ["Left readout"] = "左側讀數",
    ["What the left end of the bar shows. Attack speed turns into the warning colour below two global cooldowns per swing -- under that the twist and the seal going back up no longer both fit, so wait for the cooldown before twisting."] = "決定計時條左端顯示的內容。當每次揮擊已經容不下兩個公共冷卻時間時，攻擊速度會轉為警告顏色 -- 低於這個門檻，twist 和重新上印就無法同時塞進一次揮擊，因此請先等公共冷卻結束再 twist。",
    ["Right readout"] = "右側讀數",
    ["Readout text size"] = "讀數文字大小",
    ["The two numbers inside the bar. 0 follows the general text size."] = "計時條內的兩個數字。設為 0 時沿用一般文字大小。",
    ["Global cooldown bar texture"] = "公共冷卻條材質",
    ["Border"] = "邊框",
    ["Solid draws four flat edges in the colour below. Texture takes an edge file from shared media, which is what a border from another interface pack looks like."] = "純色會以下方的顏色畫出四條平整的邊。材質則從共用媒體取用邊框檔案，那正是其他介面套件的邊框樣貌。",
    ["Only used while the border is set to texture."] = "只有在邊框設為材質時才會使用。",
    ["Border width"] = "邊框寬度",
    ["Marker texture"] = "標記材質",
    ["Marker width"] = "標記寬度",
    ["Font colour"] = "字型顏色",
    ["Frame strata"] = "框架層級",
    ["Which layer of the interface the helper sits in. Raise it to lift the bar over another addon that draws in the same place."] = "決定這個輔助介面位於介面的哪一層。若有其他插件畫在同一個位置，可以調高它，把計時條蓋上去。",
    ["Draw level"] = "繪製層次",
    ["The order inside the chosen layer. Higher draws on top."] = "在所選層級內的排序。數值越高畫得越上層。",
    ["Colour the bar by"] = "計時條配色依據",
    ["The zone the swing is in"] = "揮擊所處的區段",
    ["The seal you are carrying"] = "你身上帶著的聖印",
    ["Zones colour the fill by the stretch of the swing you are in, which is what this helper is built around. Seal colours it by what you are carrying, which is the faster read once the timing is in your fingers. Either way the special colours below outrank the choice."] = "區段會依你目前處在揮擊的哪一段來填色，這也是整個輔助介面的設計核心。聖印則依你身上帶著的聖印上色，一旦時機已經練進手感，這種讀法更快。無論選哪一種，下方的特殊顏色都會優先套用。",
    ["Seal of Command"] = "命令聖印",
    ["Seal of Righteousness"] = "正義聖印",
    ["Seal of Blood / the Martyr"] = "血之聖印／殉道者聖印",
    ["Seal of Vengeance"] = "復仇聖印",
    ["Seal of the Crusader"] = "十字軍聖印",
    ["Seal of Justice"] = "公理聖印",
    ["Seal of Light"] = "光明聖印",
    ["Seal of Wisdom"] = "智慧聖印",
    ["No twist possible"] = "無法 twist",
    ["The fill while this swing's twist is already gone, and the tail of the swing a cast can no longer reach."] = "當這一次揮擊的 twist 機會已經錯過時的填色，以及揮擊末端施法再也趕不上的那一段。",
    ["Warning"] = "警告",
    ["The warnings on the bar, and the attack speed once the weapon is too fast to twist with."] = "計時條上的警告訊息，以及武器快到無法 twist 時的攻擊速度。",
    ["Twisting"] = "twist 中",
    ["The fill while both seals are up: the twist is in and this swing carries it."] = "兩個聖印都在身上時的填色：twist 已經完成，這一次揮擊會帶上它。",
    ["Default"] = "預設",
    ["The fill with no seal up and between swings."] = "身上沒有聖印，以及兩次揮擊之間的填色。",
    ["Global cooldown"] = "公共冷卻時間",
    ["Deadzone"] = "盲區",
    ["Twist window padding"] = "twist 時間窗補償",
    ["Pulls the twist window earlier so the cast still reaches the server inside it. Dynamic follows your calibrated latency; fixed is a number you choose yourself."] = "把 twist 時間窗往前挪，讓施法仍能在窗內送達伺服器。動態會跟隨你校準後的延遲；固定則由你自己指定一個數值。",
    ["Fixed twist padding (ms)"] = "固定 twist 補償 (毫秒)",
    ["Only used while the padding mode is set to fixed."] = "只有在補償模式設為固定時才會使用。",
    ["Dynamic (follows latency)"] = "動態 (跟隨延遲)",
    ["Fixed"] = "固定",
    ["Latency"] = "延遲",
    ["|cffaaaaaaThe round trip your client reports is not the delay a twist has to beat: the client adds a slice of its own, so the figure everything below works from is (world latency x multiplier) + offset. Raise the multiplier if you keep missing twists that looked in time.|r"] = "|cffaaaaaa客戶端回報的來回延遲，並不等於 twist 必須克服的延遲：客戶端自己還會再加上一段，因此底下所有設定實際採用的數值是（世界延遲 x 倍率）＋ 偏移。如果你老是錯過那些看起來明明來得及的 twist，就把倍率調高。|r",
    ["Latency multiplier"] = "延遲倍率",
    ["Latency offset (ms)"] = "延遲偏移 (毫秒)",
    ["Shade the deadzone"] = "標示盲區陰影",
    ["The tail of the swing a cast can no longer cross, shaded at the end of the bar. Its size follows your raw world latency rather than the calibrated figure, because this one is the wire and not a prediction. This switch only draws it -- the timing itself always accounts for it, so set the scale to 0 if you want no compensation at all."] = "揮擊末端施法再也跨不過去的那一段，會在計時條尾端加上陰影。它的大小跟隨你原始的世界延遲，而不是校準後的數值，因為這一段是線路本身而不是預測。這個開關只負責畫出它 -- 時機計算永遠都會把它算進去，所以如果你完全不想要補償，請把比例設為 0。",
    ["Deadzone scale"] = "盲區比例",
    ["Multiplies your world latency. Raise it if you cannot twist just outside the shaded stretch, lower it if you still can inside it. 0 switches the compensation off entirely."] = "用來乘上你的世界延遲。如果你在陰影區外側就已經換不了印，請調高；如果在陰影區內側還換得了印，請調低。設為 0 會完全關閉補償。",
    ["Deadzone texture"] = "盲區材質",
    ["Deadzone transparency"] = "盲區透明度",
    ["Global cooldown padding"] = "公共冷卻補償",
    ["Pulls the global cooldown boundary earlier by part of your latency, so a cast started right at the mark still clears the cooldown in time."] = "依你延遲的一部分把公共冷卻的界線往前挪，讓剛好卡在標記上施放的法術仍能及時通過冷卻。",
    ["Fixed global cooldown padding (ms)"] = "固定公共冷卻補償 (毫秒)",
    ["Show the judgement mark"] = "顯示制裁標記",
    ["A fourth line where Judgement comes off cooldown during this swing, so a judgement can be put in front of the twist instead of on top of it. Only drawn while a seal is up."] = "在這一次揮擊中制裁冷卻結束的位置畫上第四條線，讓你能把制裁排在 twist 之前，而不是壓在 twist 上面。只有在身上有聖印時才會繪製。",
    ["Show the global cooldown bar"] = "顯示公共冷卻條",
    ["A strip along the bottom of the bar reaching to the moment the global cooldown frees up, so you can see how much of this swing is already spoken for."] = "沿著計時條底部延伸到公共冷卻結束時刻的一條細帶，讓你看得出這一次揮擊已經有多少時間被佔走。",
    ["Global cooldown bar height"] = "公共冷卻條高度",
    ["When to show the bar"] = "計時條顯示時機",
    ["Always keeps it on screen, which is the easier way to practise the timing on a dummy. Seal active shows it whenever you are carrying a seal, in or out of a fight."] = "總是顯示會讓它一直留在螢幕上，這是在木樁上練時機比較輕鬆的方式。聖印生效中則是只要你身上帶著聖印就顯示，不論是否在戰鬥中。",
    ["Seal active"] = "聖印生效中",
    ["In combat or seal active"] = "戰鬥中或聖印生效中",
    ["Only with Two-Handed Weapon Specialization"] = "僅在擁有雙手武器專精時",
    ["Hides the helper unless you have a point in the talent. Twisting works without it, but the slow swing it is built around is what makes the whole habit pay."] = "除非你在該天賦上點了點數，否則隱藏這個輔助介面。沒有它也能 twist，但整套習慣真正划算的前提，正是它所倚賴的慢速揮擊。",
    ["Neck"] = "頸部",
    ["Shoulder"] = "肩部",
    ["Waist"] = "腰部",
    ["Legs"] = "腿部",
    ["Wrist"] = "手腕",
    ["Hands"] = "手部",
    ["Finger 2"] = "手指 2",
    ["Trinket 2"] = "飾品 2",
    ["Off Hand"] = "副手",
    ["Ranged"] = "遠程",
    -- Patch notes 1.42.0
    ["Practice – A swing clock that runs on its own, with your own keys and a verdict on every swing"] = "練習 – 自行運轉的揮擊計時器，使用你自己的按鍵，每次揮擊都有判定",
    ["Next action – An icon of the one thing to press, wherever you put it"] = "下一個動作 – 把此刻唯一該按的東西做成圖示，放在你想要的位置",
    ["Latency – Calibrate the delay a twist has to beat, with its own multiplier and offset"] = "延遲 – 用自己的倍數與偏移校準 twist 必須贏過的那段延遲",
    ["Shade the deadzone – The tail of the swing a cast can no longer cross"] = "標示盲區陰影 – 施法再也無法跨越的揮擊末端",
    ["Show the global cooldown bar – A strip reaching to the moment the cooldown frees up"] = "顯示公共冷卻條 – 一條延伸到冷卻結束那一刻的細條",
    ["When to show the bar – Always, in combat, while a seal is up, or either"] = "計時條顯示時機 – 永遠、戰鬥中、身上有聖印時，或兩者之一",
    ["Colour the bar by – The zone the swing is in, or the seal you are carrying"] = "計時條配色依據 – 揮擊所在的區段，或你身上的聖印",
    ["Detach from the bar – The seal icons take their own position, with a cooldown sweep"] = "從計時條分離 – 聖印圖示取得自己的位置，並帶冷卻掃描",
    ["Suggest Judgement – Offered only with room to re-seal afterwards, and off until you ask"] = "建議使用制裁 – 只在之後還有空間重新上印時建議，且預設關閉",
    ["Textures, border, font, frame layer, marker width and the two readouts inside the bar are yours to set, and every seal has its own colour."] = "材質、邊框、字體、框架層級、標記寬度，以及計時條內的兩處顯示都由你決定，每個聖印也各有自己的顏色。",
    -- Patch notes 1.42.0
    ["The twist is now called twist in every language, the word paladins use themselves. German called it Siegelwechsel; the helper and its window are named after the twist instead."] = "這個技巧現在在所有語言中都叫 twist，這正是聖騎士自己的說法。德文原本叫 Siegelwechsel，現在輔助工具與它的視窗都以 twist 命名。",
    ["The cue for a landed twist no longer guesses. It used to fire the moment a seal went out inside the window, which is a prediction the server can disagree with. Now the combat log has to show a swing landing with both seals up and the held seal's own damage behind it. Without that, nothing sounds."] = "成功 twist 的提示不再靠猜。以前只要聖印在時間窗內送出就會響，那是一個伺服器可能不同意的預測。現在戰鬥記錄必須顯示一次帶著兩個聖印命中的揮擊，緊接著還要有所維持聖印本身的傷害。少了這一條，就什麼都不會響。",
    -- Patch notes 1.42.0
    ["Switching the module off used to leave the bag bar, the latency bar and Action Bar 1's twelve buttons behind until a /reload. All three come back on their own now."] = "關閉這個模組後，背包條、延遲條以及動作條 1 的十二個按鈕都會一直留在原樣，直到 /reload。現在這三者都會自己回來。",
    ["Rows that span the page now start their control where their neighbours do, instead of each sizing its own label."] = "佔滿整行的設定項，其控制項現在與相鄰各行從同一位置開始，而不再各自量自己的標籤寬度。",
    -- Patch notes 1.42.0
    ["Watch this unit – A group can follow your target, your focus or your pet instead of you"] = "觀察此單位 – 一個分組可以跟隨你的目標、專注目標或寵物，而不是跟隨你自己",
    ["Only what I cast myself – A group can require the aura to be your own, not anyone's"] = "只算我自己施放的 – 一個分組可以要求這個光環必須是你自己上的，而不是隨便誰的",
    ["Order – Sort a group by the time left instead of the order you added things in"] = "順序 – 依剩餘時間排序一個分組，而不是依你加入它們的先後",
    ["Conditions belong to the individual entry now, not only to the kind of group it sits in. One entry can ask for a stack count or for the last few seconds while its neighbours ask for nothing."] = "條件現在屬於單一項目，而不再只屬於分組的類型。一個項目可以要求層數或最後幾秒，而它旁邊的項目什麼都不要求。",
    ["Cast bars in front of other plates – So the cast you are watching is not hidden behind the plate beside it"] = "施法條顯示在其他名條之前 – 讓你正在看的那條施法不會被旁邊的名條擋住",
    ["Darken enemies out of combat – With its own strength, so an idle mob reads as idle at a glance"] = "戰鬥外的敵人變暗 – 有自己的強度，讓閒著的敵人一眼看上去就是閒著的",
    ["Highlight strength – How far the plate under your cursor lifts out of the row"] = "高亮強度 – 游標下的名條從這一排裡凸出多少",
    ["The clickable area is measured from the plate now instead of assumed, so the width and height settings land where your cursor really is."] = "可點擊區域現在是從名條上量出來的，不再靠假設，所以寬高設定會落在你游標真正所在的位置。",
    ["A dropdown with more entries than fit on screen scrolls instead of running off the bottom, and a label that had grown too long fits its row again."] = "項目多到裝不進畫面的下拉選單現在會捲動，而不是從下方溢出，過長的標籤也重新裝回它自己那一行。",
    -- Patch notes 1.43.0
    ["Compatibility"] = "相容性",
    ["The character window stayed empty on clients we had never named. The panel asked whether the client called itself one of two specific versions and refused every other one, including clients that have exactly the frames it needs. It now asks for the one thing it cannot work without. Enchants, sockets and item stats were missing for the same reason and return with it."] = "在我們從未點名的客戶端上，角色視窗是空的。這塊面板只問客戶端是否自稱那兩個特定版本之一，其餘一律拒絕，連那些恰好具備它所需框體的客戶端也不例外。現在它只問那一樣缺了就無法運作的東西。附魔、插槽與物品屬性缺失也是同一個原因，現在一併回來了。",
    ["Hit rating, haste rating and spell hit rating appear on Wrath-based clients too. They were tied to a single version by name, although the game there has those stats."] = "命中等級、加速等級與法術命中等級在以巫妖王之怒為基礎的客戶端上也會顯示。它們先前按名字綁死在唯一一個版本上，可是那邊的遊戲確實有這些屬性。",
    ["The stat rows Wrath draws in pages with two dropdowns are hidden underneath our own panel now, instead of showing through it."] = "巫妖王之怒用兩個下拉選單分頁繪製的屬性列，現在被藏在我們自己的面板底下，不再從中透出來。",
    ["Titan Reforged – The addon no longer reports itself out of date on the Chinese client, whose build is listed now"] = "Titan Reforged – 插件在中國客戶端上不再自稱過期，它的版本號現在也列在裡面了",
    ["Version detection falls back to the build number whenever a client reports an identifier we have no name for. Such a client used to end up with every version flag false, which left it worse off than a client with no identifier at all, because that one at least fell back to something."] = "只要客戶端回報一個我們叫不出名字的識別碼，版本辨識就退回去看版本號。以前這樣的客戶端會讓所有版本標記都為假，反而比完全沒有識別碼的客戶端更糟，因為後者至少還能退回到某個預設值。",
    ["242 texts that nothing in the interface looks up any more are gone from all nine language files, roughly eight percent of each. Renamed settings left them behind: the action bars were given clearer names a while ago and the old entries simply stayed. A check now asks the reverse question after every change, whether every translated text is still in use, so they cannot pile up again."] = "介面裡再也沒有任何地方會去查的 242 條文字，已經從九個語言檔中全部移除，各占約百分之八。它們是被改名的設定留下的：動作列前一陣換了更清楚的名字，舊項目就那麼留著。現在每次改動之後都會有一項檢查反過來問，每條翻譯好的文字是否還在被使用，這樣它們就不會再堆積起來。",
    ["Call button – A fifth totem button for the spells that summon a whole saved totem set, shown only to characters who know one"] = "召喚按鈕 – 第五個圖騰按鈕，用於那些一次召喚整套已儲存圖騰的法術，只對會這類法術的角色顯示",
    ["Icon Strip"] = "圖示列",
    ["Distance from frame"] = "與框架的距離",
    ["Spacing between icons"] = "圖示間距",
    ["Racial, PvP trinket and the DR row sit on the same edge of the frame and are placed one after the other, in that order, outwards from the frame."] = "種族技能、PvP 飾品與遞減圖示列位於框架的同一側，並依此順序逐一向外排列。",
    ["Where it sits is set once for all three trackers under Layout, Icon Strip."] = "位置在「版面—圖示列」中一次為三個追蹤器統一設定。",
    ["Gap below each frame. The opponent's pet bar hangs off the bottom of the frame, so a small gap lets it reach into the next one."] = "每個框架下方的間距。對手的寵物條會超出框架底部，間距過小時會壓到下一個框架。",
    ["Arena: racial, PvP trinket and the DR row now share one icon strip; your chosen side was kept."] = "競技場：種族技能、PvP 飾品與遞減圖示列現在共用一條圖示列；你選擇的一側已保留。",
    ["|cffff5555Arena layout failed:|r %s"] = "|cffff5555競技場版面失敗：|r %s",
    ["|cffff5555Arena icon strip error:|r %s"] = "|cffff5555競技場圖示列錯誤：|r %s",
    ["Nothing in this bar yet. Add a spell or trinket below, or drag one onto the bar."] = "這條列上還沒有任何內容。在下方加入法術或飾品，或將其拖到列上。",
    ["+  New cooldown bar"] = "+  新增冷卻列",
    ["+  New buff / proc bar"] = "+  新增增益／觸發列",
    ["+  New target debuff bar"] = "+  新增目標減益列",
    ["+  New missing-buff reminder"] = "+  新增增益缺失提醒",
    ["Buffs & Procs"] = "增益與觸發",
    ["Target debuffs"] = "目標減益",
    ["Missing buffs"] = "缺少的增益",
    ["New name for this bar"] = "這條列的新名稱",
    ["Delete this bar and everything on it?"] = "刪除這條列及其上的全部內容？",
    ["That is the last bar — there has to be one."] = "這是最後一條列——必須保留一條。",
    ["Drag to reorder bars"] = "拖曳可重新排序各列",
    ["Rename this bar"] = "重新命名這條列",
    ["Delete this bar"] = "刪除這條列",
    ["Duplicate bar"] = "複製這條列",
    ["Copies the selected bar with all entries and layout settings."] = "複製所選列，連同全部項目與版面設定。",
    ["Bar layout"] = "列版面",
    ["Icon appearance"] = "圖示外觀",
    ["Icon display"] = "圖示顯示",
    ["Movable cooldown bars grouped however you like — procs, defensives, offensives, each with its own look and position."] = "可自由分組的可移動冷卻條——觸發效果、防禦、攻擊，每條都有自己的外觀與位置。",
    ["Which IDs should be shown in tooltips? Some types do not exist on this game version and are ignored (e.g. TraitNodeID, SourceID)."] = "提示資訊中應顯示哪些 ID？部分類型在此遊戲版本中不存在，會被忽略（例如 TraitNodeID、SourceID）。",
    ["CDM Bars"] = "CDM 列",
    ["Bug Fixes"] = "錯誤修正",
    ["Bar Glows"] = "列位光效",
    ["Click to edit this icon's glow."] = "點擊以編輯此圖示的光效。",
    ["Click an icon to edit its glow."] = "點擊圖示以編輯其光效。",
    ["Nothing in this bar yet. Add a spell or trinket on the CDM Bars tab first."] = "這條列上還沒有任何內容。請先在「CDM 列」分頁加入法術或飾品。",
    ["|cffaaaaaaEach icon can glow while a buff of yours is active — or missing. Click an icon in the preview above, then add one or more watchers; the first whose condition holds paints the icon.|r"] = "|cffaaaaaa每個圖示都可以在你的某個增益生效——或缺失時發光。點擊上方預覽中的圖示，然後加入一個或多個監視器；第一個條件成立的監視器為圖示上色。|r",
    ["|cff888888No icon picked yet.|r"] = "|cff888888尚未選擇圖示。|r",
    ["Glows: %s"] = "光效：%s",
    ["Glow when"] = "發光條件",
    ["Buff is active"] = "增益生效時",
    ["Buff is missing"] = "增益缺失時",
    ["Action button glow"] = "快捷列按鈕光效",
    ["Pulsing fill"] = "脈動填充",
    ["Gold (default)"] = "金色（預設）",
    ["Pick color..."] = "選擇顏色…",
    ["Remove this glow"] = "移除此光效",
    ["Watches: %s"] = "監視：%s",
    ["Add watcher (buff name / ID)"] = "加入監視器（法術名稱／ID）",
    ["|cffaaaaaaNo watcher yet. Most spells put a buff of the same name on you when used — one click below makes this icon glow while that buff is on you. Or type any other buff into the field.|r"] = "|cffaaaaaa尚無監視器。大多數法術施放時會給你一個同名增益——點擊下方按鈕，此圖示將在該增益存在期間發光。也可以在輸入欄中填寫任意其他增益。|r",
    ["Glow while '%s' is on me"] = "當「%s」在我身上時發光",
    -- Patch notes 1.44.0
    ["Icon Strip – Racial, trinket and the diminishing-returns row share one edge of the frame in a fixed order, with one set of controls — they can no longer land on top of each other"] = "圖示列 – 種族技能、飾品和遞減圖示列按固定順序共用框架的一側，只需一組設定——它們不會再互相疊在一起",
    ["The frame layout — order, spacing, grow direction — never actually applied: its hooks were installed before the arena interface had loaded. The frames now report their own moves and the layout follows; during a fight they are protected, so a move mid-round is corrected when it ends."] = "競技場框架的版面——順序、間距、延伸方向——從未真正生效：它的掛鉤在競技場介面載入之前就已安裝。現在框架會自行回報移動，版面隨之跟進；戰鬥中它們受保護，回合中途的移動會在結束時修正。",
    ["The default gap between frames clears the opponent's pet bar, and the drag box in edit mode covers the whole stack instead of a fixed area."] = "框架之間的預設間距為對手的寵物條留出了位置，編輯模式的拖曳框覆蓋整疊框架，而不是一塊固定區域。",
    ["Bar Glows – Any icon can glow while a buff of yours is active or missing: three styles, gold, class or custom color, and one click watches the spell's own buff"] = "列位光效 – 任何圖示都可以在你的某個增益生效或缺失期間發光：三種樣式，金色、職業色或自訂顏色，一鍵即可監視法術自身的增益",
    ["The page is built around a preview that stays put while you scroll: the bar picker with rename, delete and drag-to-reorder on top, under it every icon of the bar at its real size and shape with the real cooldown sweep. Drag reorders, right-click removes."] = "頁面圍繞一個捲動時保持不動的預覽建構：上方是可重新命名、刪除、拖曳排序的列選擇器，下方是該列的每個圖示，以真實大小、形狀和真實的冷卻掃過效果顯示。拖曳排序，右鍵移除。",
    ["The page is split into tabs, and the resource bar moved in as one of them. Spells you add belong to the class that added them and no longer show up on your other characters."] = "頁面拆分為分頁，資源條作為其中之一搬了進來。你加入的法術屬於加入它的職業，不再出現在你的其他角色上。",
    ["The third extra-item slot no longer stretches across the page with its box flung to the far edge."] = "第三個額外物品欄位不再橫跨整個頁面、把輸入欄甩到最邊上。",
    ["The interface no longer compares itself with the other game version anywhere; a check keeps such wording out for good."] = "介面不再在任何地方與另一遊戲版本作比較；一項檢查會永久擋住這類措辭。",
    ["Modules with several pages show them as a tab row along the top; when the tabs outgrow the row, two arrows page through it instead of wrapping into a second line."] = "有多個頁面的模組將它們顯示為頂部的一列分頁；分頁超出一列時，兩個箭頭翻頁瀏覽，而不是折成第二列。",
    ["The sidebar got shorter: player and target frames, font bars, castbar and cooldown pulse are one entry now, and a new General entry under Reminders collects the former Extras, Character and Bug Fixes rows — the bug fixes as a single tab."] = "側邊欄變短了：玩家與目標框架、字型條、施法條和冷卻脈衝現在是一個條目，提醒下方新的「一般」條目收納了原來的雜項、角色和錯誤修正各列——錯誤修正只佔一個分頁。",
    ["Typing into an add field and then clicking the button beside it silently did nothing; the typed text only counted after pressing Enter. Buttons now take the field's text with them."] = "在加入輸入欄裡打字後點擊旁邊的按鈕曾悄無聲息地毫無作用；輸入的文字只有按 Enter 才算數。現在按鈕會帶上輸入欄的文字。",
    ["Developer"] = "開發者",
    ["Suppress Lua Errors"] = "隱藏 Lua 錯誤",
    ["Hides the game's own Lua error popup (CVar scriptErrors). Errors still happen and error-collecting addons still see them - they just stop interrupting you."] = "隱藏遊戲內建的 Lua 錯誤視窗（CVar scriptErrors）。錯誤仍會發生，收集錯誤的插件也仍能看到——只是不再打擾你。",
    ["Show IDs in Tooltips"] = "在提示資訊中顯示 ID",
    ["Shows spell, item, NPC and other IDs in tooltips. Which ID types appear can be fine-tuned on the Tooltip IDs page in the Extras group."] = "在提示資訊中顯示法術、物品、NPC 等 ID。顯示哪些 ID 類型可在雜項群組的提示資訊 ID 頁面中調整。",
    ["Reset All Settings"] = "重置所有設定",
    ["Optimize My FPS and Graphics"] = "最佳化我的 FPS 與畫質",
    ["Applies a proven set of graphics settings that noticeably raises FPS while keeping the game looking good - shadows, liquids, ambient occlusion and view distance go down, textures and spell effects stay sharp. Your current values are saved first and the restore button brings them back. Only settings this client knows are touched."] = "套用一組經過驗證的畫質設定，在保持畫面觀感的同時明顯提升 FPS——陰影、液體、環境光遮蔽與可視距離調低，材質與法術效果保持清晰。目前的值會先被儲存，還原按鈕可隨時找回。只會更動此客戶端認識的設定。",
    ["Restore My Graphics Settings"] = "還原我的畫質設定",
    ["Returns every graphics setting the optimize button changed to its previous value and removes the backup."] = "將最佳化按鈕更動過的每項畫質設定還原為先前的值，並刪除備份。",
    ["Graphics optimized: %d settings applied."] = "畫質已最佳化：套用了 %d 項設定。",
    ["Graphics settings restored."] = "畫質設定已還原。",
    ["Fonts & Colors"] = "字型與顏色",
    ["Global Font"] = "全域字型",
    ["The font for the whole VuloClassicUI interface. Fonts shared by other addons appear here too.\n\n|cffaaaaaaRequires /reload to apply everywhere.|r"] = "整個 VuloClassicUI 介面的字型。其他插件共享的字型也會出現在這裡。\n\n|cffaaaaaa需要 /reload 才能在所有位置生效。|r",
    ["Outline Mode"] = "描邊模式",
    ["Default outline for VuloClassicUI text. Elements with their own outline setting keep it.\n\n|cffaaaaaaRequires /reload to apply everywhere.|r"] = "VuloClassicUI 文字的預設描邊。帶有自己描邊設定的元素保持不變。\n\n|cffaaaaaa需要 /reload 才能在所有位置生效。|r",
    ["Apply to All Game Texts"] = "套用到所有遊戲文字",
    ["Replaces the font of the game's own texts (chat, tooltips, quest log and more) with the global font.\n\n|cffaaaaaaTurning it off requires /reload to restore the original fonts.|r"] = "用全域字型取代遊戲本身文字（聊天、提示資訊、任務日誌等）的字型。\n\n|cffaaaaaa關閉時需要 /reload 才能還原原始字型。|r",
    ["Class Colors"] = "職業顏色",
    ["Resource Colors"] = "資源顏色",
    ["Font changed. /reload required to apply it everywhere."] = "字型已變更。需要 /reload 才能在所有位置生效。",
    ["Reset to default"] = "重設為預設值",
    ["Rename..."] = "重新命名...",
    ["Rename loadout '%s'. Enter new name:"] = "重新命名裝備配置「%s」。輸入新名稱：",
    ["A loadout named '%s' already exists."] = "已存在名為「%s」的裝備配置。",
    ["Loadout '%s' renamed to '%s'."] = "裝備配置「%s」已重新命名為「%s」。",
    -- Patch notes 1.45.0
    ["The item level on equipment links sits after the link now, not inside its brackets. Some clients re-check link text against their own data, and the changed text turned the link into the name of whatever quest carried that number."] = "裝備連結上的物品等級現在跟在連結後面，而不在方括號內。部分客戶端會用自己的資料重新核對連結文字，改動過的文字曾把連結變成對應編號任務的名字。",
    ["A spell no longer shows up on another class just because that class owns a different spell with the same name. Entries respect their class stamp on the bars, and old entries are adopted by spell ID instead of by name."] = "法術不再只因另一個職業擁有同名的不同法術就出現在那個職業上。項目在條列上遵循自己的職業標記，舊項目改按法術 ID 歸屬，而不是按名字。",
    ["The bundled media library silently dropped font registrations when no other addon shipped a newer copy of it; the addon font now registers on every install."] = "內建的媒體庫在沒有其他插件提供較新副本時會悄悄捨棄字型註冊；現在插件字型在任何安裝下都會註冊。",
    ["Rename... – In the set's right-click menu and on the sets page; icon, contents and talent binding move along with the name"] = "重新命名... – 在配置的右鍵選單和配置頁面中；圖示、內容和天賦綁定隨名字一起搬移",
    ["Optimize My FPS and Graphics – A proven set of graphics settings with a one-time backup; the restore button next to it brings your old values back"] = "最佳化我的 FPS 與畫質 – 一套經過驗證的畫質設定，附一次性備份；旁邊的還原按鈕可找回舊值",
    ["Fonts & Colors – A new tab: global font with outline mode, optionally for all game texts, plus class and resource colors with a reset on every row"] = "字型與顏色 – 新分頁：帶描邊模式的全域字型（可選套用到所有遊戲文字），以及每列帶重設的職業與資源顏色",
    ["Developer – Suppress Lua errors, switch tooltip IDs and reset all settings from a new section on the General tab"] = "開發者 – 在一般分頁的新區域裡隱藏 Lua 錯誤、切換提示資訊 ID、重設所有設定",
    ["The General tab is organised in sections on a two-column grid like the rest of the window. The new tab ships a texture file: restart the client once after updating, a /reload alone will not show the reset arrows."] = "一般分頁像視窗其餘部分一樣按兩欄網格分區。新分頁帶來一個材質檔案：更新後請完整重新啟動一次客戶端，僅 /reload 不會顯示重設箭頭。",
    ["The enlargement stays off on Wrath-based clients (Titan Reforged): their quest log is already the wide two-pane frame, and enlarging it pushed the detail pane into the button row."] = "在基於巫妖王之怒的客戶端（Titan Reforged）上放大保持關閉：那裡的任務日誌本就是寬雙欄視窗，放大會把詳情欄擠進按鈕列。",
    ["Long dropdown lists open upwards when there is no room below. They used to run off the bottom edge of the screen, where the last entries could never be scrolled into view."] = "長下拉選單在下方沒有空間時向上開啟。以前它們會伸出畫面下緣，最後幾項永遠捲不進視野。",
    ["On"] = "開啟",
    ["Select all"] = "全選",
    ["Deselect all"] = "全不選",
    ["Interface layout (window positions and links)"] = "介面佈局（視窗位置與關聯）",
    ["Fonts & colors (account-wide)"] = "字型與顏色（整個帳號）",
    ["Also carries your account-wide font and color settings; they apply immediately when the string is imported."] = "同時攜帶你整個帳號的字型與顏色設定；匯入字串時立即生效。",
    ["|cffaaaaaaThe export will include %d of %d modules.|r"] = "|cffaaaaaa匯出將包含 %d/%d 個模組。|r",
    ["Nothing selected to export."] = "沒有選擇要匯出的內容。",
    ["|cffaaaaaaUntick modules to share only a part - a partial string merges onto the importer's active profile.|r"] = "|cffaaaaaa取消勾選模組可只分享一部分——部分字串會合併到匯入者的目前設定檔中。|r",
    ["Standard Action Bars"] = "標準快捷列",
    ["Modern"] = "現代",
    ["|cffaaaaaaThe game's own action bars stay in place. Frame style and Dark Mode below come from the Dark Skin module and style Blizzard's buttons directly.|r"] = "|cffaaaaaa遊戲內建的快捷列保持原樣。下方的邊框樣式與暗色模式來自 Dark Skin 模組，直接作用於暴雪的按鈕。|r",
    ["Apply layout to all bars"] = "將佈局套用到所有快捷列",
    ["Copies this bar's layout - scale, icon size, buttons per row, spacing, direction - to every other bar."] = "把此快捷列的佈局——縮放、圖示大小、每列按鈕數、間距、方向——複製到其他所有快捷列。",
    ["Layout applied to all bars."] = "佈局已套用到所有快捷列。",
    ["Text sizes"] = "文字大小",
    ["Bar Display"] = "快捷列顯示",
    ["Menu, Bags & XP Bar"] = "選單、背包與經驗條",
    ["|cffaaaaaaOnly active in Modern mode (Bar Display tab).|r"] = "|cffaaaaaa僅在現代模式下生效（快捷列顯示分頁）。|r",
    ["Click: layout settings. Right-click: text sizes."] = "點擊：佈局設定。右鍵：文字大小。",
    ["Bar Animations"] = "快捷列動畫",
    ["Tint the pressed state"] = "為按下狀態上色",
    ["Colours the flash a button shows while it is pressed down."] = "為按鈕按下時顯示的閃光上色。",
    ["Tint the hover highlight"] = "為懸停高亮上色",
    ["Colours the glow a button shows under the mouse."] = "為滑鼠懸停時按鈕顯示的光暈上色。",
    ["Use class colour"] = "使用職業顏色",
    ["Enable bar background"] = "啟用快捷列背景",
    ["A flat colour panel behind the bar, sized with it."] = "快捷列後面的純色面板，隨其調整大小。",
    ["Padding"] = "邊距",
    ["Flat (default)"] = "純色（預設）",
    ["Core"] = "基本",
    ["Opacity"] = "不透明度",
    ["Durability"] = "耐久度",
    ["Talent points"] = "天賦點數",
    ["Pulse"] = "脈動",
    ["Steady"] = "恆亮",
    ["Background"] = "背景",
    ["Low"] = "低",
    ["Medium"] = "中",
    ["High"] = "高",
    ["Dialog"] = "對話框",
    ["Click an icon to jump to its settings."] = "點擊圖示跳轉到對應設定。",
    ["Middle-click: hide until the next loading screen."] = "中鍵點擊：隱藏至下一次載入畫面。",
    ["Nothing to preview: every reminder is switched off."] = "沒有可預覽的內容：所有提醒均已關閉。",
    ["Show effects missing on others"] = "顯示其他人缺少的效果",
    ["Scans your party or raid for class buffs you could cast and reminds you when someone lacks one."] = "檢查隊伍或團隊中你可施放的職業增益，當有人缺少時提醒你。",
    ["Missing on %s: %s"] = "%s缺少：%s",
    ["In raids (minutes)"] = "團隊中（分鐘）",
    ["In dungeons (minutes)"] = "地下城中（分鐘）",
    ["0 uses the global warn threshold."] = "0 使用全域警告閾值。",
    ["Preferred food"] = "首選食物",
    ["Preferred flask or elixir"] = "首選藥劑或道標",
    ["Preferred weapon enhancement"] = "首選武器強化",
    ["Automatic (best in bags)"] = "自動（背包中最佳）",
    ["Click to use."] = "點擊使用。",
    ["Attach reminders to the cursor"] = "將提醒附加到游標",
    ["Shows small copies of the current reminders next to the mouse cursor."] = "在滑鼠游標旁顯示目前提醒的小型副本。",
    ["Helpers"] = "助手",
    ["Queue countdown, buff minigame helper and class trainer book in one place."] = "隊列倒數、增益小遊戲助手和訓練師書籍集中於一處。",
    ["Open group board"] = "開啟組隊面板",
    ["Scans chat for people forming groups and lists them by Classic/TBC instance in a window (/vlfg or the button below)."] = "掃描聊天中正在組隊的玩家，並在視窗中依經典舊世／燃燒的遠征副本分類列出（/vlfg 或下方按鈕）。",
    ["Show minimap button"] = "顯示小地圖按鈕",
    ["PvP Settings"] = "PvP設定",
    ["Fullscreen"] = "全螢幕",
    ["Fullscreen dialog"] = "全螢幕對話框",
    ["Tooltip"] = "滑鼠提示",
    ["Orientation"] = "方向",
    ["Horizontal"] = "水平",
    ["Vertical (up)"] = "垂直（向上）",
    ["Vertical (down)"] = "垂直（向下）",
    ["Fill opacity"] = "填充不透明度",
    ["Below 100 the world shows through the filled part of the bar."] = "低於100時，遊戲世界會透過條的填充部分顯現。",
    ["The fill fades into a second colour towards its end."] = "填充色會往末端漸變成第二種顏色。",
    ["Name inside the bar"] = "名字顯示在血條內",
    ["Anchors the name at the left edge inside the health bar instead of above it — the right edge stays free for the health text."] = "將名字固定在血條內的左緣而不是上方——右緣留給生命值文字。",
    ["Show plates for enemy pets"] = "顯示敌方寵物的名牌",
    ["Divider line on the target's bar"] = "目標血條上的分隔線",
    ["Draws a thin vertical line at the given percent of the health bar — an execute marker."] = "在血條的指定百分比處繪製一條細豎線——斬殺標記。",
    ["Line position (%)"] = "線的位置(%)",
    ["Only on your target"] = "僅限你的目標",
    ["Spell name"] = "法術名稱",
    ["Colour the last tick"] = "為最後一跳著色",
    ["Show latency text"] = "顯示延遲文字",
    ["Vertical"] = "垂直",
    ["Automatic stacks a side slot as a column and a top or bottom slot as a row."] = "自動：側邊位置直排為一列，上方或下方位置橫排為一行。",
    ["Show older versions"] = "顯示更早的版本",
    ["%d broken numeric values were removed from the settings so they can be saved again."] = "已從設定中移除 %d 個損壞的數值，設定即可再次儲存。",
    ["Widen window"] = "加寬視窗",
    ["Extra width for the friends window so long names, notes and zones fit on one line. 0 keeps Blizzard's width."] = "為好友視窗增加額外寬度，讓過長的名字、註記和區域能顯示在同一行。0 表示維持 Blizzard 的寬度。",
    ["Classic+ keeps Blizzard's layout with extras. Modern adds the dark chrome and moves all stats into a panel on the right of the character window."] = "Classic+ 保留 Blizzard 的版面並加入額外功能；Modern 加上深色外框，並將所有屬性移到角色視窗右側的面板。",
    ["Overrides the group switch for this entry alone - e.g. to track a buff someone else casts on you."] = "僅為此條目覆寫群組開關——例如追蹤別人施放在你身上的增益效果。",
    ["Group default"] = "群組預設",
    ["Anyone's"] = "任何人的",
    ["Use conditions"] = "使用條件",
    ["Unticked parks this entry: it keeps its settings but never shows. The gear holds moving, removing and per-entry settings."] = "取消勾選會擱置此條目：設定保留但永不顯示。齒輪中有移動、移除與個別條目設定。",
    ["Talent Window"] = "天賦視窗",
    ["Shows all three talent trees side by side in one window."] = "在同一視窗中並排顯示三棵天賦樹。",
    ["Points left: %d"] = "剩餘點數：%d",
    ["TALENTS"] = "天賦",
    ["Open Blizzard's talent window"] = "開啟 Blizzard 的天賦視窗",
    ["For glyphs and everything this window does not cover."] = "用於雕紋以及此視窗未涵蓋的所有功能。",
    ["|cffaaaaaaAll three talent trees side by side, with live ranks and click-to-learn. Glyphs stay in Blizzard's window, one button away.|r"] = "|cffaaaaaa三棵天賦樹並排顯示，即時顯示階級並可點擊學習。雕紋仍在 Blizzard 的視窗中，一鍵即達。|r",
    ["Replace Blizzard's talent window"] = "取代 Blizzard 的天賦視窗",
    ["Opening talents shows this window instead. Turn it off to get Blizzard's one-tree window back."] = "開啟天賦時會改為顯示此視窗。關閉後即恢復 Blizzard 的單樹視窗。",
    ["Open talent window"] = "開啟天賦視窗",
    ["See-through"] = "透明",
    ["Hide the box fill and labels while editing, so you can see the interface you are aligning. The thin borders stay."] = "編輯時隱藏方框的填充和標籤，以便看清正在對齊的介面。細邊框會保留。",
    -- Patch notes 1.46.0
    ["Options"] = "選項",
    ["Talents"] = "天賦",
    ["The page opens with two modes: Standard keeps Blizzard's bars with the skin rows, Modern runs the addon's own bars with a live preview, a per-bar background, button press and hover tints and an XP bar texture"] = "頁面提供兩種模式：標準保留暴雪快捷列和外觀選項，現代使用插件自帶的快捷列，帶即時預覽、每列獨立背景、按鍵按下與懸停染色以及經驗條材質",
    ["Modern – Third player cast bar style: flat look with name and timer on the bar, plus bar texture, border, a coloured last tick and a latency readout"] = "現代 – 玩家施法條的第三種樣式：扁平外觀，名稱和時間顯示在施法條上，另有施法條材質、邊框、著色的最後一跳和延遲顯示",
    ["The options page carries a live preview; clicking its icon or bar jumps to the matching section"] = "選項頁面帶有即時預覽；點擊其圖示或施法條會跳轉到對應設定區域",
    ["Enchant and gem displays no longer displace each other on non-English clients, and Chinese enchant text is no longer cut mid-character"] = "附魔與寶石顯示在非英文客戶端不再互相頂替，中文附魔文字也不會再被截斷到半個字元",
    ["Tracked entries sit two per row, each with a gear: park an entry without deleting it, move or remove it, set conditions, and override Only what I cast myself for that entry alone"] = "追蹤條目每行兩個，各帶齒輪：可以擱置條目而不刪除、移動或移除、設定條件，並為單個條目單獨覆蓋只算我自己施放的",
    ["See-through – Hides the box fill and labels while editing, so you can see the interface you are aligning"] = "透明 – 編輯時隱藏方框的填充和標籤，以便看清正在對齊的介面",
    ["Coordinates appear on the box while dragging or nudging, and the window being snapped to pulses white"] = "拖動或微調時座標直接顯示在方框上，吸附對齊的目標視窗會呈白色脈動",
    ["The loot window can be moved on Wrath clients"] = "在巫妖王之怒客戶端可以移動拾取視窗",
    ["Widen window – Extra width so long names, notes and zones fit on one line"] = "加寬視窗 – 增加寬度，讓較長的名字、備註和區域顯示在一行內",
    ["The close glyph of every window is larger now"] = "所有視窗的關閉符號現在更大了",
    ["Three tabs with a pinned live preview, a name-in-bar option and thousands separators on health numbers"] = "三個標籤頁帶固定即時預覽，可將名字放入血條內，生命值數字帶千位分隔符",
    ["Gear rows open inside their own column, aura rows align per row, helper tools share one tab, and the pinned page header of the last visited tab is cleared on switching"] = "齒輪行在自己的列內展開，光環行按行對齊，輔助工具共用一個標籤頁，切換時會清理上次訪問標籤頁的固定頁首",
    ["Only the last five versions build at once; a button loads the older ones"] = "一次只載入最近五個版本，按鈕可載入更早的版本",
    ["Orientation, fill opacity, frame strata and a live preview on the options page"] = "可設定方向、填充不透明度、框體層級，選項頁面帶即時預覽",
    ["A profile string can carry a selection: chosen modules, the window layout, talent overrides, and the account-wide fonts and colours"] = "設定檔字串可以只攜帶一部分內容：選定的模組、視窗佈局、天賦覆蓋設定以及全帳號字體和顏色",
    ["Per-rule switches with class-coloured names, a group scan for missing buffs, preferred food, flask and weapon oil, raid and dungeon thresholds, glow styles, scale and a live preview; middle-click hides a reminder until the next loading screen"] = "每條規則獨立開關並以職業顏色顯示名稱，掃描隊伍缺失增益，可設首選食物、精煉藥劑和武器油，團隊與地城閾值，發光樣式、縮放和即時預覽；中鍵點擊可隱藏提醒直到下次載入畫面",
    ["Broken numeric values are removed before saving and reported at the next login. A single such value used to reset every setting of the account to defaults"] = "損壞的數值會在保存前被移除，並在下次登入時報告。以前一個這樣的數值就會把整個帳號的設定重置為預設",
    ["Totemic Recall stands as its own button after the elements on Wrath clients"] = "在巫妖王之怒客戶端，收回圖騰在元素圖示後有獨立按鈕",
    ["Talent Window – All three talent trees side by side with live ranks and click-to-learn on Wrath clients; glyphs stay one button away"] = "天賦視窗 – 在巫妖王之怒客戶端並排顯示全部三系天賦，即時顯示點數，點擊即可學習；雕紋仍可一鍵打開",
    ["The string is selected - press Ctrl+C to copy it."] = "字串已選取 - 按 Ctrl+C 複製。",
    ["%d characters"] = "%d 個字元",
    ["Paste the string here with Ctrl+V."] = "在此處按 Ctrl+V 貼上字串。",
    ["String captured - %d characters."] = "已擷取字串 - %d 個字元。",
    ["Partial string: anything missing is taken from your active profile."] = "部分字串：缺少的部分將取自你目前的設定檔。",
    ["Unticked parts keep your current settings."] = "未勾選的部分將保留你目前的設定。",
    ["Profile '%s' imported. Switch to it now and reload the UI?"] = "已匯入設定檔「%s」。現在切換並重載介面？",
    ["Switch and reload"] = "切換並重載",
    ["Save a backup copy"] = "儲存備份副本",
    ["Creates a dated copy of the active profile as a restore point. Nothing switches - the copy just sits in the profile list."] = "建立目前設定檔的帶日期副本作為還原點。不會切換任何內容 - 副本只是留在設定檔清單中。",
    ["Backup '%s' created."] = "已建立備份「%s」。",
    ["Go back"] = "返回",
    ["Pixel-true plate size"] = "像素級名條大小",
    ["Sizes the plates in screen pixels instead of interface units: height 27 is then 27 pixels on any monitor and UI scale."] = "以螢幕像素而非介面單位設定名條大小：高度 27 在任何螢幕與介面縮放下都是 27 像素。",
    -- Patch notes 1.47.0
    ["The boxes now cover their window exactly, in the same dark look as the rest of the interface, with the name centred and shown in orange when the window is docked to another one"] = "方框現在精確覆蓋對應的視窗，與介面其餘部分同為深色風格；名稱置中顯示，當視窗停靠到另一個視窗時變為橙色",
    ["Outside the editor the small drag handle stays, so an unlocked cooldown bar still accepts dropped spells and test previews stay visible"] = "在編輯器之外仍保留小拖曳框，因此解鎖的冷卻列仍能接收拖放的法術，測試預覽也保持可見",
    ["The cloak equipment slot was translated with the navigation word for back in six languages and now reads correctly everywhere"] = "披風裝備欄位在六種語言裡被譯成了導航用的返回一詞，現在所有語言都顯示正確",
    ["Pixel-true plate size – Sizes the plates in screen pixels, so height 27 is 27 pixels on any monitor and interface scale"] = "像素級名條大小 – 以螢幕像素設定名條大小，高度 27 在任何螢幕與介面縮放下都是 27 像素",
    ["Plate sizes now mean exactly what the sliders say: the game no longer secretly enlarges the target's plate or shrinks distant ones, and the live preview matches the game — making the target larger is now solely the job of the target plate scale option"] = "名條大小現在與滑桿所示完全一致：遊戲不再偷偷放大目標的名條或縮小遠處的名條，即時預覽與遊戲一致——放大目標現在完全交給目標名條縮放選項",
    ["Save a backup copy – One click keeps a dated copy of the active profile as a restore point"] = "儲存備份副本 – 一次點擊即可保存目前設定檔的帶日期副本作為還原點",
    ["Exporting opens a proper window with the string already selected, and importing shows a preview first: rename the profile and untick the parts you do not want before anything is written"] = "匯出會開啟一個正式視窗且字串已選取，匯入會先顯示預覽：在寫入任何內容之前可以重新命名設定檔並取消勾選不需要的部分",
    ["Export strings are compressed to a fraction of their old length and fit in a chat message; strings from older versions still import"] = "匯出字串經過壓縮，長度只剩原來的幾分之一，可放進一條聊天訊息；舊版本的字串仍可匯入",
    ["On the Wrath client the talent tooltip showed a placeholder instead of the description, and the talent key would open the window but not close it — both fixed"] = "在巫妖王之怒客戶端上，天賦提示只顯示占位符而非描述，天賦快捷鍵能打開視窗卻無法關閉——兩者均已修復",
    ["%s Locked"] = "%s已封鎖",
    ["|cffffffffLOSS OF CONTROL|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffff失去控制|r\n|cffaaaaaa拖曳或方向鍵|r",
    ["%.1f seconds"] = "%.1f 秒",
    ["Loss of control mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Press the button again to finish."] = "失去控制的移動模式已開啟。|cff9b6cff拖曳紫色方塊|r或使用|cff9b6cff方向鍵|r（SHIFT = 5 像素）。再次點擊按鈕即可完成。",
    ["Preview"] = "預覽",
    ["Loss of Control"] = "失去控制",
    ["Shows what is controlling you right now -- stun, fear, root, silence, disarm or a school lockout -- with the effect icon, its name and the time left. Where two effects run at once the one that matters is shown large, and the next one as a small icon beside it."] = "顯示目前正在控制你的效果——昏迷、恐懼、定身、沉默、繳械或法術學派封鎖——並附上效果圖示、名稱與剩餘時間。若同時存在兩個效果，較重要的會以大圖示顯示，下一個則以小圖示顯示在旁邊。",
    ["Show loss of control alert"] = "顯示失去控制提示",
    ["Show in"] = "顯示於",
    ["Arena and battlegrounds"] = "競技場與戰場",
    ["Arena only"] = "僅競技場",
    ["Name font size"] = "名稱字型大小",
    ["Timer font size"] = "剩餘時間字型大小",
    ["Background and red lines"] = "背景與紅線",
    ["Show the next effect"] = "顯示下一個效果",
    ["Profile changed. Use /reload when you are out of combat."] = "設定檔已切換。脫離戰鬥後請使用 /reload。",
    ["Profile keybind"] = "設定檔快捷鍵",
    ["Switches to this profile outside combat and then asks to reload the UI. Override bindings are restored at login."] = "在非戰鬥狀態下切換到該設定檔，然後詢問是否重新載入介面。快捷鍵會在登入時還原。",
    ["Use the global font"] = "使用全域字型",
    ["Name color"] = "名稱顏色",
    ["Timer color"] = "剩餘時間顏色",
    ["|cffffffffINTERRUPTS|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffff打斷|r\n|cffaaaaaa拖曳或方向鍵|r",
    ["Interrupt bar mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Press the button again to finish."] = "打斷條的移動模式已開啟。|cff9b6cff拖曳紫色方塊|r或使用|cff9b6cff方向鍵|r（SHIFT = 5 像素）。再次點擊按鈕即可完成。",
    ["Interrupts"] = "打斷",
    ["Watches the combat log for enemy interrupts and starts a cooldown for each one, tracked per caster -- two enemies of the same class get an icon each. The border carries the caster's class colour."] = "監視戰鬥記錄中敵方的打斷技能，並依施法者分別開始冷卻計時——同職業的兩名敵人各占一個圖示。邊框顯示施法者的職業顏色。",
    ["Show interrupt bar"] = "顯示打斷條",
    ["Show interrupts that are still ready"] = "同時顯示已就緒的打斷技能",
    ["Timer text on the icons"] = "在圖示上顯示剩餘時間",
    ["Cooldown swipe on the icons"] = "在圖示上顯示冷卻掃描",
    ["Only take over the key while a fishing pole is worn"] = "僅在裝備釣竿時占用該按鍵",
    ["Without a pole in hand the key keeps whatever you bound it to, so it stays usable outside fishing. A cast already in the water keeps the key. This switches off auto-equipping a pole, which needs the key exactly while none is worn."] = "手中沒有釣竿時，該按鍵保留你自己設定的功能，在釣魚之外仍可正常使用。已經拋出的釣線會繼續占用按鍵。此設定會關閉自動裝備釣竿，因為該功能正需要在沒有釣竿時占用按鍵。",
    ["Stand-in for an enemy frame: the side strip is placed by the settings below."] = "敵方框體的佔位示意：側邊圖示列由下方的設定決定位置。",
    -- Patch notes 1.48.0
    ["Options Window"] = "設定視窗",
    ["Loss of Control – Shows the stun, fear, root, silence or lockout holding you, with its icon, its name and the time left"] = "失去控制 – 顯示目前正控制你的昏迷、恐懼、定身、沉默或學派封鎖，並附上圖示、名稱與剩餘時間",
    ["Interrupts – Tracks enemy interrupts from the combat log, one icon per caster, bordered in the caster's class colour"] = "打斷 – 透過戰鬥記錄追蹤敵方打斷，每名施法者一個圖示，邊框為其職業顏色",
    ["Timer Text On The Icons – Seconds left on the interrupt icons, with their own font, outline and colour"] = "在圖示上顯示剩餘時間 – 打斷圖示上的剩餘秒數，可單獨設定字型、外框與顏色",
    ["Cooldown Swipe On The Icons – Drop the sweeping shade and keep only the number"] = "在圖示上顯示冷卻掃描 – 去掉旋轉的陰影，只保留數字",
    ["The icon strip beside the enemy frames has a live preview on the General tab. Those frames exist only inside an arena, so its sliders used to move something you could not see."] = "敵方框體旁的圖示列在一般標籤頁有了即時預覽。這些框體只在競技場中存在，因此它的滑桿先前調整的是看不見的東西。",
    ["An unlocked mover box no longer vanished a moment after the button put it there. The box and a running preview now ignore the zone filter: you place a bar where you are standing, and that is rarely an arena."] = "解鎖的移動方塊不再在按鈕顯示它之後一瞬間消失。方塊與正在執行的預覽現在會忽略區域過濾：你在所站之處擺放列表，而那裡很少是競技場。",
    ["The pinned icon strip also appears on the Layout tab, where icon size, spacing, shape and zoom read back off it while the slider moves."] = "固定的圖示列現在也出現在版面標籤頁，拖曳滑桿時可直接在上面看到圖示大小、間距、形狀與縮放。",
    ["Moving Blizzard frames no longer marks every Edit Mode window as touched by this addon, which had the pet frame refused in combat. Selecting a layout caused it, and that ran on every editor entry even when nothing had been placed."] = "移動暴雪視窗不再把編輯模式的每個視窗都標記為被本插件碰過，這曾導致戰鬥中拒絕顯示寵物框體。原因是選擇版面配置，而且每次進入編輯器都會執行，即使從未擺放過任何東西。",
    ["The icon picker has a close button, and no longer floats over the game after the character sheet is shut."] = "圖示選擇器有了關閉按鈕，並且在角色面板關閉後不再懸浮於遊戲畫面上。",
    ["Only Take Over The Key While A Fishing Pole Is Worn – Without a pole the key keeps whatever you bound it to"] = "僅在裝備釣竿時占用該按鍵 – 沒有釣竿時該按鍵保留你自己設定的功能",
    ["The mouse wheel scrolls the sidebar and the page. The window also shrinks to fit a screen smaller than itself, which is what left it undraggable on a high interface scale."] = "滑鼠滾輪可捲動側欄與頁面。視窗還會縮小以符合比它更小的螢幕，而這正是高介面縮放下無法拖曳視窗的原因。",
    ["Profile Keybind – Put a profile on a key and switch to it out of combat"] = "設定檔快捷鍵 – 把設定檔放到一個按鍵上，脫離戰鬥時切換過去",
    ["The bag sweep behind the food, flask and weapon oil reminders is kept until the bags change, instead of walking every bag three times over twice a second."] = "食物、合劑與武器油提醒背後的背包掃描會一直保留到背包發生變化，而不是每秒兩次、每次走訪所有背包三遍。",
    ["The modern player frame style no longer reaches into the pet and totem frames."] = "現代玩家框體樣式不再干預寵物框體與圖騰框體。",
    ["Fine tuning for this slot"] = "此位置的微調",
    ["Slot settings"] = "位置設定",
    ["Border settings"] = "邊框設定",
    ["Border size"] = "邊框粗細",
    ["How solid the empty part of the bar is."] = "血條空白部分的不透明度。",
    ["Absorb settings"] = "吸收盾設定",
    ["Border around the cast bar"] = "施法條也顯示邊框",
    ["Off leaves the cast bar without its own outline; the health bar keeps one."] = "關閉後施法條不再有自己的邊框，生命條的邊框保留。",
    ["Top text"] = "頂部文字",
    ["Left text"] = "左側文字",
    ["Right text"] = "右側文字",
    ["Centred text"] = "置中文字",
    ["Unit name"] = "單位名稱",
    ["Main text positions"] = "主要文字位置",
    ["|cffaaaaaaOne thing per slot. The level rides at the name's left edge and follows it.|r"] = "|cffaaaaaa每個位置只放一樣。等級緊貼名稱左側並跟隨它。|r",
    ["Health and cast bar"] = "生命條與施法條",
    ["Health bar width"] = "生命條寬度",
    ["Health bar height"] = "生命條高度",
    ["Cast icon"] = "施法圖示",
    ["Cast icon settings"] = "施法圖示設定",
    ["Cast background"] = "施法背景",
    ["Cast bar border"] = "施法條邊框",
    ["Thickness of the cast bar's own border. 0 removes it; the health bar keeps its own."] = "施法條自身邊框的粗細。0 表示不顯示，生命條的邊框保留。",
    ["Cast bar border colour"] = "施法條邊框顏色",
    ["Cast timer"] = "施法計時",
    ["Cast timer settings"] = "計時設定",
    ["Cast bar Y offset"] = "施法條 Y 偏移",
    ["Cast colours and effects"] = "施法顏色與效果",
    ["The bar's colour while a spell is being cast."] = "施放法術時施法條的顏色。",
    ["More cast colours"] = "更多施法顏色",
    ["Interrupt ready"] = "打斷已就緒",
    ["Interrupt flash"] = "打斷閃光",
    ["Interrupt-ready hint"] = "提示：打斷已就緒",
    ["Show cast bars in front of nameplates"] = "將施法條顯示在名條前方",
    ["Casts draw above every plate, so a cast you care about is never hidden behind another unit's bar."] = "施法條繪製在所有名條之上，重要的施法不會被其他單位的血條擋住。",
    ["The enemy's cast bar flashes and reads 'Interrupted' for a moment when their cast is stopped."] = "敵方施法被打斷時，施法條會閃爍並短暫顯示「已打斷」。",
    ["Interrupt flash settings"] = "打斷閃光設定",
    ["Target, focus and hover effects"] = "目標、焦點與滑鼠停留效果",
    ["Target effect"] = "目標效果",
    ["A coloured edge around the plate you have targeted."] = "在你選取的名條周圍顯示彩色邊框。",
    ["Target effect settings"] = "目標效果設定",
    ["Target arrows"] = "目標箭頭",
    ["Arrow settings"] = "箭頭設定",
    ["Target bar colour on"] = "啟用目標顏色",
    ["Focus bar colour on"] = "啟用焦點顏色",
    ["A coloured edge around the plate you have set as your focus."] = "在你設為焦點的名條周圍顯示彩色邊框。",
    ["Mouseover effect"] = "滑鼠停留效果",
    ["Mouseover effect settings"] = "滑鼠停留效果設定",
    ["General text"] = "通用文字",
    ["Debuff duration"] = "減益持續時間",
    ["Buff duration"] = "增益持續時間",
    ["Crowd control duration"] = "控制持續時間",
    ["Aura stacks"] = "光環層數",
    ["Timer text colour"] = "計時文字顏色",
    ["Stack text colour"] = "層數文字顏色",
    ["Text settings"] = "文字設定",
    ["Spell target"] = "施法目標",
    ["Background settings"] = "背景設定",
    ["Hide the gryphons"] = "隱藏獅鷲",
    ["Removes the two beasts at the ends of Blizzard's main action bar. The bar itself stays."] = "移除預設動作列兩端的兩隻神獸。動作列本身保留。",
    ["Extra indicators"] = "其他指示器",
    ["Enemy colours"] = "敵人顏色",
    ["Enemy types"] = "敵人類型",
    ["The health bar colour a unit takes from its reaction to you."] = "血條依單位對你的態度所取的顏色。",
    ["Neutral enemies"] = "中立單位",
    ["Units that are not hostile until you make them so."] = "在你主動招惹之前不會敵對的單位。",
    ["Other nameplates"] = "其他姓名板",
    ["Nameplate spacing"] = "名條間距",
    ["|cffaaaaaaThe game's own settings, changed live and not part of the profile — except the hitbox. Not changeable in combat.|r"] = "|cffaaaaaa遊戲本身的設定，立即生效且不隨設定檔保存 —— 點擊區域除外。戰鬥中無法變更。|r",
    ["Stackable nameplates"] = "可堆疊的名條",
    ["Extra aura options"] = "額外光環選項",
    ["Target and focus effects"] = "目標與焦點效果",
    ["Plate scale while casting"] = "施法時的名條大小",
    ["A casting unit's plate grows to this size, so the one that matters stands out. 100 = off."] = "正在施法的單位其名條會放大到這個尺寸，讓重要的目標更醒目。100 表示關閉。",
    ["Opacity while casting"] = "施法時的不透明度",
    ["A casting unit's plate is at least this opaque, even when something else is targeted."] = "正在施法的單位其名條至少保持這個不透明度，即便你選取了別的目標。",
    ["The unit's name gives way to the spell name for as long as the cast runs."] = "施法期間，單位名稱讓位給法術名稱。",
    ["Active talent group"] = "目前啟用的天賦方案",
    ["Left-click: show this talent group"] = "左鍵點擊：檢視該天賦方案",
    ["Right-click: activate this talent group"] = "右鍵點擊：啟用該天賦方案",
    ["Talent group %d (not active)"] = "天賦方案 %d（未啟用）",
    ["Talents can only be learned in the active talent group."] = "只能在目前啟用的天賦方案中學習天賦。",
    ["Talent groups cannot be switched in combat."] = "戰鬥中無法切換天賦方案。",
    ["This client refused to switch the talent group."] = "此客戶端拒絕切換天賦方案。",
    ["Input line above the chat"] = "輸入列置於聊天上方",
    ["Puts the chat input line above the message area instead of below it. The panel and the tab bar follow it."] = "把輸入列放在訊息區上方而不是下方。面板與標籤列會隨之移動。",
    ["Own background for the input line"] = "輸入列使用自有背景",
    ["Draws the input line on our own dark background instead of Blizzard's. The dark background panel already covers the input line, so this shows once that panel is off."] = "讓輸入列使用我們自己的深色背景，而不是暴雪的預設背景。深色背景面板本就覆蓋了輸入列，因此關閉該面板後才會顯現。",
    ["Addon buttons"] = "插件按鈕",
    ["Click to show or hide the collected buttons."] = "點擊可顯示或隱藏已收納的按鈕。",
    ["Where other addons' minimap buttons sit: around the map, hidden until the mouse is over it, or gathered in one box under it."] = "其他插件的小地圖按鈕放在哪裡：環繞地圖、滑鼠移上去才顯示，或收納到地圖下方的一個盒子裡。",
    ["Around the minimap"] = "環繞小地圖",
    ["Only on mouseover"] = "僅滑鼠停留時",
    ["Collected in a box"] = "收納到一個盒子裡",
    -- Patch notes 1.49.0
    ["Hide The Gryphons – Takes the two beasts off the ends of Blizzard's main bar without dimming anything else"] = "隱藏獅鷲 – 移除暴雪主動作列兩端的兩隻野獸，其餘部分不做任何變暗處理",
    ["Switching the module off now switches it off. Its handlers are registered when the addon loads, so a module that was already off at login never ran its shutdown: being stunned in a battleground still popped the loss-of-control display, and the interrupt bar filled up and never emptied again, because the ticker that clears its icons only starts when the module is switched on."] = "關閉模組現在是真的關閉。它的處理器在插件載入時註冊，所以登入時就已關閉的模組從未走過關閉流程：在戰場上被控制仍會彈出失控提示，打斷列會填滿且再也不清空，因為清理其圖示的計時器只在模組開啟時啟動。",
    ["The interrupt bar no longer reads the whole world's combat log. It registered on load and never unregistered, so every combat line anywhere — several thousand a second in a raid — was taken apart for a bar whose own default is arena and battlegrounds only. It uses the same zone filter as the display beside it now."] = "打斷列不再讀取整個世界的戰鬥紀錄。它在載入時註冊且從未取消註冊，於是任何地方的每一行戰鬥紀錄——團隊副本裡每秒數千行——都被拆解，只為一個預設值本就是競技場與戰場的列。現在它使用與旁邊提示相同的區域過濾。",
    ["Switching the module on inside an arena counts as arriving. The zone decision used to live in the loading screen alone, so anyone who enabled it while already in there got no diminishing-returns ticker until the next one."] = "在競技場內開啟模組也算作抵達。區域判斷先前只發生在載入畫面，因此已經身處其中才開啟的人，直到下一場都拿不到遞減計時器。",
    ["The item level text size slider works again. It looked for the numbers in two places it hoped they would be, and where a client parents its paper doll buttons elsewhere it found none and quietly did nothing — which from the outside is indistinguishable from the text simply being too small."] = "裝備等級文字大小的滑桿又能用了。它在兩個自認為會有數字的位置尋找，而當客戶端把裝備格按鈕掛在別處時，它一個也找不到，於是悄悄什麼都不做——從外面看，這和文字本來就太小毫無區別。",
    ["Input Line Above The Chat – Puts the input line over the message area instead of under it, with the panel and the tab bar following it; Wrath client only"] = "輸入列置於聊天上方 – 把輸入列放在訊息區上方而不是下方，面板與標籤列會隨之移動；僅限 Wrath 客戶端",
    ["Own Background For The Input Line – Draws the input line on its own dark background instead of Blizzard's, which is what you saw once the dark panel was off; Wrath client only"] = "輸入列使用自有背景 – 讓輸入列使用我們自己的深色背景，而不是暴雪的預設背景，也就是關閉深色面板後你會看到的那個；僅限 Wrath 客戶端",
    ["Icon zoom is now called Icon crop and reads in percent. It is the same question the nameplate sliders ask, and it was answering in hundredths while they answered in percent."] = "圖示縮放現在叫圖示裁切，並以百分比顯示。這與名條滑桿提出的是同一個問題，而它先前用百分之一作答，那邊卻用百分比作答。",
    ["The extra width belongs to the friends tab alone now. The row texts there stretch with the window, but the column headers on the who, guild and raid tabs sit at fixed offsets and stay put, so every point of width you added landed in an empty right half. Those three tabs go back to Blizzard's own proportions, which is what their columns were measured for."] = "額外寬度現在只屬於好友標籤頁。那裡的行文字會隨視窗一起延展，但查詢、公會與團隊標籤頁的欄標題固定在原處不動，因此你增加的每一點寬度都落進了右半邊的空白。這三個標籤頁恢復暴雪自己的比例，也正是它們的欄位當初丈量的依據。",
    ["The set list and the icon picker take the character panel's style. In the classic style they used to be a flat dark surface with a purple edge holding Blizzard's red buttons — two materials in a hand's width. They now carry Blizzard's dialog frame there and stand in the same material as the window they hang off, while the modern style keeps the flat look."] = "套裝清單與圖示選擇器採用角色面板的樣式。在經典樣式下，它們是一塊帶紫色邊緣的深色平面，裡面放著暴雪的紅色按鈕——一掌之內兩種材質。現在那裡改用暴雪的對話框邊框，與其依附的視窗同屬一種材質，而現代樣式保留扁平外觀。",
    ["The character panel no longer breaks when the sidebar builds its first set row. The marker bar on the row still reached for an accent colour that had been removed, so the list stayed empty and the panel came up bare."] = "側欄建立第一行套裝時，角色面板不再中斷。行上的標記條仍在讀取一個已被移除的強調色，導致清單為空、視窗空白開啟。",
    ["Addon Buttons – Choose where other addons' buttons sit: around the map, hidden until you mouse over it, or gathered in one box below it; Wrath client only"] = "插件按鈕 – 選擇其他插件的按鈕放在哪裡：環繞地圖、滑鼠移上去才顯示，或收納到地圖下方的一個盒子裡；僅限 Wrath 客戶端",
    ["Icon Crop (%) – How much of the border the game bakes into its icons is cut away, set per aura row and for the cast bar icon"] = "圖示裁切 (%) – 遊戲烘焙在圖示裡的邊框要裁掉多少，可依光環列分別設定，施法列圖示也有一項",
    ["The rounded bar style no longer leaves dead space at both ends. The round shape does not fill its own image — a transparent border runs all the way round it — and stretching that border across a wide, short bar put roughly eleven points of empty bar at each end and barely one above and below, which is why it showed up sideways and not upright."] = "圓角列樣式不再在兩端留下空白。圓形形狀並未填滿自己的圖像——它四周環繞著一圈透明邊緣——把這圈邊緣延展到又寬又矮的列上，兩端各留下約十一點的空列，上下卻只有一點，所以橫向顯眼而縱向不顯。",
    ["The options page is cut by question instead of by mechanism. Sixteen sections had settings that belong together lying far apart, with the bar texture under one heading and the cast bar's texture under another; eight settings were reachable from two sections at once."] = "選項頁依問題劃分，而不是依機制。十六個區塊裡彼此相關的設定相隔很遠，列材質在一個標題下，施法列材質在另一個標題下；有八項設定可以從兩個區塊同時抵達。",
    ["Every text on the plate sits in a slot now, the way the aura rows already did: top, left, right or centred, filled with the unit name or the health text. Four on/off switches became position pickers, each starting on the place its text already had."] = "名條上的每段文字現在都佔據一個位置，就像光環列早已如此：上方、左側、右側或置中，填入單位名稱或生命值文字。四個開關變成了位置選擇器，每個都從其文字原本所在的位置開始。",
    ["The stacking dropdown had no readable value at all. It was reading a setting this client does not have; the one it does have is now read and written, measured in the running game."] = "堆疊方式的下拉選單顯示不出任何可讀的值。它讀取的是這個客戶端沒有的設定；它確實擁有的那個現在會被讀寫，並已在執行中的遊戲裡實測。",
    ["A gear icon on a half-width row opens a small floating window instead of unfolding inside the cell. Half a cell has no room for a slider, and six of them had been squeezed into stubs."] = "半寬列上的齒輪會開啟一個浮動小視窗，而不是在儲存格內展開。半個儲存格放不下滑桿，其中六個曾被擠成殘段。",
    ["Colour swatches, eyes, gears and arrows sit directly beside the control they belong to rather than in the icon strip on the right, which stays reserved for the gear and the info dot."] = "色塊、眼睛、齒輪與箭頭直接位於它們所屬控制項的旁邊，而不是右側圖示列內——那列依舊留給齒輪與資訊點。",
    ["On the Wrath client the module stands down completely and the client keeps its own window. Our restyle addresses Blizzard's widgets by name and by region number, and behind those names that client has a different anatomy: black holes where the hidden regions used to be, a stretched title bar, dropdowns over the recipe list — and no error, because nothing throws, it simply lands on the wrong widgets."] = "在 Wrath 客戶端上，本模組完全退讓，客戶端保留自己的視窗。我們的重繪依名稱與區域編號定位暴雪的控制項，而在那個客戶端上，同樣的名稱背後是另一套結構：被隱藏的區域處出現黑洞、標題列被延展、下拉選單壓在配方清單上——而且不報錯，因為它什麼都沒拋出，只是落在了錯誤的控制項上。",
    ["Talent group buttons run down the right edge, one for each group you have bought. Left-click shows a group, right-click activates it, the same split Blizzard's own window uses. Talents can only be learned in the active group, so a click in the preview does nothing and the tooltip says so beforehand."] = "右側邊緣排列著天賦方案按鈕，每個已購買的方案一個。左鍵點擊檢視某個方案，右鍵點擊啟用它，與暴雪自家視窗的分工相同。天賦只能在目前啟用的方案中學習，因此在預覽裡點擊不會有任何反應，提示框也會事先說明。",
    ["The tab carries a book instead of a question mark. That mark is Blizzard's placeholder for a missing icon and read like a defect."] = "標籤頁帶的是一本書而不是問號。那個問號是暴雪用於缺失圖示的佔位符，看起來像是出了故障。",
    ["Glyphs"] = "雕文",
    ["CHARACTER"] = "角色",
    ["Packs the selected bar setup into a string you can pass on. Slots, macros and key bindings travel with it."] = "把選中的快捷列配置打包成一段可以轉交的字串。按鍵位、巨集與快速鍵都會一起帶上。",
    ["Reads a bar setup string into your library. Putting it onto your bars stays a separate step."] = "把快捷列配置字串讀入你的收藏。真正套用到快捷列上仍是單獨的一步。",
    ["The bar setup string is damaged."] = "快捷列配置字串已損壞。",
    ["This is not a bar setup string."] = "這不是快捷列配置字串。",
    ["Bar setup '%s' imported."] = "已匯入快捷列配置 '%s'。",
    ["Macros left alone: the switch above is off."] = "巨集未更動：上方的開關是關閉的。",
    ["Macros: %d restored, |cffff8800%d failed|r -- the macro list may be full."] = "巨集：已恢復 %d 個，|cffff8800%d 個失敗|r——巨集清單可能已滿。",
    ["Macros: %d restored."] = "巨集：已恢復 %d 個。",
    ["Key bindings left alone: the switch above is off."] = "快速鍵未更動：上方的開關是關閉的。",
    ["Key bindings: %d applied."] = "快速鍵：已套用 %d 個。",
    ["Bar setup '%s' saved: %d slots, %d macros, %d key bindings."] = "已儲存快捷列配置 '%s'：%d 個按鍵位、%d 個巨集、%d 個快速鍵。",
    ["|cffff8800No key bindings were captured.|r This client may not report them."] = "|cffff8800沒有採集到任何快速鍵。|r該客戶端可能不會回報快速鍵。",
    -- Patch notes 1.50.0
    ["Export as string – Packs the selected setup into a string you can pass on, with its slots, macros and key bindings"] = "匯出為字串 – 把選中的配置連同按鍵位、巨集與快速鍵一起打包成可以轉交的字串",
    ["Import from string – Reads someone else's setup into your library; a name you already use gets a number rather than being overwritten"] = "從字串匯入 – 把別人的配置讀入你的收藏；已經在用的名稱會加上編號，而不是被覆蓋",
    ["An imported setup is rebuilt entry by entry before it is stored. The restore walks every entry, so a malformed one would have thrown in the middle of a run with part of your bars already changed. Broken entries are dropped, the rest still arrives."] = "匯入的配置在入庫前會逐條重建。還原過程會讀取每一條，因此只要有一條格式不對，就會在中途出錯，而那時你的一部分快捷列已經被改動了。損壞的條目會被丟棄，其餘的照常送達。",
    ["Saving and loading say what they did. Both had been counting their work all along and throwing the numbers away, so a setup whose macros all failed looked exactly like one that had none, and a save that captured no key bindings said nothing at all."] = "儲存與載入會說明自己做了什麼。兩者一直都在統計自己的工作，卻把數字全丟掉了：巨集全部失敗的配置看起來和根本沒有巨集的配置一模一樣，而一次沒採集到任何快速鍵的儲存則什麼都不說。",
    ["The character window can be placed by hand on the Wrath client. Blizzard's editor does not own that window, so it takes the same direct route the loot window already uses; one box moves the character, reputation and skills tabs together, and the stats panel and set list travel with it."] = "在 Wrath 客戶端上，角色視窗可以手動擺放。暴雪的編輯器並不管這個視窗，因此它走的是拾取視窗已經在用的直接路徑；一個方框會同時移動角色、聲望與技能三個標籤頁，屬性面板與套裝清單也一併跟著走。",
    ["The window starts wide on the Wrath client. The slider has always gone to 400 — it simply started at nothing, so the extra room only ever reached whoever went looking for it."] = "在 Wrath 客戶端上視窗一開始就是寬的。滑桿一直都能拉到 400——它只是從零開始，所以多出來的空間只落到願意去找它的人手裡。",
    ["The glyph page opens from a button under the talent group buttons, and it is dark now. The rune circle is dimmed rather than removed, because it is what makes that page recognisable; the sockets take the accent colour, and the glyph artwork and the pickup highlight stay as they are."] = "雕文頁面由天賦方案按鈕下方的一個按鈕開啟，現在是深色的。符文圓環是被調暗而不是移除，因為正是它讓人認出這個頁面；鑲孔取用強調色，雕文本身的圖案與拾取時的高亮保持原樣。",
    ["The talent group button shows its tree's icon instead of a question mark. It asked for that icon through an interface that does not answer on every client, and fell back to the placeholder; the answer is now worked out from the ranks themselves, which cannot be misread."] = "天賦方案按鈕顯示所屬天賦樹的圖示，而不是問號。它先前透過一個並非在所有客戶端都會作答的介面索取該圖示，於是退回佔位符；現在答案直接從天賦點數本身推得，而點數是不會被誤讀的。",
    ["The level number on the player frame sits where the client puts it on the Wrath client. Our two anchors are measured against one frame sheet, and where a different one ships, the number landed beside the portrait — the client keeps that anchor itself there anyway, moving it as the rest and PvP icons come and go."] = "在 Wrath 客戶端上，玩家框架的等級數字回到客戶端給它安排的位置。我們的兩個錨點是照著一套框架貼圖量出來的，換成另一套時數字就落到了頭像旁邊——何況客戶端本來就自己維護這個錨點，會隨著休息與 PvP 圖示的出現與消失而挪動它。",

    -- Character Panel: socket strip
    ["Socket strip under the window"] = "視窗下方的插槽列",
    ["Puts a strip with every socket of your equipped gear under the character window. Click a socket to put a gem from your bags into it. Stays empty on clients whose game has no gems."] = "在角色視窗下方放置一列列出你所穿裝備全部插槽的條列。點擊某個插槽，即可把背包裡的寶石鑲入其中。在沒有寶石的遊戲客戶端上保持為空。",
    ["Choose a gem"] = "選擇寶石",
    ["No gems in your bags."] = "背包裡沒有寶石。",
    ["Empty socket"] = "空插槽",
    ["Click to pick a gem from your bags."] = "點擊以從背包中挑選寶石。",
    ["Cannot socket gems in combat."] = "戰鬥中無法鑲嵌寶石。",
    ["Close the socketing window first."] = "請先關閉鑲嵌視窗。",
    -- Patch notes 1.51.0
    ["Socket strip under the window – A row of every socket on your equipped gear, hung under the character window; click a socket to put a gem from your bags into it"] = "視窗下方的插槽列 – 一列列出你所穿裝備全部插槽的條列，位於角色視窗下方；點擊某個插槽即可把背包裡的寶石鑲入其中",
    ["The enchant text on armour slots reads the enchant again instead of the item's difficulty tag. The filter took the first green line of the tooltip, and where an item carries a tag that tag stands above the enchant — so every such slot showed the tag, while a weapon two rows down showed its enchant correctly because nothing stood in front of it. The tag and the client's bracketed hints are both recognised now, in every language rather than only in English and German."] = "護甲欄位的附魔文字重新顯示附魔，而不是物品的難度標記。過濾器取的是提示訊息裡第一行綠字，而帶標記的物品，其標記就排在附魔之上——於是每個這樣的欄位都顯示標記，而兩行之下的武器因為前面沒有別的，附魔顯示正確。現在標記和客戶端的角括號提示都會被識別，而且適用於所有語言，不再只有英語和德語。",
    ["The set list no longer casts a shadow past its own frame. What looked like the background standing out over the border was a drop shadow: not an outline but four filled rectangles reaching up to seven pixels beyond the frame on every side, and behind Blizzard's dialog frame there was nothing for it to fall on. It is gone in both looks."] = "套裝清單不再把陰影投到自己的邊框之外。看上去像是背景越過邊框的那一塊其實是投影：它不是描邊，而是四個填滿的矩形，每一側最多伸出邊框七個像素，而在暴雪的對話框邊框後面它根本無處可落。兩種外觀下都已移除。",
    ["In the Classic+ look the dark ground stopped short of the ornate line instead of ending on it, and so showed past the frame on every side."] = "在 Classic+ 外觀下，深色底面停在紋飾線之前而不是正好落在線上，因此四面都露到了邊框之外。",

    -- Nameplates: layout preset + health text content
    ["Apply this arrangement"] = "套用此佈局",
    ["Puts the unit name and the health value inside the bar, crowd control left of it, incoming debuffs above that and buffs to its right, and gives the cast bar its icon, its remaining time and its target. Your current arrangement is saved first and the button beside this one brings it back."] = "把單位名稱和生命值放進血條內，控制效果置於其左側，進入的減益置於其上方，增益置於其右側，並為施法條加上圖示、剩餘時間和目標。你目前的佈局會先被儲存，旁邊的按鈕可以還原。",
    ["Restore my arrangement"] = "還原我的佈局",
    ["Puts every text and aura position back to what it was before the arrangement was applied, and removes the saved copy. Anything you moved by hand since then goes back as well."] = "把每一處文字與光環的位置恢復到套用佈局之前的樣子，並刪除儲存的副本。此後你手動挪動過的內容也會一併還原。",
    ["Nameplate layout applied. The button beside it puts your old one back."] = "姓名板佈局已套用。旁邊的按鈕可還原原來的佈局。",
    ["Nameplate layout restored."] = "姓名板佈局已還原。",
    ["Shows"] = "顯示",
    ["Current health"] = "目前生命值",
    ["Current and maximum"] = "目前與最大",
    ["Current and percent"] = "目前與百分比",
    ["Separator"] = "分隔符號",
    ["What goes between the two numbers, when the row above is set to current and percent."] = "當上面一行設為目前與百分比時，兩個數字之間放什麼。",
    ["Brackets"] = "括號",
    ["Vertical bar"] = "豎線",
    ["Dash"] = "短橫線",
    ["Space"] = "空格",
    -- Patch notes 1.52.0
    ["The own background for the input line is offered on every client. It was limited to one client generation, and the code already said it would work everywhere."] = "輸入行的自有背景現在在所有客戶端上提供。它先前被限制在一個客戶端世代，而程式碼裡早就寫著它在哪裡都能用。",
    ["The icon borders are pixel-exact. The border there is not a texture of its own but the rim of a plate behind the icon, so the two have to sit on the same pixel grid, the thickness has to be counted in pixels rather than frame units, and the icon size and spacing have to begin on whole pixels. None of the three was true, which is why a rim came out two pixels on one edge and none on the opposite."] = "圖示邊框現在精確到像素。那裡的邊框並不是自己的貼圖，而是圖示後面一塊底板露出的邊，所以兩者必須落在同一套像素格線上，粗細要按像素而不是框體單位來算，尺寸和間距也要落在整像素上。三點一條都不滿足，於是同一個邊一側有兩像素、對側一點也沒有。",
    ["Apply this arrangement – Puts the unit name and the health value inside the bar, crowd control left of it, incoming debuffs above that and buffs to its right, with the cast bar carrying its icon, its remaining time and its target"] = "套用此佈局 – 把單位名稱和生命值放進血條內，控制效果置於其左側，進入的減益置於其上方，增益置於其右側，施法條則帶上圖示、剩餘時間和目標",
    ["The unit name was hidden behind the health bar fill as soon as a text slot put it inside the bar. The name and the health value hang from different parents: the value is created on the bar, the name on the plate, and the bar is a child of the plate — so it draws over anything the plate draws. While the name only ever sat above the bar this never showed. It has its own layer now, above the bar but not attached to it, because name-only mode hides that bar and a text parented to a hidden frame would go with it."] = "只要某個文字位把單位名稱放進血條內，名稱就藏到了血條填充的後面。名稱和生命值掛在不同的父層上：數值建立在血條上，名稱建立在姓名板上，而血條是姓名板的子層，因此會蓋住姓名板畫的一切。名稱一直只待在血條上方時，這從未顯露。現在它有了自己的一層，位於血條之上卻不依附於它——因為只顯示名稱的模式會隱藏那條血條，而掛在隱藏框體上的文字會跟著一起消失。",
    ["The health text has its controls back: what it shows, and which mark goes between the two numbers. Both were still being read and had been unreachable since the page was rebuilt."] = "生命值文字重新有了設定：顯示什麼，以及兩個數字之間放哪個符號。兩者一直都在被讀取，卻自從頁面重做之後就無處可改。",
    ["The active talent group was always reported as the first one on clients that do not carry the newer interface for it. Everything behind that believed group one was running: the header called the group you were standing in not active, the activate button offered to switch to the one already on, and the switch reported success while changing nothing. Five files ask that same question, so profile overrides and bar setups were reading it too."] = "在沒有相應新介面的客戶端上，目前生效的天賦方案總是被報成第一個。它後面的一切都以為方案一在執行：標題把你正身處的方案稱為未啟用，啟用按鈕提議切換到已經在跑的那個，而切換會回報成功卻什麼也沒改。有五個檔案問的是同一個問題，所以設定覆蓋和快捷列方案也在讀它。",
    ["The glyph page stands permanently beside the window. It is lifted out of Blizzard's talent frame, where it lives inside the scroll area of the very window we replace, and handed back when ours closes."] = "雕文頁面固定停在視窗旁邊。它是從暴雪的天賦框體裡取出來的——那頁原本就住在我們所替換的那個視窗的捲動區域內——並在我們的視窗關閉時交還回去。",
    ["The separate glyph button is gone with it. Its only job was to send you to the page that now stands in front of you."] = "單獨的雕文按鈕隨之取消。它唯一的用處就是把你送去那一頁，而那一頁現在就擺在你面前。",
    ["A band under the header carries the activate button and the name of the talent group on screen. Until now switching existed only as a right-click on the small side icons, and nothing announced it."] = "標題下方的一條區域放著啟用按鈕和目前所看方案的名稱。在此之前，切換只存在於右鍵點擊側邊的小圖示，而這一點沒有任何提示。",
    ["Form paging"] = "形態換頁",
    ["Keep the main bar on its page in every form"] = "在所有形態下讓主動作列保持目前頁面",
    ["|cffaaaaaaCat, bear, stealth, stances and Shadowform normally swap the main bar to their own page. Switch this off to keep the bar you built through every form.|r"] = "|cffaaaaaa豹、熊、潛行、姿態和暗影形態通常會把主動作列切換到各自的頁面。關閉此項，你自己編排的動作列在任何形態下都保持不變。|r",
    -- Patch notes 1.52.1
    ["Keep the main bar on its page in every form – Cat, bear, stealth, stances and Shadowform stop swapping action bar 1 to a page of their own"] = "在所有形態下讓主動作列保持目前頁面 – 豹、熊、潛行、姿態和暗影形態不再把動作列 1 切換到各自的頁面",
    ["The ticker that paints cooldown dimming and range colouring no longer walks switched-off bars. It read and repainted every action bar five times a second, including the ones whose buttons nobody can see, so running two bars cost as much as running all of them."] = "繪製冷卻變暗與距離染色的計時器不再走訪已關閉的動作列。它每秒讀取並重繪每一條動作列五次，連沒人看得見按鈕的那些也算在內，於是只用兩條的代價和全開一樣。",
    ["Leaving a button no longer builds a fresh check each time. The check only ever reads the bar, not the button, so it is built once per bar and shared by all of its buttons."] = "離開按鈕時不再每次都新建一個檢查函式。該檢查只讀取動作列而不讀取按鈕，因此每條動作列只建一次，由它的所有按鈕共用。",
    ["The opponent frames are left alone unless you actually asked for a different arrangement. They are protected frames: anchoring one from our side is allowed outside a fight, but it marks the frame for the rest of the session, and the next time the default interface repositions it during a round its own call is refused and the block is reported against us. There is no way to anchor a protected frame without leaving that mark, so an untouched setup now keeps the default stacking. Order, spacing, grow direction and slot offsets all still work — the message becomes the price of a feature you asked for rather than something every arena hands out for free."] = "除非你確實要求了另一種排列，否則不再更動對手框架。它們是受保護的框架：在戰鬥外錨定是允許的，但會為該框架留下標記直到本次登入結束；下一次預設介面在一局中途自行移動它時，它自己的呼叫會被拒絕，而這次阻擋會被記到我們頭上。沒有辦法在不留下該標記的情況下錨定受保護框架，因此未更動的設定現在保留預設堆疊方式。順序、間距、生長方向和槽位偏移仍然有效——這則訊息因此成為你主動要求的功能的代價，而不是每場競技場都白白奉送的東西。",
    ["Move up and move down work again on a category you switched off and back on. The order list was filled once, while it was still empty, so anything that did not exist at that moment never got an entry, and its arrows then did nothing at all for the rest of the session without saying so."] = "對於你關閉又重新開啟的分類，上移和下移重新生效。順序清單只在仍為空時填充過一次，那一刻不存在的項目便再也沒有拿到位置，它的箭頭此後整個登入期間毫無反應，也不出聲。",
    ["Switching a module off releases its event handlers again. The note recording which module owns a handler stayed behind when the handler was unregistered, and that note kept a hard reference to every handler the module had ever registered."] = "關閉一個模組會重新釋放它的事件處理函式。記錄某個處理函式屬於哪個模組的備註在取消註冊時留了下來，而這條備註一直強引用著該模組註冊過的每一個處理函式。",
    -- Patch notes 1.52.2
    ["Casting out of the spell book keeps working after the book was opened from the micro menu. Our micro buttons are stand-ins that hand the click on to the default button behind them, which runs everything that follows inside our own call — and for the spell book that ends in the book writing down which half of itself it is showing. That note then counted as ours, the book reads it on every click on a spell, and so every cast from the book was refused as coming from an addon. Out of combat as well, for the rest of the session, until the interface was reloaded. Opening the book by its key was never affected. The micro menu now carries the default button itself, wearing our icon, so nothing is handed through us any more."] = "從微型選單打開法術書後，仍然可以從法術書施放法術。我們的微型選單按鈕只是替身，會把點擊轉交給後方的原版按鈕，於是接下來的一切都在我們自己的呼叫裡執行——對法術書而言，這最終會讓法術書記下它正在顯示自己的哪一半。那筆記錄隨後被算作我們的，而法術書在每次點擊法術時都會讀它，於是從書裡施放的每一次法術都被當成插件的呼叫而遭拒絕。戰鬥之外同樣如此，並持續整個遊戲階段，直到重新載入介面為止。用快捷鍵打開法術書從來不受影響。現在微型選單裡放的就是原版按鈕本身，只是換上我們的圖示，不再有任何東西經我們轉交。",
    ["Pointing at a bag slot shows the tooltip of the bag itself — quality colour, how much it holds, everything the item carries — with the click hints under it, instead of the bare name. In the inventory window as well as at the bank, which had drifted apart although the two bars are the same thing."] = "指向背包格時顯示的是背包本身的提示訊息——品質顏色、容量、物品帶有的一切——下面附上點擊提示，而不再只有一個名字。物品欄視窗與銀行都是如此，先前兩條列雖是同一樣東西卻各走各的。",
    ["The bar in the inventory window takes bags now, the way the one at the bank already did: drag a bag onto a slot to put it there, or left-click a slot with a bag on the cursor. Right-click with an empty hand takes the bag off again, and left-click with an empty hand still shows and hides it. The backpack and the keyring are not slotted bags, so they accept nothing and are not offered the right-click line in the first place."] = "物品欄視窗裡的這條列現在也能接收背包了，和銀行那條早已支援的一樣：把背包拖到某個格上即可裝入該格，游標上拿著背包時左鍵點擊該格也一樣。空手右鍵點擊可把背包取下，空手左鍵點擊仍然是顯示與隱藏。背包本體和鑰匙圈不是裝上去的背包，因此不接收任何東西，也根本不會提供右鍵那一行提示。",
    ["The enchant on the wrist slot sits closer to the rows around it, and the enchant on the weapon sits six pixels lower."] = "護腕格的附魔文字更靠近周圍的行，武器的附魔文字則下移六個像素。",
    ["The trainer tab is a button of its own now. It used to be a spare tab of the spell book that we wrote on with every update, and the book reads those tabs back in the middle of its own pass. It also goes away with the pet book, where it used to stay behind."] = "訓練師標籤現在是獨立的按鈕。先前它是法術書的一個空餘標籤，我們每次更新都會寫它，而法術書會在自己的處理過程中回讀這些標籤。此外它現在會隨寵物法術書一起消失，以前它會留在原地。",
    -- Nameplates: aura border + CC size
    ["Match the health bar height"] = "與生命條同高",
    ["The icon becomes a square exactly as tall as the health bar. The three size sliders below step aside while this is on."] = "圖示變為正方形，高度與生命條完全一致。開啟期間下面三個尺寸滑桿暫不作用。",
    ["Border around aura icons"] = "光環圖示邊框",
    ["The thin rim around debuff, damage-over-time, buff and crowd-control icons. Its thickness follows the border size of the plate."] = "減益、持續傷害、增益與控場效果圖示周圍的細邊。粗細跟隨名條的邊框粗細。",
    ["Aura border colour"] = "光環邊框顏色",
    ["Border in the aura's own school colour"] = "依效果自身的類型顏色描邊",
    ["Magic blue, curse purple, disease orange, poison green — instead of the one colour beside it."] = "魔法藍色、詛咒紫色、疾病橘色、中毒綠色——而不是旁邊的單一顏色。",
    -- Global settings: settings window scale
    ["Settings Window Scale"] = "設定視窗大小",
    ["Scales this settings window on its own. The game's interface keeps the size it has."] = "僅縮放此設定視窗。遊戲介面維持原本的大小。",
    -- Patch notes 1.52.3
    ["Match the health bar height – Makes the crowd-control icon a square exactly as tall as the health bar, in place of its own size sliders"] = "與生命條同高 – 讓控場效果圖示變成與生命條完全等高的正方形，取代它自己的尺寸滑桿",
    ["Border around aura icons – Switches the rim around debuff, damage-over-time, buff and crowd-control icons on or off, with its colour beside it"] = "光環圖示邊框 – 開關減益、持續傷害、增益與控場效果圖示周圍的細邊，顏色就在旁邊",
    ["Text size – Sets how large the unit name and the health value are drawn, in the panel behind each of those two rows"] = "文字大小 – 設定目標名稱與生命數值的繪製大小，位於各自那一行後方的面板中",
    ["A long unit name is trimmed with three dots instead of running through the health value. The two share the bar as soon as both sit inside it, so the name now gets the width that is actually free — and only a health value at the other end takes room away, because sharing one slot is something you did on purpose. Only a name that would overflow is capped at all, which is what keeps the level number glued to the name instead of hanging off an oversized box."] = "過長的目標名稱會以三個點截斷，而不再穿過生命數值。兩者都在條內時便共用同一條，因此名稱現在取得真正空出的寬度——只有位於另一端的生命數值會占走位置，共用同一個位置本來就是你自己的選擇。只有會溢出的名稱才會被限制，這也正是讓等級數字緊貼名稱、而不是掛在過寬方框邊緣的原因。",
    ["The aura border can also take the colour of the aura's own school. That switch was read from the start and had no control anywhere."] = "光環邊框也可以採用效果自身的類型顏色。這個開關一直被讀取，卻在任何地方都沒有對應的控制項。",
    ["Settings Window Scale – Scales this settings window on its own, from 70 to 130 per cent, while the game's interface keeps the size it has"] = "設定視窗大小 – 僅縮放此設定視窗，範圍為百分之七十到百分之一百三十，遊戲介面維持原本的大小",
    ["Making the window smaller now gives it back its full size on a screen that was cutting it off. The fitting measured the room in the game's units and the window in its own, so scaling it down changed nothing about what it was allowed to be."] = "把視窗調小，現在能在原本會裁切它的螢幕上重新取得完整尺寸。先前的調整把空間以遊戲的單位衡量、把視窗以它自己的單位衡量，因此調小並不會改變它被允許占據的大小。",
    -- Nameplates: reverse aura swipe
    ["Reverse the swipe"] = "反向掃描",
    ["The shade grows back as the aura runs out, so a nearly clear icon means it is nearly gone."] = "陰影會隨著光環接近結束重新長回來，因此圖示幾乎乾淨時就表示快要結束了。",
    -- Character panel: socket overwrite confirmation
    ["Replace %s with %s? The gem that comes out is destroyed."] = "將 %s 替換為 %s？取出的寶石會被銷毀。",
    ["That socket has changed — nothing was socketed."] = "該插槽已變動 — 未鑲嵌任何寶石。",
    ["Click to replace the gem — the old one is destroyed."] = "點擊以替換寶石 — 原本的寶石會被銷毀。",
    ["Ask before overwriting a gem"] = "覆寫寶石前先詢問",
    ["A click on a socket that already holds a gem asks first — putting a gem in destroys the one that comes out."] = "點擊已鑲嵌寶石的插槽會先詢問 — 鑲嵌新寶石會銷毀被取出的寶石。",
    -- Loadouts: equipping straight out of the bank
    ["%d of them came out of the bank."] = "其中 %d 件來自銀行。",
    ["in the bank — open the bank window to equip it"] = "在銀行中 — 開啟銀行視窗才能裝備",
    -- Patch notes 1.52.4
    ["Ask before overwriting a gem – A click on a socket that already holds a gem asks first, because putting a gem in destroys the one that comes out"] = "覆寫寶石前先詢問 – 點擊已鑲嵌寶石的插槽會先詢問，因為鑲嵌新寶石會銷毀被取出的那顆",
    ["Pointing at an occupied socket says what a click on it costs. Clicking one was always allowed, nothing ever said so, and the gem that comes out is destroyed. The question names both gems in their quality colours, and it drops the action when the gear moved while it was standing — otherwise a swap under the open dialog would answer for a socket you never looked at."] = "指向已鑲嵌的插槽會說明點擊它的代價。它一直都能點擊，卻從沒有人說過，而被取出的寶石會被銷毀。詢問會以品質顏色列出兩顆寶石，並在視窗停留期間裝備發生變動時放棄操作 — 否則在開啟的視窗下換裝，就會替你從未看過的插槽作答。",
    ["Equipping a set at the bank takes the pieces that are lying in the bank, as long as the bank window is open. Until now they counted as missing, so you could stand at the bank and be told the set was not equippable. The message says how many of them came out of the bank, and the piece that comes off goes into the bank slot the new one came from. With the bank closed, a missing piece in there no longer only names its place, it says to open the bank window."] = "在銀行裝備套組時，只要銀行視窗是開啟的，就會取用放在銀行裡的部件。此前它們算作缺失，於是你站在銀行前，卻被告知套組無法裝備。訊息會說明其中有幾件來自銀行，而脫下的部件會進入新部件原本的銀行格。銀行關閉時，放在裡面的缺失部件不再只說出所在位置，而是提示你開啟銀行視窗。",
    ["The line that tells you which sets an item belongs to appears in item tooltips. It was built and hooked up from the start, but it went in through the one tooltip mechanism this client offers and never uses, so no line was ever drawn and nothing complained."] = "告訴你物品屬於哪些套組的那一行會出現在物品提示中。它從一開始就已建好並掛上，但走的是這個客戶端只提供、從不觸發的那一套提示機制，所以那一行從未被畫出來，也沒有任何錯誤。",
    ["Reverse the swipe – The shade grows back as the aura runs out, so a nearly clear icon means it is nearly gone"] = "反向掃描 – 陰影會隨著光環接近結束重新長回來，因此圖示幾乎乾淨時就表示快要結束了",
    ["The cooldown swipe on the aura icons has a control of its own. It was read from the start and could not be changed anywhere."] = "光環圖示上的冷卻掃描有了自己的開關。它從一開始就被讀取，卻無處可改。",
    ["The raid target marker is visible at all. The eight marks live on one sheet, and the call that picks a tile out of it was working on a frame that never got the sheet — a cut-out of nothing, on every plate and in the preview, since the module was built."] = "團隊標記終於看得見。八個標記放在同一張圖上，而從中挑選格子的呼叫作用在一個從未拿到這張圖的面上 — 從虛無裡裁下一塊，自模組建成起，在每個名條和預覽裡都是如此。",
    ["The raid target marker takes one of the six named slots, like the four aura rows. It had three positions of its own and could land on top of a row, which is the very collision the slots exist for. The old choice moves into the matching slot once and then goes, so there is no second control for the same question. Its room is reserved as soon as it is switched on, not only once a unit really carries a mark, so the rows do not jump every time somebody sets a skull."] = "團隊標記像四行光環那樣占用六個命名位置之一。它原本有三個自己的位置，可能壓在某一行上，而這正是這些位置存在的原因。舊的選擇會一次性遷入對應位置，隨後消失，同一個問題不再有第二處設定。位置在開啟時就被保留，而不是等到目標真的帶上標記才保留，這樣別人每次打個骷髏，各行都不會跳動。",
    ["The marker's own offset and spacing sliders take effect again. They were writing two fields of their own while the plate read the slot, so the visible control was the one without an effect. The old values move across once."] = "標記自己的偏移與間距滑桿重新生效。名條讀取的是位置，而滑桿寫的是自己的兩個欄位，於是看得見的那個設定正是沒有作用的那個。舊的數值會一次性隨之遷移。",
    ["A mark set between two aura passes lands where it belongs. Where the marker goes is worked out in the aura pass, because only that knows how far the rows on its side reach, and the plate now remembers that point for the event that shows the marker on its own."] = "在兩次光環更新之間打上的標記也會落在該在的地方。標記的位置在光環更新中算出，因為只有它知道自己這一側的行延伸到哪裡，名條現在會記住這個點，供單獨顯示標記的事件使用。",
    ["The cast time and the cast target show something in the preview. Both only exist for a cast that is really running on a real unit, so both stayed empty while their switches, colours and side settings stood next to them with nothing to show."] = "施法時間與施法目標在預覽裡有內容了。兩者只在真實目標上真正施法時才產生，所以它們的開關、顏色和方向設定就在旁邊，兩個欄位卻一直是空的。",
    -- Slot picker: the bags moved under an open picker
    ["Your bags moved — pick the item again."] = "背包已變動 — 請重新選擇物品。",
    -- Bar setups: load confirmation, imported macros left alone
    ["Load '%s'? Every button on your bars is overwritten or cleared."] = "載入 '%s'？快捷列上的每個按鈕都會被覆寫或清空。",
    ["Macros: %d restored, %d of your own kept (an import does not rewrite them)."] = "巨集：已恢復 %d 個，保留你自己的 %d 個（匯入不會改寫它們）。",
    -- Patch notes 1.52.5
    ["The enchant text of the wrist slot sits under its slot instead of beside it. The wrist is the last slot of the left column, and to the right of it lies the weapon row, which is where the line was writing."] = "護腕的附魔文字顯示在格子下方，而不是旁邊。護腕是左欄的最後一格，右邊就是武器欄，那正是這行文字原本寫過去的地方。",
    ["Search field in the enchanting window – Leaves only the recipes whose name or reagents match what you type"] = "附魔視窗的搜尋框 – 只保留名稱或材料與輸入內容相符的配方",
    ["The enchanting window is the one profession window that never had a search box. The field sits between the title and the slot dropdown: type into it and only the recipes whose name or one of their reagents matches stay, with the scroll bar shortening along with the list instead of leaving empty rows under the last hit. Recipes you starred still float to the top of what is left, and closing the window clears the text — otherwise the next visit would open on a list with most of the recipes missing and nothing on screen to explain it."] = "附魔視窗是唯一一個從未有過搜尋框的專業視窗。它位於標題與部位下拉選單之間：輸入文字後，只保留名稱或其中一種材料相符的配方，捲軸也會隨清單一起變短，不會在最後一筆結果下方留下空行。標記星號的配方仍會浮到剩餘清單的最上方；關閉視窗時會清空輸入，否則下次打開時會看到一個缺了大半配方的清單，螢幕上卻沒有任何說明。",
    -- Patch notes 1.52.5
    ["Diminishing returns and interrupts recognise every rank of a spell. Both lists carried one identifier per spell, usually the one for rank one, so what is really cast at level seventy fell through: no icon for the polymorph, no bar for the kick. All ranks share their name, and the client knows the name behind every identifier already in the list, so one pass builds a name index that covers every rank at once, in the client's own language, which is the one the combat log speaks."] = "遞減與打斷現在認得法術的每一個等級。兩份清單每個法術只帶一個識別碼，通常是一級的那個，於是七十級真正施放的東西就漏掉了：變形沒有圖示，腳踢沒有條。所有等級共用同一個名稱，而清單裡已有的每個識別碼對應的名稱客戶端都知道，因此一次巡覽就用它們建起一份名稱索引，一次涵蓋全部等級，用的是客戶端自己的語言，也就是戰鬥記錄所講的那一種。",
    ["Loading a setup asks first. It sets a hundred and twenty slots and empties the ones the setup has nothing for, and a single click in the dropdown was enough. The only warning, for a setup belonging to another class, was a chat line that arrived after the damage was done."] = "載入設定會先詢問。它要寫入一百二十個格子，並清空設定中沒有內容的格子，而這原本只需在下拉選單裡點一下。唯一的警告是針對其他職業的設定，而那是一行在損失發生之後才出現的聊天訊息。",
    ["Importing a setup leaves your own macros and keybindings alone. Macros are matched by name, and a name like Pull belongs to everyone, so a foreign setup replaced the contents of your own macro of that name with the switch on by default and without a word about it. Imported setups are marked as foreign now and keep what is already there, and the message says how many were kept. A backup entry carrying no keys at all no longer gets restored either, which used to clear the keys of that command and save the result."] = "匯入設定不再動你自己的巨集和按鍵設定。巨集是按名稱配對的，而像 Pull 這樣的名稱人人都在用，於是別人的設定會取代你同名巨集的內容，開關預設開啟，而且一聲不吭。匯入的設定現在被標記為外來，會保留既有的內容，並在訊息裡說明保留了多少。完全不帶按鍵的備份項目也不再被還原，那以前會清掉該指令的按鍵並把結果存下來。",
    ["The enchant text of a weapon sits above its slot. Beside a weapon there is the next weapon, and to the left the whole text column, so the line had nowhere to go; above the weapon row the paper doll is empty. It is centred over its own slot and wraps upward, so two enchanted weapons no longer write across each other."] = "武器的附魔文字顯示在其格子上方。武器旁邊是下一件武器，左邊是整列文字，這行字無處可去，而武器一排的上方人偶區域是空的。它以自己的格子為中心置中，並向上換行，因此兩件附魔武器不會再互相寫到一起。",
    ["The question before overwriting a gem is only armed once the dialog is really standing. If one was already open the client reuses it, and rebuilding it cleared the note that had just been made, so the second question answered nothing at all and said nothing about it. The recheck now compares the item as well, and an open window on its own no longer counts as proof that it is the right one."] = "覆蓋寶石前的詢問只有在對話框真正立起來之後才生效。若已有一個開啟，客戶端會重新使用它，而重建過程會清掉剛剛做下的記號，於是第二次詢問什麼也沒有回答，還不吭聲。覆核現在也會比對物品，僅憑一個視窗開著不再算作它就是對的那一個的證據。",
    ["The item level of a piece the client has not cached yet appears once it arrives. The retry ran into the very gate that had excluded it and drew nothing, ever. It is capped at twenty attempts per item so it cannot turn into a loop that runs every tenth of a second."] = "客戶端尚未快取的裝備，其裝備等級會在資料抵達時顯示出來。重試落進了當初把它排除掉的那道門，從來沒有畫出任何東西。現在每件物品最多重試二十次，以免變成每十分之一秒一輪的迴圈。",
    ["Deleting an entry removes the one you clicked. It went by the position the row was built with, and the list is rewritten behind the open page whenever the trinket matching adds or removes entries after an equipment change, so the neighbour disappeared instead."] = "刪除項目刪掉的是你點的那一條。它按建立該列時的位置來處理，而每當飾品配對在更換裝備後增刪項目，清單就會在開啟的頁面背後被重寫，於是消失的是相鄰的那條。",
    ["Logging in no longer opens the edit mode behind your back. Restoring frame positions used to apply the layout by showing the client's own edit mode manager, and that rebuilds every system the editor owns out of our call stack, which hands them to the addon for the rest of the session. Measured in game: one such call three seconds after login, and twenty seconds later 1593 refused actions in combat, party and raid frames among them. The layout is still written, and the client applies it the next time it does so itself. A frame you drag by hand still settles immediately."] = "登入不再在你背後開啟編輯模式。還原框體位置時是透過顯示客戶端自己的編輯模式管理員來套用版面的，而它會從我們的呼叫堆疊裡重建編輯器擁有的每一個系統，這樣它們在本次登入期間就歸插件所有了。遊戲內實測：登入三秒後出現一次這樣的呼叫，二十秒後戰鬥中有 1593 次動作被拒絕，其中包括小隊與團隊框體。版面依舊會被儲存，客戶端下次自行套用時會生效。你用手拖曳的框體仍然立刻就位。",
    ["A frame dropped after a fight has started keeps the spot you dropped it at. A drag can only begin out of combat but it can end in one, and letting go wrote the anchor onto a protected frame without asking. The position was already saved by then, so the saved value and the frame on screen would have disagreed for the rest of the session. The write now waits for the fight to end and is made good afterwards."] = "戰鬥開始之後放下的框體會停在你放下的地方。拖曳只能在戰鬥外開始，卻可能在戰鬥中結束，而放手時會不問自取地把錨點寫到受保護的框體上。那時位置已經儲存過了，所以儲存的值和螢幕上的框體會在本次登入餘下的時間裡彼此矛盾。這次寫入現在會等到戰鬥結束後再補上。",
    ["The client settings the fishing mode borrows survive a crash. The backup of your own values lived in memory only, so a reload, a disconnect or a crash while fishing mode was running took it along, and music, ambience, auto loot and soft targeting stayed on the fishing values for good with nothing left anywhere to say what they had been."] = "釣魚模式借用的客戶端設定能挺過一次當機。你原有數值的備份只存在於記憶體裡，因此一次重新載入、一次斷線或釣魚模式執行中的一次當機就會把它一併帶走，音樂、環境音、自動拾取和柔性目標便永遠停在釣魚用的數值上，而原來是什麼樣子哪裡也沒有留下。",
    ["Switching the camera zoom option off returns the zoom to the client's default. The comment promised as much and the code did nothing of the sort, so with the option already on from an earlier session there was no value of ours to fall back to and the maximum stayed for every session after. It is only reset while the value still is our maximum, so anything you have set yourself since then stays."] = "關閉鏡頭拉遠選項會把視距還給客戶端的預設值。註解是這麼承諾的，程式碼卻完全沒做，而如果該選項在更早的登入中就已開啟，就根本沒有屬於我們的數值可退回，最大值於是在此後每次登入裡都留著。只有當數值仍然是我們的最大值時才會還原，所以你自己之後調過的值會保留。",
    ["Unit tooltips no longer throw a Lua error on a unit without an identifier. The fallback one line above did the arithmetic on the missing identifier itself and handed the result to the very call that cannot take it."] = "單位提示不再在沒有識別碼的單位上拋出 Lua 錯誤。上一行的墊底自己拿缺失的識別碼做了運算，又把結果遞給了恰好無法接受它的那個呼叫。",
    ["A set finds its own piece when two items share an identifier, the way the owl's ring and the bear's ring do. Sets store the full reference but searched by the bare identifier; the search goes by identifier and suffix now, while enchants and gems stay out of it because those change during an item's life and would make a set report its own piece as missing."] = "當兩件物品共用一個識別碼時，套裝也能找到自己的那一件，貓頭鷹之戒和熊之戒就是如此。套裝儲存的是完整參照，查找時卻只用光禿禿的識別碼；現在按識別碼加後綴查找，而附魔和寶石被特意排除在外，因為它們在物品的一生中會變，會讓套裝把自己的部件報成缺失。",
    ["The name comes back after a cast the same way the interrupt flash already decides it. A retired field was still being asked, although the options page says it is read nowhere any more."] = "施法結束後名字回來的方式，和打斷閃光早已採用的判斷一致。一個已經停用的欄位仍在被讀取，儘管選項頁面寫著它哪裡都不再讀了。",
    ["The click area of a plate returns to its measured size. The value that means the client's own size was only right as long as the setter had never run, so afterwards the old area stood until a reload and the sliders went up without ever coming back."] = "名條的點擊區域會回到測得的尺寸。那個代表客戶端自身尺寸的值，只有在設定函式從未執行過時才是對的；此後舊的區域會一直保持到重新載入，滑桿只上不回。",
    ["An installation from before the schema stamp runs its migrations instead of skipping them. No stamp meant two opposite things, a fresh installation with nothing to migrate or one older than the stamp with everything still pending, and both were stamped current and skipped, so the older one silently lost every migration, its bar setups in their old storage place among them. The two are told apart now by whether there is any module data at all."] = "早於架構標記的安裝會執行自己的移轉，而不是跳過。沒有標記意味著兩件相反的事：要麼是沒什麼可移轉的全新安裝，要麼是比標記還早、一切都還沒做的安裝，而兩者都被蓋上目前的標記並跳過，於是較早的那一個悄悄丟掉了每一次移轉，包括仍在舊存放位置的快捷列設定。現在透過是否存在任何模組資料來區分兩者。",
    ["The strip for the weapon slots opens downward instead of sideways. The three weapons are the only slots standing in a row rather than a column, at the bottom of the paper doll, where sideways always runs into their own neighbour. It grows away from the middle of the screen so it cannot pass the near edge, and it tips upward when the window sits at the bottom of the screen."] = "武器格子的長條現在向下展開，而不是向旁邊。三個武器格是唯一排成一列而非一行的格子，位於人偶下方，往旁邊展開總會撞上自己的鄰居。它朝遠離螢幕中央的方向生長，因而不會越過就近的邊緣，並在視窗貼著螢幕底部時向上翻。",
    ["A click in the picker can no longer hit whatever has moved into that bag slot in the meantime. It remembered bag and slot from the moment it was filled and listened to no bag event, so after a sort run a click hit what was lying there by then, which with a merchant window open would have been a sale. It follows bag changes now, and every click checks the item in place against the one the button was built for."] = "選擇框裡的點擊不會再打到這期間挪進那個背包格的東西。它只記住填充時的背包和格子，不監聽任何背包事件，所以整理之後點擊打中的是當時躺在那裡的東西，若商人視窗開著，那就會是一次出售。它現在會跟隨背包變化，每次點擊都會把當場的物品與按鈕建立時的那件比對。",
    ["The merchant lock covers both trinket slots. A mixed-up condition left it applying to the lower one only."] = "商人鎖定對兩個飾品格都生效。一個搞反的條件讓它只作用於下面那個。",
    ["The addon no longer stamps the client's own health text and target classification with its taint. Both called the client's updaters from our call stack, the very thing the same file forbids two hundred lines further down in writing and with a reason, which makes the client's next pass over those frames unsafe. Both write what they need themselves now. The standard border returns the moment the client next classifies your target."] = "插件不再用自己的汙染去蓋客戶端的生命值文字和目標分類。兩者都是從我們的呼叫堆疊裡呼叫客戶端的更新函式，而同一個檔案在兩百行之下白紙黑字連理由一起禁止了這件事，它會讓客戶端下一次處理這些框體變得不安全。現在兩者都自己寫需要的內容。標準邊框會在客戶端下次判定你的目標時回來。",
    ["|cffff7777What it costs, and why this is off unless you switch it on: the answer has to sit on a name the client's own protected code reads, which hands the party and raid frames to this addon for the rest of the session. In combat they then refuse to resize and name this addon while doing it. Switching it back off stops it happening again but does not undo the session it already happened in - that takes a reload.|r"] = "|cffff7777這樣做的代價，以及為什麼它預設關閉、要由你自己開啟：這個答案必須放在客戶端受保護程式碼會讀取的名字上，而那會把小隊與團隊框體在本次登入餘下的時間裡交給本插件。此後在戰鬥中它們會拒絕調整大小，並在提示裡點名本插件。重新關閉只能防止再次發生，並不能撤銷已經發生的這次登入，那需要重新載入介面。|r",
    ["not applied - this client does reject the call, so the error is firing"] = "未套用 - 此客戶端確實拒絕該呼叫，因此錯誤正在發生",
    -- Patch notes 1.52.6
    ["X Offset / Y Offset – Nudge the stack and reagent numbers away from their chosen corner; both sit behind the gear of the position row"] = "X 偏移 / Y 偏移 – 把堆疊數和材料數從所選角落推開；兩者都在位置列的齒輪後面",
    ["Opening Edit Mode no longer hands the party and raid frames to the addon for the rest of the session. Merely opening it drove the client's frame editor through the addon, and in combat the client then refused to update those frames, naming the addon in the message. Only really moving one of Blizzard's frames still writes to the editor, and a frame that is hidden, like the focus frame while nothing is focused, never does."] = "開啟編輯模式不再讓隊伍和團隊框體在本次工作階段剩下的時間裡歸插件所有。僅僅是開啟，就會讓客戶端的框體編輯器經過插件執行，之後在戰鬥中客戶端會拒絕更新這些框體，並在訊息裡點出插件的名字。現在只有真正移動暴雪的框體才會寫入編輯器，而隱藏的框體，例如沒有專注目標時的專注框體，永遠不會寫入。",
    ["Opening Edit Mode closes the options window. It sat exactly on top of the boxes it had just unlocked."] = "開啟編輯模式會關閉設定視窗。它正好壓在自己剛剛解鎖的方框上面。",
    ["The equipment list steps aside for the rune engraving panel. That panel opens on the right side of the character sheet, exactly where the list docks, so the two stood on top of each other. The list now follows the panel's edge, and where the screen is too narrow for sheet, panel and list together, it moves to the left side of the sheet."] = "裝備清單會讓路給符文銘刻面板。該面板在角色視窗右側開啟，正是清單停靠的位置，於是兩者疊在一起。清單現在跟著面板的邊緣，螢幕裝不下視窗、面板和清單三者時，它會移到角色視窗的左側。",
    ["The role fix ships switched off. What it fixes is a silent error that truncates one update when a nameplate appears; what it costs is that the party and raid frames count as touched by the addon for the whole session and refuse to resize in combat, with the addon named in the message. That price was reaching players who never chose it, so now only whoever switches the fix on pays it."] = "職責修復預設關閉。它修復的是名條出現時悄悄截斷一次更新的錯誤；它的代價是隊伍和團隊框體整場工作階段都算作被插件碰過，戰鬥中拒絕調整大小，訊息裡還點出插件的名字。這個代價一直由從未選擇它的玩家承擔，現在只有把修復打開的人才付。",
    ["The status line of the role fix tells the whole truth. With the fix off it used to claim it was not needed on this client, even for players who do have the error; it now says whether the fix is applied, not needed, or simply not switched on while the error is firing."] = "職責修復的狀態列說出全部真相。修復關閉時它聲稱此客戶端不需要修復，哪怕玩家確實遇到這個錯誤；現在它會說明修復是已套用、不需要，還是錯誤仍在發生而修復只是沒有打開。",
    ["The bar ships switched off. A second resource bar is a strong opinion to hand someone who never asked for one, and the client already draws its own. Installations that already exist keep the bar exactly as it was."] = "該條預設關閉。把第二條資源條塞給從未要過它的人未免主張太強，而且客戶端本來就畫著自己的一條。已經存在的安裝會讓它保持原樣。",
    ["The dark skin keeps Blizzard's rim off the stance buttons for good. Their updates write the button art back directly, past the hook that guards the action bars, so the rim used to return the first time you switched."] = "深色外觀讓暴雪的邊框永遠遠離姿態按鈕。姿態按鈕的更新繞過守護快捷列的掛鉤，直接把按鈕貼圖寫回去，於是邊框在你第一次切換時就回來了。",
    ["Bonus"] = "加成",
    ["Rating"] = "等級",
    ["Base"] = "基礎",
    ["Block value"] = "格擋值",
    ["Spell Haste"] = "法術加速",
    ["Increases your melee attack power."] = "提高你的近戰攻擊強度。",
    ["Increases your armor, critical strike chance, and chance to dodge."] = "提高你的護甲、致命一擊機率和閃躲機率。",
    ["Increases your maximum health."] = "提高你的最大生命力。",
    ["Increases your maximum mana and spell critical strike chance."] = "提高你的最大法力和法術致命一擊機率。",
    ["Increases your health and mana regeneration."] = "提高你的生命力和法力回復速度。",
    ["Chance for your melee attacks to critically hit."] = "近戰攻擊造成致命一擊的機率。",
    ["Increases your melee attack speed."] = "提高你的近戰攻擊速度。",
    ["Reduces the chance that your melee attacks miss."] = "降低你的近戰攻擊未命中的機率。",
    ["Increases the damage of your spells."] = "提高你的法術傷害。",
    ["Increases the healing done by your spells."] = "提高你的法術治療效果。",
    ["Chance for your spells to critically hit."] = "法術造成致命一擊的機率。",
    ["Reduces the cast time of your spells."] = "縮短你的法術施法時間。",
    ["Reduces the chance that your spells miss."] = "降低你的法術未命中的機率。",
    ["Increases your damage with melee weapons by %.1f damage per second."] = "提高你的近戰武器傷害，相當於每秒%.1f點傷害。",
    ["Reduces physical damage taken by %.2f%% against enemies of your level."] = "降低你受到的物理傷害%.2f%%（對抗與你同等級的敵人）。",
    ["Reduces your chance to be hit and to be critically hit."] = "降低你被擊中和被致命一擊的機率。",
    ["Chance to dodge enemy melee attacks."] = "閃躲敵人近戰攻擊的機率。",
    ["Chance to parry enemy melee attacks."] = "招架敵人近戰攻擊的機率。",
    ["Chance to block enemy melee attacks with your shield."] = "用盾牌格擋敵人近戰攻擊的機率。",
    ["Shadow (darkened Blizzard border)"] = "陰影（暗化的暴雪邊框）",
    ["Standard (Blizzard's own look)"] = "標準（暴雪原版外觀）",
    ["Pick how the action buttons look: Blizzard's own untouched button, the dark Shadow skin, or a masked shape (circle, square, hexagon)."] = "選擇動作按鈕的外觀：暴雪原版按鈕、深色陰影樣式，或遮罩形狀（圓形、方形、六邊形）。",
    ["|cff9b6cffButton border / icon style lives in the Dark Skin module (Action Bars > Bar style): Blizzard's own look, the dark Shadow skin, or masked shapes.|r"] = "|cff9b6cff按鈕外框/圖示樣式位於Dark Skin模組（快捷列 > 快捷列樣式）：暴雪原版外觀、深色陰影樣式，或遮罩形狀。|r",
    ["Circle (masked shape)"] = "圓形（遮罩形狀）",
    ["Square (masked shape)"] = "方形（遮罩形狀）",
    ["Hexagon (masked shape)"] = "六邊形（遮罩形狀）",
    ["WeakAuras style"] = "WeakAuras 樣式",
    ["Style for WeakAuras icons, independent of the action bars."] = "WeakAuras 圖示的樣式，與快捷列各自獨立。",
    ["Shadow 1"] = "Shadow 1",
    ["Shadow 2"] = "Shadow 2",
    ["Shadow 3"] = "Shadow 3",
    ["Shadow 4"] = "Shadow 4",
    ["Shadow 5"] = "Shadow 5",
    ["Border color"] = "外框顏色",
    ["Tints the frame of the Shadow and shape styles. Reset it to get each style's built-in coloring back."] = "為陰影和形狀樣式的外框著色。重置可恢復各樣式的內建顏色。",
    ["Tints the border layer of the aura sets. Reset it to get each set's built-in coloring back."] = "為光環套組的外框層著色。重置可恢復各套組的內建顏色。",
    ["Spell lists"] = "法術清單",
    ["Edit spell lists"] = "編輯法術清單",
    ["Always-show and never-show spell IDs for this row."] = "此列始終顯示或從不顯示的法術ID。",
    ["Always show"] = "始終顯示",
    ["Never show"] = "從不顯示",
    ["Auras on this list always appear in this row, even when its own rules would hide them."] = "此清單中的光環始終顯示在此列，即使該列自身的規則會隱藏它們。",
    ["Auras on this list never appear in this row."] = "此清單中的光環從不顯示在此列。",
    ["No entries yet."] = "尚無條目。",
    ["Unknown spell"] = "未知法術",
    ["Click to switch this entry on or off without deleting it."] = "點擊可開關此條目而不刪除它。",
    ["Mine"] = "自己",
    ["Any"] = "所有",
    ["Counts only your own casts - click to count any caster."] = "僅計算你自己施放的法術，點擊後計算任何施法者。",
    ["Counts any caster - click to count only your own casts."] = "計算任何施法者，點擊後僅計算你自己施放的法術。",
    ["Low-health glow"] = "低血量光效",
    ["Lights the plate up once the unit drops below the chosen health percentage."] = "當單位血量低於所選百分比時點亮名條。",
    ["Thin ring"] = "細邊框",
    ["Pulsing glow"] = "脈動光效",
    ["Low-health percent"] = "低血量百分比",
    -- Patch notes 1.53.0
    ["Every row of the stats sheet now explains itself when you point at it, and spell haste has joined the sheet."] = "屬性表的每一列現在指向時都會自我說明，法術加速也加入了清單。",
    ["Custom class colours moved into the addon's own colour book. Writing them into the client's shared tables marked the party and raid frames as touched by the addon at every login, and the client then refused to resize them in combat. The clean-up has a price: the client's own windows and other addons show the standard class colours again, while the custom ones colour everything this addon draws."] = "自訂職業顏色搬進了插件自己的顏色簿。以前寫入客戶端的共享表格，會在每次登入時把隊伍和團隊框架標記為被插件觸碰，客戶端隨後在戰鬥中拒絕調整它們。清理是有代價的：客戶端自己的視窗和其他插件重新顯示標準職業顏色，而自訂顏色只染這個插件繪製的一切。",
    ["Edit spell lists – Every aura row carries an always-show and a never-show spell ID list, kept in its own editing window behind the slot's fine tuning"] = "編輯法術清單 – 每個光環列都帶有一份始終顯示和一份從不顯示的法術ID清單，在位置微調後面的專屬編輯視窗中管理",
    ["Low-health glow – Marks plates below a chosen health percentage, as a thin ring or a soft pulsing glow, in a colour of your choice"] = "低血量光效 – 將低於所選血量百分比的名條標記為細邊框或柔和的脈動光效，顏色可自選",
    ["The pulsing glow ships as a new texture file, so it takes one full client restart to appear; a reload is not enough."] = "脈動光效作為新的材質檔案提供，因此需要完整重新啟動客戶端才會出現；重載介面並不夠。",
    ["The seal-twist helper no longer counts a swing ahead on parries or when attacking starts; its window used to point at a swing that never came."] = "聖印切換助手不再在招架和開始攻擊時提前計數一次揮擊；它的視窗曾指向一次永遠不會到來的揮擊。",
    ["The import preview no longer sits on top of the paste step of the import dialog."] = "匯入預覽不再蓋住匯入對話框的貼上步驟。",
    ["The clock keeps ticking through abilities that replace the swing, Heroic Strike and Cleave among them: they write their own combat log line instead of a swing line, so the bar used to stand still exactly for the classes that queue such an ability on every swing."] = "時鐘在替換揮擊的技能中繼續走動，其中包括英勇打擊和順劈斬：它們在戰鬥紀錄裡寫下自己的行而不是揮擊行，所以恰恰是每次揮擊都排上這類技能的職業，進度條會停住。",
    ["Swing-resetting spells that deal no damage, parried special attacks and extra attacks now reach the clock too."] = "不造成傷害的揮擊重置法術、被招架的特殊攻擊和額外攻擊現在也能到達時鐘。",
    ["WeakAuras style – A separate icon style for WeakAuras, independent of the action bars, with five Shadow aura sets"] = "WeakAuras 樣式 – 獨立於快捷列的 WeakAuras 圖示樣式，附帶五套 Shadow 光環外觀",
    ["Border color – Tints the frame of the Shadow and shape styles; resetting it restores each style's built-in colouring"] = "外框顏色 – 為 Shadow 和形狀樣式的外框著色；重置後恢復各樣式的內建配色",
    ["The bar style now starts at Blizzard's own untouched look, and the masked shapes circle, square and hexagon bring their own frames."] = "快捷列樣式現在從暴雪原生外觀開始，而遮罩形狀圓形、方形和六邊形帶來自己的外框。",
    -- Action Ring
    ["%d of %d entries"] = "%d / %d 個項目",
    ["360 is a full circle; anything less opens a fan of that width."] = "360 為完整圓形；小於此值則會開啟該寬度的扇形。",
    ["Action Ring"] = "動作環",
    ["Action Ring %d"] = "動作環 %d",
    ["Add an entry that runs a slash command or macro text."] = "新增一個執行斜線指令或巨集文字的項目。",
    ["Add entry"] = "新增項目",
    ["Add new ring"] = "新增動作環",
    ["All %d rings are in use."] = "全部 %d 個動作環皆已使用。",
    ["An extra key that closes the ring without using anything. ESCAPE always works."] = "一個額外的按鍵，可關閉動作環而不使用任何項目。ESCAPE 永遠有效。",
    ["Arc width"] = "弧形寬度",
    ["At the cursor"] = "在游標處",
    ["Bind or change the key that opens this ring."] = "綁定或變更開啟此動作環的按鍵。",
    ["Cancel key: %s"] = "取消鍵：%s",
    ["Clear cancel key"] = "清除取消鍵",
    ["Clear select key"] = "清除選擇鍵",
    ["Click an entry to add it to the ring."] = "點擊項目以將其加入動作環。",
    ["Custom command"] = "自訂指令",
    ["Custom command..."] = "自訂指令...",
    ["Delete ring"] = "刪除動作環",
    ["Distance from centre"] = "與中心的距離",
    ["Edit ring"] = "編輯動作環",
    ["Enable action ring"] = "啟用動作環",
    ["Entries"] = "項目",
    ["Fixed screen position"] = "固定螢幕位置",
    ["Grey out unusable entries"] = "無法使用的項目顯示為灰色",
    ["Hold a keybind to open a ring of actions around the cursor; aim at an entry and release to use it."] = "按住按鍵以在游標周圍開啟動作環；瞄準項目並放開即可使用。",
    ["Horizontal offset"] = "水平位移",
    ["Keep the ring open"] = "保持動作環開啟",
    ["Key %s was bound to '%s' - now opens %s."] = "按鍵 %s 原本綁定於「%s」- 現在會開啟 %s。",
    ["Keybind: %s"] = "按鍵設定：%s",
    ["Macros"] = "巨集",
    ["Markers"] = "標記",
    ["Not bound"] = "未綁定",
    ["Open position"] = "開啟位置",
    ["Opens this ring without a key press. It closes by itself after a while, or press the button again."] = "不需按鍵即可開啟此動作環。它會在一段時間後自動關閉，或再按一次按鈕。",
    ["Press a key... (ESC to cancel)"] = "請按一個按鍵...（ESC 取消）",
    ["Raid marker"] = "團隊標記",
    ["Release to cancel"] = "放開以取消",
    ["Remove marker"] = "移除標記",
    ["Ring name"] = "動作環名稱",
    ["Ring setup"] = "動作環設定",
    ["Select key: %s"] = "選擇鍵：%s",
    ["Show cooldowns"] = "顯示冷卻時間",
    ["Show ring name in the middle"] = "在中央顯示動作環名稱",
    ["Shown in the middle of the ring and in the keybinding list."] = "顯示於動作環中央及按鍵設定清單中。",
    ["Spells"] = "法術",
    ["The key that uses the aimed entry while the ring is kept open. Without it the ring falls back to hold-and-release."] = "在動作環保持開啟時，用來使用所瞄準項目的按鍵。若未設定，動作環將改用按住後放開的方式。",
    ["The ring grows on its own when entries would overlap; this is the smallest size."] = "當項目會重疊時，動作環會自動變大；此為最小尺寸。",
    ["The ring stays open after the key is released. Aim and press the select key to use an entry; ESCAPE or the ring's key closes it."] = "放開按鍵後動作環仍保持開啟。瞄準並按下選擇鍵即可使用項目；按 ESCAPE 或動作環的按鍵可將其關閉。",
    ["This ring is empty - add entries below."] = "此動作環是空的 - 請在下方新增項目。",
    ["This ring is empty - add entries in the options."] = "此動作環是空的 - 請在選項中新增項目。",
    ["This ring is full (%d entries)."] = "此動作環已滿（%d 個項目）。",
    ["Unbind"] = "解除綁定",
    ["|cffaaaaaaHold a keybind to open a ring of actions. Aim at an entry and release the key to use it; release over the middle to cancel. Each ring has its own keybind and its own entries.|r"] = "|cffaaaaaa按住按鍵以開啟動作環。瞄準項目並放開按鍵即可使用；在中央放開則取消。每個動作環都有自己的按鍵與項目。|r",
    -- Action Ring
    ["A dotted line from the centre toward the cursor. Ring layout only."] = "從中心指向游標的虛線。僅限圓環配置。",
    ["A near-square grid keeps the worst pointer travel short."] = "接近正方形的網格能縮短游標最遠的移動距離。",
    ["Apply this look to all rings"] = "將此外觀套用至所有圓環",
    ["Cancel form"] = "取消形態",
    ["Choose columns automatically"] = "自動選擇欄數",
    ["Clear all markers"] = "清除所有標記",
    ["Columns"] = "欄數",
    ["Custom"] = "自訂",
    ["Custom selection colour"] = "自訂選取顏色",
    ["Cycle raid markers"] = "循環切換團隊標記",
    ["Empty ring"] = "空的圓環",
    ["Entries each side"] = "每側項目數",
    ["Hide entries this character cannot use"] = "隱藏此角色無法使用的項目",
    ["Invert scroll direction"] = "反轉捲動方向",
    ["New ring - empty or template"] = "新圓環 - 空白或範本",
    ["Override the look for this ring"] = "覆寫此圓環的外觀",
    ["Ring"] = "圓環",
    ["Select with the mouse"] = "以滑鼠選取",
    ["Selection colour"] = "選取顏色",
    ["Show entry names"] = "顯示項目名稱",
    ["Show pointer needle"] = "顯示指針",
    ["Strip (mouse wheel)"] = "條列（滑鼠滾輪）",
    ["Strip direction"] = "條列方向",
    ["Templates are built from what this character has right now."] = "範本是依據此角色目前擁有的內容建立的。",
    ["The release fires the entry under the pointer; with this off, the wheel's entry fires."] = "放開按鍵時會施放游標所指的項目；關閉此選項後，則施放滾輪選取的項目。",
    ["The shared settings take this ring's values and every ring's own override is removed."] = "共用設定會採用此圓環的數值，並移除每個圓環自己的覆寫。",
    ["Theme colour"] = "主題顏色",
    ["This ring keeps its own layout and display settings; every other ring follows the shared ones above."] = "此圓環保留自己的配置與顯示設定；其他圓環則依照上方的共用設定。",
    ["This ring's own look"] = "此圓環的專屬外觀",
    ["Unknown spells and missing macros are left out of the ring entirely. The stored entries stay for characters that can use them."] = "未習得的法術與不存在的巨集會完全排除在圓環之外。已儲存的項目仍會保留給可以使用的角色。",
    ["|cffaaaaaaTurn the override on to give this ring its own settings.|r"] = "|cffaaaaaa開啟覆寫以讓此圓環擁有自己的設定。|r",
    ["Target markers"] = "目標標記",
    ["Hearthstone"] = "爐石",
    ["Teleports"] = "傳送",
    ["Potions"] = "藥水",
    ["Druid forms"] = "德魯伊形態",
    ["Stances and auras"] = "姿勢與光環",
    ["Quest items"] = "任務物品",
    -- Action Ring
    ["Not in combat - keybinds can't be changed while fighting."] = "戰鬥中無法變更按鍵設定。",
    -- Action Ring
    ["Colour while a swing attack is queued"] = "攻擊排入佇列時上色",
    ["While an on-next-swing attack (Heroic Strike, Cleave, Raptor Strike, Maul) is queued, the bar takes this colour - the resource it will eat is already spoken for."] = "當下次攻擊技能（英勇打擊、順劈斬、猛禽一擊、重毆）排入佇列時，資源條會顯示此顏色——它將消耗的資源已被預留。",
    ["Queued colour"] = "佇列顏色",
    -- Patch notes 1.54.0
    ["Action Ring – Hold a keybind to open a ring of actions, aim at an entry and release to use it, spells, items and macros alike, in and out of combat"] = "動作環 – 按住設定的按鍵即可開啟一個動作環，指向條目後放開按鍵即可使用，法術、物品和巨集一視同仁，戰鬥內外皆可",
    ["Choose between a ring, a grid and a mouse-wheel strip, run up to 16 rings with their own keys, entries and look, and start from ready-made templates such as raid marks, teleports, potions or shapeshifts."] = "可在圓環、網格和滑鼠滾輪條之間選擇，最多可設 16 個動作環，各有自己的按鍵、條目和外觀，還能從團隊標記、傳送、藥水或變形等現成範本開始。",
    ["The options page shows a live preview of the selected ring that redraws while you drag a slider, and a plus button right in the picture adds entries."] = "選項頁面會顯示所選動作環的即時預覽，拖曳滑桿時立即重繪，圖中的加號按鈕可直接加入條目。",
    ["Colour while a swing attack is queued – The resource bar shows a colour of your choice while an on-next-swing attack waits for the hit, so you can see that the resource is already spoken for"] = "攻擊排入佇列時上色 – 當下一擊攻擊排入佇列時，資源條會顯示你選擇的顏色，提醒你這部分資源已被預定",
    ["The low-health glow now reaches further past the plate and rounds its corners more generously; before, it hugged the frame so tightly that it read as a border instead of a glow."] = "低生命值光效現在向名條外延伸得更遠，圓角也更大；之前它緊貼邊框，看起來像框線而不是光效。",
    ["The glow texture changed on disk, so it takes one full client restart to show its new shape; a reload is not enough."] = "光效材質在磁碟上已變更，需要完全重新啟動客戶端才能看到新形狀；重新載入介面並不足夠。",
    ["The bar colour opens a full colour picker instead of a short list of presets; existing profiles keep the colour they had."] = "計時條顏色改為完整的調色器，不再是簡短的預設清單；現有設定檔保留原本的顏色。",
    ["Bar default"] = "列位預設",
    ["Edit glows..."] = "編輯光效...",
    ["Sound when ready"] = "就緒時音效",
    ["Custom icon..."] = "自訂圖示...",
    ["Park this icon (kept, never shown)"] = "擱置此圖示（保留設定，不再顯示）",
    ["Drag to reorder. Right-click opens this icon's settings."] = "拖拉以調整順序。右鍵點擊開啟此圖示的設定。",
    ["Drag to reorder. Right-click an icon for its settings."] = "拖拉以調整順序。右鍵點擊圖示可開啟其設定。",
    ["Custom icon: enter a spell or item ID, or a texture path. Empty returns the real icon."] = "自訂圖示：輸入法術或物品 ID，或材質路徑。留空恢復原始圖示。",
    ["Switching the module off now hands the micro buttons and the bag buttons back to their exact Blizzard positions, and a dialog offers the reload right away; the addon's row layout used to survive into the default bars until the next reload."] = "關閉模組時，微型按鈕和背包按鈕會精確回到暴雪的原始位置，並跳出對話框提示立即重載介面；先前插件的排列會殘留在預設動作條上，直到下次重載。",
    ["Sound when ready – Every icon can announce the end of its cooldown with a sound from the shared media list, auditioned right in the menu with every click"] = "就緒時音效 – 每個圖示都可以在冷卻結束時播放共享媒體清單中的音效，在選單中每次點擊即可試聽",
    ["Custom icon... – Any entry can wear an icon of your choice, named by spell or item ID or a texture path"] = "自訂圖示... – 任一條目都可以使用你選擇的圖示，透過法術或物品 ID 或材質路徑指定",
    ["Right-clicking an icon in the preview strip opens a settings menu for that one entry: glow while ready with its own colour, the ready flash, the dimming, the cooldown swipe and the countdown text can each override the bar's setting, and the glow editor, parking and removing live in the same place. Removing is no longer the bare right-click itself, so a stray click cannot shorten the bar."] = "右鍵點擊預覽條中的圖示會開啟僅針對該條目的設定選單：就緒時發光及其顏色、就緒閃光、冷卻變暗、冷卻掃描和倒數文字都可以逐項覆蓋該列的設定，光效編輯器、擱置和移除也在同一處。移除不再是單純的右鍵點擊本身，誤點不會再縮短該列。",
    ["Long popup menus, the module list on the minimap button among them, now show a window that scrolls with the mouse wheel instead of growing past the screen edge."] = "過長的彈出選單（包括小地圖按鈕上的模組清單）現在會顯示一個可用滑鼠滾輪捲動的視窗，而不是超出螢幕邊緣。",
    ["Helm"] = "頭盔",
    ["Cloak"] = "披風",
    ["Don't change"] = "不更改",
    ["shown"] = "顯示",
    ["hidden"] = "隱藏",
    ["Resilience"] = "韌性",
    ["Reduces the chance to be critically hit and the damage taken from critical strikes."] = "降低受到致命一擊的機率以及所受的致命一擊傷害。",
    -- Patch notes 1.56.0
    ["Keeping the main bar on its page in every form now also holds the standard main bar, even while the whole module is off. The keys fire exactly what the buttons show, and switching to bars 2 to 6 by hand still works."] = "在所有形態下把主快捷列按在原頁的開關，現在也作用於標準主快捷列，即使整個模組已關閉。按鍵觸發的正是按鈕顯示的內容，手動切換到第 2 到第 6 條快捷列照樣可用。",
    ["The stats sheet shows resilience under Defense, with the rating and its percent effect in the tooltip."] = "屬性面板在防禦之下顯示韌性，滑鼠提示裡給出數值和它的百分比效果。",
    ["The enchant text on the equipment slots no longer falls onto the green armor line of pieces with built-in bonus armor; that line only stands in when no real enchant follows."] = "裝備欄位的附魔文字不再落到自帶額外護甲的部位的綠色護甲行上；只有在沒有真正的附魔時，那一行才會頂替進來。",
    ["Helm / Cloak – Each set can show, hide or leave untouched the helm and the cloak as it is equipped, chosen in the row's right-click menu, and the row tooltip names the choice"] = "頭盔 / 披風 – 每個套裝在穿戴時可以顯示、隱藏或不更動頭盔和披風，在該列的右鍵選單裡選擇，列的滑鼠提示會說明所選狀態",
    ["The set rows can be reordered with the left mouse button held down: a translucent ghost follows the pointer, a line in the accent colour marks where the row will land, and letting go outside the list cancels. Existing sets keep their alphabetical order as the starting point, new ones join at the end."] = "套裝列可以按住滑鼠左鍵重新排序：一個半透明的殘影跟著指標，一條強調色的線標出該列將落下的位置，在清單外放開則取消。既有套裝以原本的字母順序為起點，新套裝排在最後。",
    ["The red auto-attack blink sits exactly on the icon in the skinned button styles and is cut to the same shape; it used to be drawn for the standard button art and blinked beside the icon."] = "紅色的自動攻擊閃爍在換裝按鈕樣式裡正好落在圖示上，並按同樣的形狀裁剪；它原本是為標準按鈕外觀繪製的，閃在圖示旁邊。",
    ["Popup dialogs measure their frame with the font that is really drawn; with long texts the buttons used to hang below the border."] = "對話框用真正繪製的字型來測量邊框；文字很長時，按鈕曾懸在邊框之下。",
} end)
